window.TET_DATA_PHYSICS = [{"id": 1, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "The speed of a car is 36 km/h. Its speed in m/s", "q_te": "ఒక కారు వడి 36 కి.మీ/గం. దాని వడి మీ/సె లలో", "opts": [{"en": "18", "te": "18"}, {"en": "72", "te": "72"}, {"en": "5", "te": "5"}, {"en": "10", "te": "10"}], "ans": 4, "exp_en": "36 kmph = 36 × (5/18) = 10 m/s.", "exp_te": "36 కి.మీ/గం = 36 × (5/18) = 10 మీ/సె."}, {"id": 2, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "A car travels 16 m in 3 s and another 16 m in 5 s. The average speed of the car is (in m/s)", "q_te": "ఒక కారు 3 సె. లలో 16 మీ. ప్రయాణిస్తుంది. ఆ పై మరొక 5 సె. లలో మరో 16 మీ. ప్రయాణిస్తే, ఆ కారు సరాసరి వడి (మీ/సె లలో)", "opts": [{"en": "8", "te": "8"}, {"en": "6", "te": "6"}, {"en": "4", "te": "4"}, {"en": "2", "te": "2"}], "ans": 3, "exp_en": "Total distance = 32 m, total time = 8 s. Average speed = 32 ÷ 8 = 4 m/s.", "exp_te": "మొత్తం దూరం = 32 మీ, మొత్తం కాలం = 8 సె. సరాసరి వడి = 32 ÷ 8 = 4 మీ/సె."}, {"id": 3, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "The formula for average velocity is", "q_te": "సరాసరి వేగానికి సూత్రం", "opts": [{"en": "Initial velocity + Final velocity", "te": "తొలి వేగం + తుది వేగం"}, {"en": "Initial velocity − Final velocity", "te": "తొలి వేగం − తుది వేగం"}, {"en": "$\\frac{\\text{Initial velocity + Final velocity}}{2}$", "te": "$\\frac{\\text{తొలి వేగం + తుది వేగం}}{2}$"}, {"en": "$\\frac{\\text{Initial velocity − Final velocity}}{2}$", "te": "$\\frac{\\text{తొలి వేగం − తుది వేగం}}{2}$"}], "ans": 3, "exp_en": "For uniform acceleration, average velocity = (u + v)/2.", "exp_te": "ఏకరీతి త్వరణంలో సరాసరి వేగం = (తొలి వేగం + తుది వేగం)/2."}, {"id": 4, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "The units of acceleration in S.I. system", "q_te": "S.I పద్ధతిలో త్వరణానికి ప్రమాణాలు", "opts": [{"en": "m", "te": "m"}, {"en": "m/s", "te": "m/s"}, {"en": "$m/s^2$", "te": "$m/s^2$"}, {"en": "$m\\,s^2$", "te": "$m\\,s^2$"}], "ans": 3, "exp_en": "Acceleration = change in velocity ÷ time = (m/s) ÷ s = m/s<sup>2</sup>.", "exp_te": "త్వరణం = వేగ మార్పు ÷ కాలం = (మీ/సె) ÷ సె = మీ/సె<sup>2</sup>."}, {"id": 5, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "The initial velocity of a freely falling object is", "q_te": "స్వేచ్ఛాపతన వస్తువు తొలి వేగం", "opts": [{"en": "Zero", "te": "సున్నా"}, {"en": "Maximum", "te": "గరిష్ఠం"}, {"en": "One", "te": "ఒకటి"}, {"en": "Cannot say", "te": "చెప్పలేము"}], "ans": 1, "exp_en": "A freely falling body starts from rest, so its initial velocity is zero.", "exp_te": "స్వేచ్ఛా పతన వస్తువు నిశ్చల స్థితి నుండి మొదలవుతుంది, కాబట్టి తొలి వేగం శూన్యం."}, {"id": 6, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "An athlete is running in a circular track of radius 120 m and reaches the starting point in 1 minute. The displacement of the athlete is (in metres)", "q_te": "ఒక క్రీడాకారుడు 120 మీ. వ్యాసార్థం గల వృత్తాకార ట్రాక్‌లో పరిగెత్తి 1 నిమిషంలో బయలుదేరిన బిందువుకు చేరాడు. అతని స్థానభ్రంశం (మీ. లలో)", "opts": [{"en": "120", "te": "120"}, {"en": "60", "te": "60"}, {"en": "2", "te": "2"}, {"en": "0", "te": "0"}], "ans": 4, "exp_en": "Displacement is the straight distance between start and end points. Here both are the same point, so it is 0.", "exp_te": "స్థానభ్రంశం అంటే ప్రారంభ, తుది బిందువుల మధ్య సరళ దూరం. ఇక్కడ రెండూ ఒకే బిందువు కాబట్టి 0."}, {"id": 7, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "In the formula $v^2 - u^2 = 2as$, ‘a’ represents", "q_te": "$v^2 - u^2 = 2as$ సూత్రంలో ‘a’ దేనిని సూచిస్తుంది", "opts": [{"en": "Initial velocity", "te": "తొలి వేగం"}, {"en": "Final velocity", "te": "తుది వేగం"}, {"en": "Acceleration", "te": "త్వరణం"}, {"en": "Distance", "te": "దూరం"}], "ans": 3, "exp_en": "In the equations of motion u is initial velocity, v final velocity, a acceleration and s displacement.", "exp_te": "చలన సమీకరణాలలో u తొలి వేగం, v తుది వేగం, a త్వరణం, s స్థానభ్రంశం."}, {"id": 8, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "A train starting from rest gains a velocity 20 m/s in 5 seconds. The acceleration of the train is (in $m/s^2$)", "q_te": "విశ్రాంతి స్థితి నుండి బయలుదేరిన రైలు బండి 5 సెకన్లలో 20 మీ/సె వేగాన్ని పొందింది. రైలు త్వరణం ($m/s^2$ లలో)", "opts": [{"en": "2", "te": "2"}, {"en": "4", "te": "4"}, {"en": "6", "te": "6"}, {"en": "8", "te": "8"}], "ans": 2, "exp_en": "a = (v − u)/t = (20 − 0)/5 = 4 m/s<sup>2</sup>.", "exp_te": "త్వరణం = (తుది వేగం − తొలి వేగం)/కాలం = (20 − 0)/5 = 4 మీ/సె<sup>2</sup>."}, {"id": 9, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "Five kilometres is equal to (in m)", "q_te": "ఐదు కిలోమీటర్లు (మీ. లలో)", "opts": [{"en": "5", "te": "5"}, {"en": "50", "te": "50"}, {"en": "500", "te": "500"}, {"en": "5000", "te": "5000"}], "ans": 4, "exp_en": "1 km = 1000 m, so 5 km = 5000 m.", "exp_te": "1 కి.మీ = 1000 మీ, కాబట్టి 5 కి.మీ = 5000 మీ."}, {"id": 10, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "Motion of the needle of a sewing machine is", "q_te": "కుట్టు మిషను సూది చలనం", "opts": [{"en": "Rectilinear motion", "te": "సరళరేఖా చలనం"}, {"en": "Oscillatory motion", "te": "డోలనా చలనం"}, {"en": "Rotatory motion", "te": "భ్రమణ చలనం"}, {"en": "Circulatory motion", "te": "వృత్తాకార చలనం"}], "ans": 2, "exp_en": "The needle moves up and down repeatedly about a mean position — oscillatory motion.", "exp_te": "సూది ఒక మధ్య స్థానం చుట్టూ పైకి కిందికి పునరావృతంగా కదులుతుంది — డోలన చలనం."}, {"id": 11, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "While measuring the length of a knitting needle, the reading of the scale at one end is 3.0 cm and at the other end is 33.1 cm. The length of the needle is (in cm)", "q_te": "అల్లిక సూది పొడవు కొలిచేటప్పుడు స్కేలు రీడింగ్ ఒక చివర 3.0 సెం.మీ, మరొక చివర 33.1 సెం.మీ. సూది పొడవు (సెం.మీ లలో)", "opts": [{"en": "3.1", "te": "3.1"}, {"en": "36.1", "te": "36.1"}, {"en": "30.1", "te": "30.1"}, {"en": "11.1", "te": "11.1"}], "ans": 3, "exp_en": "Length = 33.1 − 3.0 = 30.1 cm.", "exp_te": "పొడవు = 33.1 − 3.0 = 30.1 సెం.మీ."}, {"id": 12, "sec": "చలనం, కొలతలు | Motion & Measurement", "passage": "", "q_en": "The correct order of the following lengths", "q_te": "క్రింది పొడవుల సరైన క్రమం", "opts": [{"en": "1cm < 1mm < 1m < 1km", "te": "1cm < 1mm < 1m < 1km"}, {"en": "1mm < 1cm < 1m < 1km", "te": "1mm < 1cm < 1m < 1km"}, {"en": "1km < 1m < 1cm < 1mm", "te": "1km < 1m < 1cm < 1mm"}, {"en": "1km < 1m < 1mm < 1cm", "te": "1km < 1m < 1mm < 1cm"}], "ans": 2, "exp_en": "1 mm = 0.1 cm, 1 cm = 0.01 m, 1 m = 0.001 km, so mm &lt; cm &lt; m &lt; km.", "exp_te": "1 మి.మీ = 0.1 సెం.మీ, 1 సెం.మీ = 0.01 మీ, 1 మీ = 0.001 కి.మీ, కాబట్టి మి.మీ &lt; సెం.మీ &lt; మీ &lt; కి.మీ."}, {"id": 13, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The frictional force between a wooden box and the floor is 20 N. The force required to move the wooden box is", "q_te": "చెక్క పెట్టె, నేల మధ్య ఘర్షణ బలం 20 N. పెట్టెను కదిలించడానికి కావలసిన బలం", "opts": [{"en": "10 N", "te": "10 N"}, {"en": "15 N", "te": "15 N"}, {"en": "21 N", "te": "21 N"}, {"en": "0 N", "te": "0 N"}], "ans": 3, "exp_en": "To move the box the applied force must be greater than the friction of 20 N, so 21 N is needed.", "exp_te": "పెట్టెను కదిలించాలంటే ప్రయోగించే బలం 20 N ఘర్షణ కన్నా ఎక్కువ ఉండాలి, కాబట్టి 21 N కావాలి."}, {"id": 14, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "If the force applied on the object is in the direction of motion, then the speed of the object", "q_te": "వస్తువుపై ప్రయోగించిన బలం చలన దిశలోనే ఉంటే వస్తువు వడి", "opts": [{"en": "Increases", "te": "పెరుగుతుంది"}, {"en": "Decreases", "te": "తగ్గుతుంది"}, {"en": "First increases and then decreases", "te": "మొదట పెరిగి తర్వాత తగ్గుతుంది"}, {"en": "First decreases and then increases", "te": "మొదట తగ్గి తర్వాత పెరుగుతుంది"}], "ans": 1, "exp_en": "A force acting along the direction of motion accelerates the body, so speed increases.", "exp_te": "చలన దిశలో పనిచేసే బలం వస్తువును త్వరణం చేస్తుంది, కాబట్టి వడి పెరుగుతుంది."}, {"id": 15, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The force applied by an archer to stretch the bow is an example of", "q_te": "విలుకాడు విల్లును సాగదీయడానికి ప్రయోగించే బలం దీనికి ఉదాహరణ", "opts": [{"en": "Frictional force", "te": "ఘర్షణ బలం"}, {"en": "Muscular force", "te": "కండర బలం"}, {"en": "Gravitational force", "te": "గురుత్వాకర్షణ బలం"}, {"en": "Magnetic force", "te": "అయస్కాంత బలం"}], "ans": 2, "exp_en": "Force produced by the muscles of the body is muscular force.", "exp_te": "శరీర కండరాల ద్వారా ఉత్పన్నమయ్యే బలం కండర బలం."}, {"id": 16, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "Pressure is the ratio of force and", "q_te": "పీడనం అనేది బలానికి, దీనికి గల నిష్పత్తి", "opts": [{"en": "Area", "te": "వైశాల్యం"}, {"en": "Volume", "te": "ఘనపరిమాణం"}, {"en": "Density", "te": "సాంద్రత"}, {"en": "Length", "te": "పొడవు"}], "ans": 1, "exp_en": "Pressure = Force ÷ Area.", "exp_te": "పీడనం = బలం ÷ వైశాల్యం."}, {"id": 17, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The force exerted by a charged body on another charged body is known as", "q_te": "ఒక ఆవేశిత వస్తువు మరొక ఆవేశిత వస్తువుపై కలుగజేసే బలం", "opts": [{"en": "Muscular force", "te": "కండర బలం"}, {"en": "Frictional force", "te": "ఘర్షణ బలం"}, {"en": "Electrostatic force", "te": "స్థిర విద్యుత్ బలం"}, {"en": "Magnetic force", "te": "అయస్కాంత బలం"}], "ans": 3, "exp_en": "The force between charges at rest is the electrostatic force.", "exp_te": "నిశ్చల ఆవేశాల మధ్య పనిచేసే బలం స్థావర విద్యుత్ బలం."}, {"id": 18, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "This is an example of non-contact force", "q_te": "స్పర్శరహిత బలానికి ఉదాహరణ", "opts": [{"en": "Muscular force", "te": "కండర బలం"}, {"en": "Frictional force", "te": "ఘర్షణ బలం"}, {"en": "Gravitational force", "te": "గురుత్వాకర్షణ బలం"}, {"en": "Tension force", "te": "తన్యతా బలం"}], "ans": 3, "exp_en": "Gravity acts without any contact between the bodies, so it is a non-contact force.", "exp_te": "గురుత్వాకర్షణ వస్తువుల మధ్య స్పర్శ లేకుండానే పనిచేస్తుంది, కాబట్టి స్పర్శించని బలం."}, {"id": 19, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "This is an example of contact force", "q_te": "స్పర్శ బలానికి ఉదాహరణ", "opts": [{"en": "Muscular force", "te": "కండర బలం"}, {"en": "Gravitational force", "te": "గురుత్వాకర్షణ బలం"}, {"en": "Electrostatic force", "te": "స్థిర విద్యుత్ బలం"}, {"en": "Magnetic force", "te": "అయస్కాంత బలం"}], "ans": 1, "exp_en": "Muscular force can act only when the body touches the object, so it is a contact force.", "exp_te": "కండర బలం వస్తువును తాకినప్పుడే పనిచేస్తుంది, కాబట్టి అది స్పర్శ బలం."}, {"id": 20, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "This is not an example of muscular force", "q_te": "కండర బలానికి ఉదాహరణ కానిది", "opts": [{"en": "Squeezing a piece of lemon between fingers", "te": "వేళ్ళ మధ్య నిమ్మకాయ ముక్కను పిండటం"}, {"en": "Taking out toothpaste from toothpaste tube", "te": "ట్యూబు నుండి టూత్‌పేస్ట్ బయటకు తీయడం"}, {"en": "Lifting the bucket containing water with hands", "te": "నీటి బకెట్‌ను చేతులతో ఎత్తడం"}, {"en": "Charged balloon attracting the pieces of paper", "te": "ఆవేశిత బెలూన్ కాగితం ముక్కలను ఆకర్షించడం"}], "ans": 4, "exp_en": "The balloon attracts paper by electrostatic force, not by muscles.", "exp_te": "బెలూన్ కాగితాన్ని స్థావర విద్యుత్ బలంతో ఆకర్షిస్తుంది, కండరాలతో కాదు."}, {"id": 21, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The decreasing order of frictional forces", "q_te": "ఘర్షణ బలాల అవరోహణ క్రమం", "opts": [{"en": "rolling, static, sliding", "te": "దొర్లుడు, స్థైతిక, జారుడు"}, {"en": "rolling, sliding, static", "te": "దొర్లుడు, జారుడు, స్థైతిక"}, {"en": "static, sliding, rolling", "te": "స్థైతిక, జారుడు, దొర్లుడు"}, {"en": "sliding, static, rolling", "te": "జారుడు, స్థైతిక, దొర్లుడు"}], "ans": 3, "exp_en": "Static friction &gt; sliding friction &gt; rolling friction.", "exp_te": "స్థైతిక ఘర్షణ &gt; జారుడు ఘర్షణ &gt; దొర్లుడు ఘర్షణ."}, {"id": 22, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The reason for sprinkling powder on the carom board", "q_te": "క్యారమ్ బోర్డుపై పౌడరు చల్లడానికి కారణం", "opts": [{"en": "To increase the friction", "te": "ఘర్షణ పెంచుటకు"}, {"en": "To decrease the friction", "te": "ఘర్షణ తగ్గించుటకు"}, {"en": "To decorate the carom board", "te": "అలంకరణకు"}, {"en": "To decrease force", "te": "బలం తగ్గించుటకు"}], "ans": 2, "exp_en": "The powder makes the surface smoother, reducing friction so the coins slide easily.", "exp_te": "పౌడర్ తలాన్ని నునుపుగా చేసి ఘర్షణను తగ్గిస్తుంది, కాయిన్లు సులభంగా జారతాయి."}, {"id": 23, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The correct statement among the following", "q_te": "క్రింది వాటిలో సరైన ప్రవచనం", "opts": [{"en": "Rolling friction is smaller than sliding friction", "te": "దొర్లుడు ఘర్షణ జారుడు ఘర్షణ కంటే తక్కువ"}, {"en": "Sliding friction is smaller than rolling friction", "te": "జారుడు ఘర్షణ దొర్లుడు ఘర్షణ కంటే తక్కువ"}, {"en": "Rolling friction is equal to sliding friction", "te": "రెండూ సమానం"}, {"en": "Rolling friction is larger than sliding friction", "te": "దొర్లుడు ఘర్షణ ఎక్కువ"}], "ans": 1, "exp_en": "Rolling friction is always the least, which is why wheels are used.", "exp_te": "దొర్లుడు ఘర్షణ ఎప్పుడూ అత్యల్పం, అందుకే చక్రాలు వాడతారు."}, {"id": 24, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The reason that tyres are treaded", "q_te": "టైర్లపై గాడులు (నమూనాలు) ఉండడానికి కారణం", "opts": [{"en": "To decrease the friction", "te": "ఘర్షణ తగ్గించుటకు"}, {"en": "To increase the friction", "te": "ఘర్షణ పెంచుటకు"}, {"en": "To look good", "te": "అందంగా కనిపించుటకు"}, {"en": "To increase speed", "te": "వడి పెంచుటకు"}], "ans": 2, "exp_en": "Treads increase the grip (friction) between the tyre and the road.", "exp_te": "గాడులు టైరుకు, రోడ్డుకు మధ్య పట్టు (ఘర్షణ) ను పెంచుతాయి."}, {"id": 25, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "S.I. unit of universal gravitational constant (G) is", "q_te": "విశ్వ గురుత్వాకర్షణ స్థిరాంకం (G) యొక్క S.I ప్రమాణం", "opts": [{"en": "$N\\,m^2\\,kg^2$", "te": "$N\\,m^2\\,kg^2$"}, {"en": "$N\\,m^2\\,kg^{-2}$", "te": "$N\\,m^2\\,kg^{-2}$"}, {"en": "$N\\,m^{-2}\\,kg^2$", "te": "$N\\,m^{-2}\\,kg^2$"}, {"en": "$N\\,m^{-2}\\,kg^{-2}$", "te": "$N\\,m^{-2}\\,kg^{-2}$"}], "ans": 2, "exp_en": "From F = Gm₁m₂/r<sup>2</sup>, G = Fr<sup>2</sup>/m₁m₂ → N m<sup>2</sup> kg<sup>−2</sup>.", "exp_te": "F = Gm₁m₂/r<sup>2</sup> నుండి G = Fr<sup>2</sup>/m₁m₂ → N మీ<sup>2</sup> కి.గ్రా<sup>−2</sup>."}, {"id": 26, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The value of ‘g’ on earth", "q_te": "భూమిపై ‘g’ విలువ", "opts": [{"en": "$9.8\\,ms^{-2}$", "te": "$9.8\\,ms^{-2}$"}, {"en": "$9.8\\,cms^{-2}$", "te": "$9.8\\,cms^{-2}$"}, {"en": "$98\\,ms^{-2}$", "te": "$98\\,ms^{-2}$"}, {"en": "$98\\,cms^{-2}$", "te": "$98\\,cms^{-2}$"}], "ans": 1, "exp_en": "The acceleration due to gravity on the earth's surface is about 9.8 m/s<sup>2</sup>.", "exp_te": "భూ ఉపరితలంపై గురుత్వ త్వరణం సుమారు 9.8 మీ/సె<sup>2</sup>."}, {"id": 27, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "If the weight of an object is 60 N on earth, then the weight of the same object on moon is", "q_te": "భూమిపై ఒక వస్తువు భారం 60 N అయితే, చంద్రునిపై అదే వస్తువు భారం", "opts": [{"en": "6 N", "te": "6 N"}, {"en": "10 N", "te": "10 N"}, {"en": "0 N", "te": "0 N"}, {"en": "36 N", "te": "36 N"}], "ans": 2, "exp_en": "The moon's gravity is 1/6 of the earth's, so weight = 60 ÷ 6 = 10 N.", "exp_te": "చంద్రుని గురుత్వం భూమిలో 1/6 వంతు, కాబట్టి భారం = 60 ÷ 6 = 10 N."}, {"id": 28, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The mass of an object is 10 kg. The weight of the object on the earth is ($g = 9.8\\,m/s^2$)", "q_te": "ఒక వస్తువు ద్రవ్యరాశి 10 కి.గ్రా. భూమిపై దాని భారం ($g = 9.8\\,m/s^2$)", "opts": [{"en": "9.8 N", "te": "9.8 N"}, {"en": "0.2 N", "te": "0.2 N"}, {"en": "98 N", "te": "98 N"}, {"en": "0 N", "te": "0 N"}], "ans": 3, "exp_en": "Weight W = mg = 10 × 9.8 = 98 N.", "exp_te": "భారం = ద్రవ్యరాశి × g = 10 × 9.8 = 98 N."}, {"id": 29, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The thrust per unit area is called", "q_te": "ప్రమాణ వైశాల్యంపై కలుగజేసే ఒత్తిడిని ఈ విధంగా పిలుస్తారు", "opts": [{"en": "Force", "te": "బలం"}, {"en": "Pressure", "te": "పీడనం"}, {"en": "Weight", "te": "భారం"}, {"en": "Mass", "te": "ద్రవ్యరాశి"}], "ans": 2, "exp_en": "Pressure = Thrust ÷ Area.", "exp_te": "పీడనం = తోపుడు ÷ వైశాల్యం."}, {"id": 30, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "S.I. unit of pressure is", "q_te": "పీడనానికి S.I ప్రమాణం", "opts": [{"en": "Newton", "te": "న్యూటన్"}, {"en": "Pascal", "te": "పాస్కల్"}, {"en": "dyne", "te": "డైన్"}, {"en": "Watt", "te": "వాట్"}], "ans": 2, "exp_en": "1 pascal = 1 newton per square metre.", "exp_te": "1 పాస్కల్ = చదరపు మీటరుకు 1 న్యూటన్."}, {"id": 31, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "A stone is released from the top of a tower of height 20 m. The final velocity before touching the ground is ($g = 10\\,m/s^2$)", "q_te": "20 మీ ఎత్తు గల టవర్ పై నుండి ఒక రాయిని వదిలారు. నేలను తాకే ముందు దాని తుది వేగం ($g = 10\\,m/s^2$)", "opts": [{"en": "0 m/s", "te": "0 m/s"}, {"en": "10 m/s", "te": "10 m/s"}, {"en": "20 m/s", "te": "20 m/s"}, {"en": "40 m/s", "te": "40 m/s"}], "ans": 3, "exp_en": "v<sup>2</sup> = u<sup>2</sup> + 2gh = 0 + 2 × 10 × 20 = 400 → v = 20 m/s.", "exp_te": "v<sup>2</sup> = u<sup>2</sup> + 2gh = 0 + 2 × 10 × 20 = 400 → v = 20 మీ/సె."}, {"id": 32, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The buoyant force acts on an object immersed in a liquid in this direction", "q_te": "ద్రవంలో మునిగిన వస్తువుపై ఉత్ప్లవన బలం పనిచేసే దిశ", "opts": [{"en": "Upward direction", "te": "పై దిశలో"}, {"en": "Downward direction", "te": "కింది దిశలో"}, {"en": "Towards right", "te": "కుడి వైపు"}, {"en": "Towards left", "te": "ఎడమ వైపు"}], "ans": 1, "exp_en": "Buoyant force always acts vertically upwards.", "exp_te": "ఉత్ప్లవన బలం ఎప్పుడూ నిలువుగా పైకి పనిచేస్తుంది."}, {"id": 33, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The principle used in the designing of ships and submarines", "q_te": "ఓడలు, జలాంతర్గాముల రూపకల్పనలో ఉపయోగించే సూత్రం", "opts": [{"en": "Newton’s principle", "te": "న్యూటన్ సూత్రం"}, {"en": "Pascal’s principle", "te": "పాస్కల్ సూత్రం"}, {"en": "Archimedes’ principle", "te": "ఆర్కిమెడిస్ సూత్రం"}, {"en": "Boyle’s principle", "te": "బాయిల్ సూత్రం"}], "ans": 3, "exp_en": "Archimedes' principle of buoyancy explains floating and sinking.", "exp_te": "ఆర్కిమెడిస్ ఉత్ప్లవన సూత్రం తేలడం, మునగడాన్ని వివరిస్తుంది."}, {"id": 34, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "A: Mass of a body does not change from place to place.\nB: Weight of a body changes from place to place.", "q_te": "A: వస్తువు ద్రవ్యరాశి ప్రదేశాన్ని బట్టి మారదు.\nB: వస్తువు భారం ప్రదేశాన్ని బట్టి మారుతుంది.", "opts": [{"en": "Both A and B are correct", "te": "A, B రెండూ సరైనవి"}, {"en": "Both A and B are incorrect", "te": "A, B రెండూ సరికావు"}, {"en": "A is correct, B is incorrect", "te": "A సరైనది, B సరికాదు"}, {"en": "A is incorrect, B is correct", "te": "A సరికాదు, B సరైనది"}], "ans": 1, "exp_en": "Mass is constant everywhere; weight = mg changes as g changes from place to place.", "exp_te": "ద్రవ్యరాశి అన్నిచోట్లా స్థిరం; భారం = mg, g మారితే భారం మారుతుంది."}, {"id": 35, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "According to Newton’s universal law of gravitation, the force acting between two bodies is", "q_te": "న్యూటన్ విశ్వ గురుత్వాకర్షణ నియమం ప్రకారం రెండు వస్తువుల మధ్య బలం", "opts": [{"en": "Directly proportional to the square of the distance", "te": "దూరవర్గానికి అనులోమానుపాతంలో"}, {"en": "Inversely proportional to the square of the distance", "te": "దూరవర్గానికి విలోమానుపాతంలో"}, {"en": "Directly proportional to the distance", "te": "దూరానికి అనులోమానుపాతంలో"}, {"en": "Inversely proportional to the distance", "te": "దూరానికి విలోమానుపాతంలో"}], "ans": 2, "exp_en": "F = Gm₁m₂/r<sup>2</sup>, so F is inversely proportional to r<sup>2</sup>.", "exp_te": "F = Gm₁m₂/r<sup>2</sup>, కాబట్టి బలం దూరవర్గానికి విలోమానుపాతం."}, {"id": 36, "sec": "బలం, ఘర్షణ, గురుత్వాకర్షణ, పీడనం | Force, Friction, Gravitation, Pressure", "passage": "", "q_en": "The formula to find ‘g’ value on earth", "q_te": "భూమిపై ‘g’ విలువను కనుగొనే సూత్రం", "opts": [{"en": "$g = \\frac{GR^2}{M}$", "te": "$g = \\frac{GR^2}{M}$"}, {"en": "$g = \\frac{GM}{R^2}$", "te": "$g = \\frac{GM}{R^2}$"}, {"en": "$g = \\frac{MR^2}{G}$", "te": "$g = \\frac{MR^2}{G}$"}, {"en": "$g = \\frac{RM^2}{G}$", "te": "$g = \\frac{RM^2}{G}$"}], "ans": 2, "exp_en": "Equating mg with GMm/R<sup>2</sup> gives g = GM/R<sup>2</sup>.", "exp_te": "mg ను GMm/R<sup>2</sup> తో సమానం చేయగా g = GM/R<sup>2</sup>."}, {"id": 37, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "The physical quantity work has", "q_te": "పని అనే భౌతిక రాశికి", "opts": [{"en": "Only magnitude", "te": "పరిమాణం మాత్రమే"}, {"en": "Only direction", "te": "దిశ మాత్రమే"}, {"en": "Both magnitude and direction", "te": "పరిమాణం, దిశ రెండూ"}, {"en": "Neither magnitude nor direction", "te": "రెండూ ఉండవు"}], "ans": 1, "exp_en": "Work is a scalar quantity — it has magnitude but no direction.", "exp_te": "పని ఒక అదిశ రాశి — దానికి పరిమాణం ఉంటుంది, దిశ ఉండదు."}, {"id": 38, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "A force of 5 N acts on an object to displace it through 2 m in the direction of force. The work done is", "q_te": "5 N బలం ఒక వస్తువును బల దిశలో 2 మీ. స్థానభ్రంశం చెందించింది. జరిగిన పని", "opts": [{"en": "2.5 J", "te": "2.5 J"}, {"en": "10 J", "te": "10 J"}, {"en": "0.4 J", "te": "0.4 J"}, {"en": "20 J", "te": "20 J"}], "ans": 2, "exp_en": "W = F × s = 5 × 2 = 10 J.", "exp_te": "పని = బలం × స్థానభ్రంశం = 5 × 2 = 10 జౌల్."}, {"id": 39, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Unit of work in S.I. system", "q_te": "S.I పద్ధతిలో పనికి ప్రమాణం", "opts": [{"en": "Newton", "te": "న్యూటన్"}, {"en": "Erg", "te": "ఎర్గ్"}, {"en": "Joule", "te": "జౌల్"}, {"en": "Watt", "te": "వాట్"}], "ans": 3, "exp_en": "1 joule = 1 newton × 1 metre.", "exp_te": "1 జౌల్ = 1 న్యూటన్ × 1 మీటరు."}, {"id": 40, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Mechanical energy is equal to", "q_te": "యాంత్రిక శక్తి దీనికి సమానం", "opts": [{"en": "Potential energy × kinetic energy", "te": "స్థితిశక్తి × గతిశక్తి"}, {"en": "Potential energy ÷ kinetic energy", "te": "స్థితిశక్తి ÷ గతిశక్తి"}, {"en": "Potential energy − kinetic energy", "te": "స్థితిశక్తి − గతిశక్తి"}, {"en": "Potential energy + kinetic energy", "te": "స్థితిశక్తి + గతిశక్తి"}], "ans": 4, "exp_en": "Mechanical energy = potential energy + kinetic energy.", "exp_te": "యాంత్రిక శక్తి = స్థితి శక్తి + గతి శక్తి."}, {"id": 41, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Formula of potential energy", "q_te": "స్థితిశక్తి సూత్రం", "opts": [{"en": "$mgh$", "te": "$mgh$"}, {"en": "$\\frac12 mv^2$", "te": "$\\frac12 mv^2$"}, {"en": "$ma$", "te": "$ma$"}, {"en": "$Fs$", "te": "$Fs$"}], "ans": 1, "exp_en": "Gravitational potential energy = mgh.", "exp_te": "గురుత్వ స్థితి శక్తి = mgh."}, {"id": 42, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Formula of kinetic energy", "q_te": "గతిశక్తి సూత్రం", "opts": [{"en": "$mgh$", "te": "$mgh$"}, {"en": "$\\frac12 mv^2$", "te": "$\\frac12 mv^2$"}, {"en": "$ma$", "te": "$ma$"}, {"en": "$Fs$", "te": "$Fs$"}], "ans": 2, "exp_en": "Kinetic energy = ½ × mass × velocity<sup>2</sup>.", "exp_te": "గతి శక్తి = ½ × ద్రవ్యరాశి × వేగం<sup>2</sup>."}, {"id": 43, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Power is equal to", "q_te": "సామర్థ్యం దీనికి సమానం", "opts": [{"en": "Work × time", "te": "పని × కాలం"}, {"en": "Work / time", "te": "పని / కాలం"}, {"en": "Force × distance", "te": "బలం × దూరం"}, {"en": "Force / distance", "te": "బలం / దూరం"}], "ans": 2, "exp_en": "Power is the rate of doing work: P = W/t.", "exp_te": "సామర్థ్యం అంటే పని చేసే రేటు: P = పని/కాలం."}, {"id": 44, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "The following two quantities have the same units", "q_te": "క్రింది రెండు రాశులకు ఒకే ప్రమాణాలు ఉంటాయి", "opts": [{"en": "Work, Force", "te": "పని, బలం"}, {"en": "Work, Power", "te": "పని, సామర్థ్యం"}, {"en": "Power, Force", "te": "సామర్థ్యం, బలం"}, {"en": "Work, Energy", "te": "పని, శక్తి"}], "ans": 4, "exp_en": "Both work and energy are measured in joules.", "exp_te": "పని, శక్తి రెండింటినీ జౌల్‌లలో కొలుస్తారు."}, {"id": 45, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "Water stored in the reservoir at a certain height has this energy", "q_te": "ఎత్తులో జలాశయంలో నిల్వ ఉన్న నీటికి ఉండే శక్తి", "opts": [{"en": "Potential energy", "te": "స్థితిశక్తి"}, {"en": "Kinetic energy", "te": "గతిశక్తి"}, {"en": "Both potential and kinetic energies", "te": "స్థితి, గతి శక్తులు రెండూ"}, {"en": "Neither potential nor kinetic energy", "te": "ఏదీ ఉండదు"}], "ans": 1, "exp_en": "Water at rest at a height has energy due to its position — potential energy.", "exp_te": "ఎత్తులో నిశ్చలంగా ఉన్న నీటికి స్థానం వల్ల శక్తి ఉంటుంది — స్థితి శక్తి."}, {"id": 46, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "For a freely falling body, during its free fall", "q_te": "స్వేచ్ఛాపతన వస్తువు పడుతున్నప్పుడు", "opts": [{"en": "Potential energy is maximum", "te": "స్థితిశక్తి గరిష్ఠం"}, {"en": "Kinetic energy is maximum", "te": "గతిశక్తి గరిష్ఠం"}, {"en": "Potential energy decreases and kinetic energy increases", "te": "స్థితిశక్తి తగ్గుతూ గతిశక్తి పెరుగుతుంది"}, {"en": "Potential energy increases and kinetic energy decreases", "te": "స్థితిశక్తి పెరుగుతూ గతిశక్తి తగ్గుతుంది"}], "ans": 3, "exp_en": "As the body falls its height decreases (PE falls) and its speed increases (KE rises); the total stays constant.", "exp_te": "వస్తువు పడుతున్నప్పుడు ఎత్తు తగ్గి స్థితి శక్తి తగ్గుతుంది, వేగం పెరిగి గతి శక్తి పెరుగుతుంది; మొత్తం శక్తి స్థిరం."}, {"id": 47, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "One of the following objects has potential energy", "q_te": "క్రింది వాటిలో స్థితిశక్తి కలిగి ఉన్నది", "opts": [{"en": "Blowing wind", "te": "వీస్తున్న గాలి"}, {"en": "Rotating wheel", "te": "తిరుగుతున్న చక్రం"}, {"en": "Flowing water", "te": "ప్రవహిస్తున్న నీరు"}, {"en": "Stretched spring", "te": "సాగదీయబడిన స్ప్రింగ్"}], "ans": 4, "exp_en": "A stretched spring stores energy because of its changed shape — elastic potential energy.", "exp_te": "సాగదీసిన స్ప్రింగ్ ఆకార మార్పు వల్ల శక్తిని నిల్వ చేస్తుంది — స్థితిస్థాపక స్థితి శక్తి."}, {"id": 48, "sec": "పని, శక్తి, సామర్థ్యం | Work, Energy & Power", "passage": "", "q_en": "One of the following objects has kinetic energy", "q_te": "క్రింది వాటిలో గతిశక్తి కలిగి ఉన్నది", "opts": [{"en": "Stretched rubber band", "te": "సాగదీయబడిన రబ్బరు బ్యాండు"}, {"en": "Water stored in dam", "te": "ఆనకట్టలో నిల్వ చేయబడిన నీరు"}, {"en": "Ball kept at a height on the wall", "te": "గోడపై కొంత ఎత్తులో ఉంచబడిన బంతి"}, {"en": "Flowing water", "te": "ప్రవహిస్తున్న నీరు"}], "ans": 4, "exp_en": "Energy due to motion is kinetic energy; only the flowing water is moving.", "exp_te": "చలనం వల్ల కలిగే శక్తి గతి శక్తి; ప్రవహించే నీరు మాత్రమే కదులుతోంది."}, {"id": 49, "sec": "ధ్వని | Sound", "passage": "", "q_en": "S.I. unit of wavelength is", "q_te": "తరంగ దైర్ఘ్యం యొక్క S.I ప్రమాణం", "opts": [{"en": "Centimetre", "te": "సెంటీమీటరు"}, {"en": "Metre", "te": "మీటర్"}, {"en": "Hertz", "te": "హెర్ట్జ్"}, {"en": "Second", "te": "సెకను"}], "ans": 2, "exp_en": "Wavelength is a length, so its S.I unit is the metre.", "exp_te": "తరంగ ధైర్ఘ్యం ఒక పొడవు, కాబట్టి దాని S.I ప్రమాణం మీటరు."}, {"id": 50, "sec": "ధ్వని | Sound", "passage": "", "q_en": "S.I. unit of frequency", "q_te": "పౌనఃపున్యం యొక్క S.I ప్రమాణం", "opts": [{"en": "Metre", "te": "మీటరు"}, {"en": "Hertz", "te": "హెర్ట్జ్"}, {"en": "Second", "te": "సెకను"}, {"en": "Metre / second", "te": "మీటర్/సెకను"}], "ans": 2, "exp_en": "1 hertz = 1 vibration per second.", "exp_te": "1 హెర్ట్జ్ = సెకనుకు 1 కంపనం."}, {"id": 51, "sec": "ధ్వని | Sound", "passage": "", "q_en": "Magnitude of maximum disturbance in the medium on either side of the mean value is called", "q_te": "యానకంలో మాధ్యమిక స్థానానికి ఇరువైపులా గరిష్ఠ అలజడి పరిమాణం", "opts": [{"en": "Frequency", "te": "పౌనఃపున్యం"}, {"en": "Amplitude", "te": "కంపన పరిమితి"}, {"en": "Wavelength", "te": "తరంగ దైర్ఘ్యం"}, {"en": "Time period", "te": "ఆవర్తన కాలం"}], "ans": 2, "exp_en": "The maximum displacement from the mean position is the amplitude.", "exp_te": "మధ్య స్థానం నుండి గరిష్ఠ స్థానభ్రంశమే కంపన పరిమితి."}, {"id": 52, "sec": "ధ్వని | Sound", "passage": "", "q_en": "If λ is the wavelength and ν is the frequency of sound produced then the formula for speed of sound wave is", "q_te": "λ తరంగదైర్ఘ్యం, ν పౌనఃపున్యం అయితే ధ్వని తరంగ వడి సూత్రం", "opts": [{"en": "$v = \\frac{\\lambda}{\\nu}$", "te": "$v = \\frac{\\lambda}{\\nu}$"}, {"en": "$\\nu = \\lambda v$", "te": "$\\nu = \\lambda v$"}, {"en": "$v = \\nu\\lambda$", "te": "$v = \\nu\\lambda$"}, {"en": "$\\lambda = \\nu v$", "te": "$\\lambda = \\nu v$"}], "ans": 3, "exp_en": "Speed = frequency × wavelength, i.e. v = υλ.", "exp_te": "వేగం = పౌనఃపున్యం × తరంగ ధైర్ఘ్యం, అంటే v = υλ."}, {"id": 53, "sec": "ధ్వని | Sound", "passage": "", "q_en": "The amount of sound energy passing through unit area in each second is called", "q_te": "ప్రతి సెకనుకు ప్రమాణ వైశాల్యం గుండా ప్రయాణించే ధ్వని శక్తి", "opts": [{"en": "Frequency", "te": "పౌనఃపున్యం"}, {"en": "Amplitude", "te": "కంపన పరిమితి"}, {"en": "Intensity", "te": "తీవ్రత"}, {"en": "Wavelength", "te": "తరంగ దైర్ఘ్యం"}], "ans": 3, "exp_en": "Sound energy per unit area per second is the intensity of sound.", "exp_te": "ప్రమాణ వైశాల్యానికి, సెకనుకు ధ్వని శక్తియే ధ్వని తీవ్రత."}, {"id": 54, "sec": "ధ్వని | Sound", "passage": "", "q_en": "A sound wave has a frequency of 20 Hz and a wavelength 35 m, then the speed of sound is", "q_te": "ఒక ధ్వని తరంగ పౌనఃపున్యం 20 Hz, తరంగదైర్ఘ్యం 35 మీ అయితే ధ్వని వడి", "opts": [{"en": "70 m/s", "te": "70 m/s"}, {"en": "700 m/s", "te": "700 m/s"}, {"en": "7000 m/s", "te": "7000 m/s"}, {"en": "7 m/s", "te": "7 m/s"}], "ans": 2, "exp_en": "v = υλ = 20 × 35 = 700 m/s.", "exp_te": "వేగం = 20 × 35 = 700 మీ/సె."}, {"id": 55, "sec": "ధ్వని | Sound", "passage": "", "q_en": "The repeated reflection that results in the persistence of sound is called", "q_te": "ధ్వని కొనసాగడానికి కారణమయ్యే పునరావృత పరావర్తనం", "opts": [{"en": "Echo", "te": "ప్రతిధ్వని"}, {"en": "Multiple reflections", "te": "బహుళ పరావర్తనాలు"}, {"en": "Reverberation", "te": "అనురణనం"}, {"en": "Frequency", "te": "పౌనఃపున్యం"}], "ans": 3, "exp_en": "Persistence of sound due to repeated reflections is reverberation.", "exp_te": "పునరావృత పరావర్తనాల వల్ల ధ్వని కొనసాగడం ప్రతినాదం."}, {"id": 56, "sec": "ధ్వని | Sound", "passage": "", "q_en": "The frequency of a sound wave is 60 Hz. The number of times it vibrates in one second is", "q_te": "ధ్వని తరంగ పౌనఃపున్యం 60 Hz. సెకనులో అది కంపించే సార్లు", "opts": [{"en": "6", "te": "6"}, {"en": "10", "te": "10"}, {"en": "60", "te": "60"}, {"en": "$\\frac{1}{60}$", "te": "$\\frac{1}{60}$"}], "ans": 3, "exp_en": "Frequency itself means vibrations per second, so 60 Hz = 60 vibrations.", "exp_te": "పౌనఃపున్యం అంటేనే సెకనుకు కంపనాలు, కాబట్టి 60 Hz = 60 కంపనాలు."}, {"id": 57, "sec": "ఉష్ణం | Heat", "passage": "", "q_en": "Temperature of an object is $25^\\circ C$. Its temperature in Kelvin scale", "q_te": "ఒక వస్తువు ఉష్ణోగ్రత $25^\\circ C$. కెల్విన్ మానంలో", "opts": [{"en": "298 K", "te": "298 K"}, {"en": "248 K", "te": "248 K"}, {"en": "300 K", "te": "300 K"}, {"en": "25 K", "te": "25 K"}], "ans": 1, "exp_en": "K = °C + 273 = 25 + 273 = 298 K.", "exp_te": "కెల్విన్ = సెల్సియస్ + 273 = 25 + 273 = 298 K."}, {"id": 58, "sec": "ఉష్ణం | Heat", "passage": "", "q_en": "Two objects A and B are in thermal equilibrium. If the temperature of A is $30^\\circ C$, then the temperature of B is", "q_te": "A, B అనే రెండు వస్తువులు ఉష్ణ సమతాస్థితిలో ఉన్నాయి. A ఉష్ణోగ్రత $30^\\circ C$ అయితే B ఉష్ణోగ్రత", "opts": [{"en": "$0^\\circ C$", "te": "$0^\\circ C$"}, {"en": "$30^\\circ C$", "te": "$30^\\circ C$"}, {"en": "$300^\\circ C$", "te": "$300^\\circ C$"}, {"en": "$60^\\circ C$", "te": "$60^\\circ C$"}], "ans": 2, "exp_en": "Bodies in thermal equilibrium are at the same temperature.", "exp_te": "ఉష్ణ సమతాస్థితిలో ఉన్న వస్తువుల ఉష్ణోగ్రతలు సమానం."}, {"id": 59, "sec": "ఉష్ణం | Heat", "passage": "", "q_en": "1 Calorie is equal to", "q_te": "1 కేలరీ దీనికి సమానం", "opts": [{"en": "4186 J", "te": "4186 J"}, {"en": "418.6 J", "te": "418.6 J"}, {"en": "41.86 J", "te": "41.86 J"}, {"en": "4.186 J", "te": "4.186 J"}], "ans": 4, "exp_en": "1 calorie = 4.186 joule (1 kilocalorie = 4186 J).", "exp_te": "1 కెలోరీ = 4.186 జౌల్ (1 కిలో కెలోరీ = 4186 J)."}, {"id": 60, "sec": "ఉష్ణం | Heat", "passage": "", "q_en": "Boiling point of water at normal atmospheric pressure is", "q_te": "సాధారణ వాతావరణ పీడనం వద్ద నీటి బాష్పీభవన స్థానం", "opts": [{"en": "$0^\\circ C$", "te": "$0^\\circ C$"}, {"en": "$100^\\circ C$", "te": "$100^\\circ C$"}, {"en": "$110^\\circ C$", "te": "$110^\\circ C$"}, {"en": "$-5^\\circ C$", "te": "$-5^\\circ C$"}], "ans": 2, "exp_en": "Water boils at 100°C at 1 atmosphere pressure.", "exp_te": "1 వాతావరణ పీడనం వద్ద నీరు 100°C వద్ద మరుగుతుంది."}, {"id": 61, "sec": "కాంతి | Light", "passage": "", "q_en": "A spherical mirror whose reflecting surface is curved inwards is called", "q_te": "పరావర్తన తలం లోపలికి వంగిన గోళాకార దర్పణం", "opts": [{"en": "Concave mirror", "te": "పుటాకార దర్పణం"}, {"en": "Convex mirror", "te": "కుంభాకార దర్పణం"}, {"en": "Plane mirror", "te": "సమతల దర్పణం"}, {"en": "Plano convex mirror", "te": "సమతల కుంభాకార దర్పణం"}], "ans": 1, "exp_en": "Inward curved reflecting surface = concave mirror.", "exp_te": "లోపలివైపు వంగిన పరావర్తన తలం = పుటాకార దర్పణం."}, {"id": 62, "sec": "కాంతి | Light", "passage": "", "q_en": "If an object is placed at the centre of curvature in front of a concave mirror, then the characteristics of the image", "q_te": "పుటాకార దర్పణం ముందు వక్రతా కేంద్రం వద్ద వస్తువును ఉంచితే ప్రతిబింబ లక్షణాలు", "opts": [{"en": "Real, inverted and diminished", "te": "నిజ, తలక్రిందులు, చిన్నది"}, {"en": "Real, inverted and magnified", "te": "నిజ, తలక్రిందులు, పెద్దది"}, {"en": "Real, inverted and same size", "te": "నిజ, తలక్రిందులు, అదే పరిమాణం"}, {"en": "Virtual, erect and same size", "te": "మిథ్యా, నిటారు, అదే పరిమాణం"}], "ans": 3, "exp_en": "When the object is at C, the image also forms at C — real, inverted and of the same size.", "exp_te": "వస్తువు C వద్ద ఉంటే ప్రతిబింబం కూడా C వద్దే — నిజ, తలక్రిందులు, సమాన పరిమాణం."}, {"id": 63, "sec": "కాంతి | Light", "passage": "", "q_en": "To form an image at infinity, the object should be placed in front of a concave mirror", "q_te": "అనంత దూరంలో ప్రతిబింబం ఏర్పడాలంటే పుటాకార దర్పణం ముందు వస్తువును ఉంచవలసిన స్థానం", "opts": [{"en": "At focus", "te": "నాభి వద్ద"}, {"en": "At pole", "te": "ధ్రువం వద్ద"}, {"en": "At centre of curvature", "te": "వక్రతా కేంద్రం వద్ద"}, {"en": "Between pole and focus", "te": "ధ్రువం, నాభి మధ్య"}], "ans": 1, "exp_en": "Rays from an object at the focus emerge parallel, so the image forms at infinity.", "exp_te": "నాభి వద్ద ఉన్న వస్తువు కిరణాలు సమాంతరంగా వెళతాయి, కాబట్టి ప్రతిబింబం అనంతం వద్ద."}, {"id": 64, "sec": "కాంతి | Light", "passage": "", "q_en": "This lens is called a converging lens", "q_te": "అభిసారి కటకం అని దీనిని అంటారు", "opts": [{"en": "Concave lens", "te": "పుటాకార కటకం"}, {"en": "Convex lens", "te": "కుంభాకార కటకం"}, {"en": "Plano concave lens", "te": "సమతల పుటాకార కటకం"}, {"en": "Plano convex lens", "te": "సమతల కుంభాకార కటకం"}], "ans": 2, "exp_en": "A convex lens brings parallel rays together at the focus, so it converges light.", "exp_te": "కుంభాకార కటకం సమాంతర కిరణాలను నాభి వద్ద కేంద్రీకరిస్తుంది."}, {"id": 65, "sec": "కాంతి | Light", "passage": "", "q_en": "Lens formula among the following", "q_te": "క్రింది వాటిలో కటక సూత్రం", "opts": [{"en": "$\\frac1u + \\frac1v = \\frac1f$", "te": "$\\frac1u + \\frac1v = \\frac1f$"}, {"en": "$\\frac1v - \\frac1u = \\frac1f$", "te": "$\\frac1v - \\frac1u = \\frac1f$"}, {"en": "$\\frac1v = \\frac1f - \\frac1u$", "te": "$\\frac1v = \\frac1f - \\frac1u$"}, {"en": "$\\frac1u = \\frac1f - \\frac1v$", "te": "$\\frac1u = \\frac1f - \\frac1v$"}], "ans": 2, "exp_en": "The lens formula is 1/v − 1/u = 1/f.", "exp_te": "కటక సూత్రం: 1/v − 1/u = 1/f."}, {"id": 66, "sec": "కాంతి | Light", "passage": "", "q_en": "The power of a lens with focal length 2 metres (in dioptres)", "q_te": "2 మీ నాభ్యంతరం గల కటక సామర్థ్యం (డయాప్టర్లలో)", "opts": [{"en": "0.1", "te": "0.1"}, {"en": "0.2", "te": "0.2"}, {"en": "0.5", "te": "0.5"}, {"en": "2", "te": "2"}], "ans": 3, "exp_en": "P = 1/f (in metres) = 1/2 = 0.5 D.", "exp_te": "సామర్థ్యం = 1/నాభ్యాంతరం = 1/2 = 0.5 డయాప్టర్."}, {"id": 67, "sec": "కాంతి | Light", "passage": "", "q_en": "The following material cannot be used to make a lens", "q_te": "కటకం తయారీకి ఉపయోగించలేని పదార్థం", "opts": [{"en": "Water", "te": "నీరు"}, {"en": "Glass", "te": "గాజు"}, {"en": "Plastic", "te": "ప్లాస్టిక్"}, {"en": "Clay", "te": "మట్టి"}], "ans": 4, "exp_en": "A lens must be transparent; clay is opaque.", "exp_te": "కటకం పారదర్శకంగా ఉండాలి; బంక మట్టి అపారదర్శకం."}, {"id": 68, "sec": "కాంతి | Light", "passage": "", "q_en": "The human eye forms the image of an object at its", "q_te": "మానవ కన్ను వస్తువు ప్రతిబింబాన్ని ఏర్పరచే భాగం", "opts": [{"en": "Cornea", "te": "కార్నియా"}, {"en": "Iris", "te": "ఐరిస్ (తారక)"}, {"en": "Pupil", "te": "కనుపాప"}, {"en": "Retina", "te": "రెటీనా"}], "ans": 4, "exp_en": "The image is formed on the light-sensitive retina.", "exp_te": "కాంతి సున్నితమైన రెటీనాపై ప్రతిబింబం ఏర్పడుతుంది."}, {"id": 69, "sec": "కాంతి | Light", "passage": "", "q_en": "The change in the focal length of the eye lens is caused by the action of", "q_te": "కంటి కటకం నాభ్యంతరంలో మార్పు దీని చర్య వల్ల జరుగుతుంది", "opts": [{"en": "Pupil", "te": "కనుపాప"}, {"en": "Retina", "te": "రెటీనా"}, {"en": "Ciliary muscles", "te": "సిలియరీ కండరాలు"}, {"en": "Iris", "te": "ఐరిస్"}], "ans": 3, "exp_en": "The ciliary muscles change the curvature of the eye lens — accommodation.", "exp_te": "సిలియరీ కండరాలు కంటి కటక వక్రతను మార్చుతాయి — సర్దుబాటు."}, {"id": 70, "sec": "కాంతి | Light", "passage": "", "q_en": "The splitting of white light into its component colours is", "q_te": "తెల్లని కాంతి అనుఘటక రంగులుగా విడిపోవడం", "opts": [{"en": "Scattering", "te": "పరిక్షేపణం"}, {"en": "Dispersion", "te": "విక్షేపణం"}, {"en": "Reflection", "te": "పరావర్తనం"}, {"en": "Refraction", "te": "వక్రీభవనం"}], "ans": 2, "exp_en": "Splitting into the seven colours by a prism is dispersion.", "exp_te": "పట్టకం ద్వారా ఏడు రంగులుగా విడిపోవడం విక్షేపణం."}, {"id": 71, "sec": "కాంతి | Light", "passage": "", "q_en": "The defect that arises due to gradual weakening of ciliary muscles and diminishing flexibility of the eye lens is", "q_te": "సిలియరీ కండరాలు క్రమంగా బలహీనపడి, కంటి కటకం వశ్యత తగ్గడం వల్ల వచ్చే దోషం", "opts": [{"en": "Myopia", "te": "హ్రస్వ దృష్టి"}, {"en": "Hypermetropia", "te": "దీర్ఘ దృష్టి"}, {"en": "Presbyopia", "te": "చత్వారం"}, {"en": "Blindness", "te": "అంధత్వం"}], "ans": 3, "exp_en": "This age-related defect is presbyopia.", "exp_te": "వయస్సుతో వచ్చే ఈ లోపం చత్వారం."}, {"id": 72, "sec": "కాంతి | Light", "passage": "", "q_en": "The lens used to correct the eye defect myopia", "q_te": "హ్రస్వ దృష్టి సవరణకు ఉపయోగించే కటకం", "opts": [{"en": "Concave lens", "te": "పుటాకార కటకం"}, {"en": "Convex lens", "te": "కుంభాకార కటకం"}, {"en": "Plano convex lens", "te": "సమతల కుంభాకార కటకం"}, {"en": "Plano concave lens", "te": "సమతల పుటాకార కటకం"}], "ans": 1, "exp_en": "A concave (diverging) lens moves the image back on to the retina.", "exp_te": "పుటాకార (విసరణ) కటకం ప్రతిబింబాన్ని రెటీనాపైకి వెనక్కి జరుపుతుంది."}, {"id": 73, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "The S.I. unit of potential difference", "q_te": "పొటెన్షియల్ భేదానికి S.I ప్రమాణం", "opts": [{"en": "Ampere", "te": "ఆంపియర్"}, {"en": "Volt", "te": "వోల్ట్"}, {"en": "Joule", "te": "జౌల్"}, {"en": "Ohm", "te": "ఓమ్"}], "ans": 2, "exp_en": "Potential difference is measured in volts (1 V = 1 J/C). Note: the printed key marks option 1, which is the unit of current.", "exp_te": "పొటెన్షియల్ భేదాన్ని వోల్టులలో కొలుస్తారు (1 V = 1 J/C). గమనిక: ప్రింటెడ్ కీ 1వ ఆప్షన్ (ఆంపియర్) చూపింది, అది విద్యుత్ ప్రవాహ ప్రమాణం."}, {"id": 74, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "Work done in moving a charge of 2 C across two points having a potential difference 12 V is", "q_te": "12 V పొటెన్షియల్ భేదం గల రెండు బిందువుల మధ్య 2 C ఆవేశాన్ని కదిలించడానికి జరిగిన పని", "opts": [{"en": "6 J", "te": "6 J"}, {"en": "12 J", "te": "12 J"}, {"en": "24 J", "te": "24 J"}, {"en": "10 J", "te": "10 J"}], "ans": 3, "exp_en": "W = qV = 2 × 12 = 24 J. Note: the printed key marks 12 J.", "exp_te": "పని = ఆవేశం × పొటెన్షియల్ భేదం = 2 × 12 = 24 జౌల్. గమనిక: ప్రింటెడ్ కీ 12 J చూపింది."}, {"id": 75, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "If the length of a wire is increased 2 times, then the resistance of the wire becomes", "q_te": "తీగ పొడవును 2 రెట్లు పెంచితే తీగ నిరోధం", "opts": [{"en": "2 times", "te": "2 రెట్లు"}, {"en": "4 times", "te": "4 రెట్లు"}, {"en": "½ times", "te": "½ రెట్లు"}, {"en": "¼ times", "te": "¼ రెట్లు"}], "ans": 1, "exp_en": "R = ρl/A, so R is directly proportional to length — doubling l doubles R. Note: the printed key marks ½.", "exp_te": "R = ρl/A, నిరోధం పొడవుకు అనులోమానుపాతం — పొడవు రెట్టింపైతే నిరోధమూ రెట్టింపు. గమనిక: ప్రింటెడ్ కీ ½ చూపింది."}, {"id": 76, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "If the area of cross section of a wire is increased 2 times, then the resistance becomes", "q_te": "తీగ మధ్యచ్ఛేద వైశాల్యాన్ని 2 రెట్లు పెంచితే నిరోధం", "opts": [{"en": "2 times", "te": "2 రెట్లు"}, {"en": "4 times", "te": "4 రెట్లు"}, {"en": "½ times", "te": "½ రెట్లు"}, {"en": "¼ times", "te": "¼ రెట్లు"}], "ans": 3, "exp_en": "R = ρl/A, so R is inversely proportional to area — doubling A halves R. Note: the printed key marks 2 times.", "exp_te": "R = ρl/A, నిరోధం వైశాల్యానికి విలోమానుపాతం — వైశాల్యం రెట్టింపైతే నిరోధం సగం. గమనిక: ప్రింటెడ్ కీ 2 రెట్లు చూపింది."}, {"id": 77, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "Resistors 2 Ω and 4 Ω are connected in series, then the resultant resistance will be", "q_te": "2 Ω, 4 Ω నిరోధాలను శ్రేణిలో కలిపితే ఫలిత నిరోధం", "opts": [{"en": "2 Ω", "te": "2 Ω"}, {"en": "4 Ω", "te": "4 Ω"}, {"en": "6 Ω", "te": "6 Ω"}, {"en": "$\\frac16$ Ω", "te": "$\\frac16$ Ω"}], "ans": 3, "exp_en": "In series R = R₁ + R₂ = 2 + 4 = 6 Ω.", "exp_te": "శ్రేణిలో R = R₁ + R₂ = 2 + 4 = 6 Ω."}, {"id": 78, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "Resistors 5 Ω and 10 Ω are connected in parallel, then the resultant resistance will be", "q_te": "5 Ω, 10 Ω నిరోధాలను సమాంతరంగా కలిపితే ఫలిత నిరోధం", "opts": [{"en": "5 Ω", "te": "5 Ω"}, {"en": "15 Ω", "te": "15 Ω"}, {"en": "$\\frac{3}{10}$ Ω", "te": "$\\frac{3}{10}$ Ω"}, {"en": "$\\frac{10}{3}$ Ω", "te": "$\\frac{10}{3}$ Ω"}], "ans": 4, "exp_en": "1/R = 1/5 + 1/10 = 3/10 → R = 10/3 Ω.", "exp_te": "1/R = 1/5 + 1/10 = 3/10 → R = 10/3 Ω."}, {"id": 79, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "When a current of 2 A passes through a resistance of 5 Ω, the potential difference between the terminals of the resistor is", "q_te": "5 Ω నిరోధం గుండా 2 A విద్యుత్ ప్రవహిస్తే దాని కొనల మధ్య పొటెన్షియల్ భేదం", "opts": [{"en": "3 V", "te": "3 V"}, {"en": "2.5 V", "te": "2.5 V"}, {"en": "0.4 V", "te": "0.4 V"}, {"en": "10 V", "te": "10 V"}], "ans": 4, "exp_en": "By Ohm's law V = IR = 2 × 5 = 10 V.", "exp_te": "ఓమ్ నియమం ప్రకారం V = IR = 2 × 5 = 10 V."}, {"id": 80, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "One kilowatt hour (kWh) is equal to", "q_te": "ఒక కిలోవాట్ గంట (kWh)", "opts": [{"en": "$3.6 \\times 10^6$ erg", "te": "$3.6 \\times 10^6$ erg"}, {"en": "$3.6 \\times 10^6$ joule", "te": "$3.6 \\times 10^6$ joule"}, {"en": "3.6 erg", "te": "3.6 erg"}, {"en": "3.6 joule", "te": "3.6 joule"}], "ans": 2, "exp_en": "1 kWh = 1000 W × 3600 s = 3.6 × 10<sup>6</sup> J.", "exp_te": "1 kWh = 1000 W × 3600 సె = 3.6 × 10<sup>6</sup> జౌల్."}, {"id": 81, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "The following term does not represent electrical power in a circuit", "q_te": "వలయంలో విద్యుత్ సామర్థ్యాన్ని సూచించనిది", "opts": [{"en": "$i^2R$", "te": "$i^2R$"}, {"en": "$iR^2$", "te": "$iR^2$"}, {"en": "$Vi$", "te": "$Vi$"}, {"en": "$\\frac{V^2}{R}$", "te": "$\\frac{V^2}{R}$"}], "ans": 2, "exp_en": "Power = VI = I<sup>2</sup>R = V<sup>2</sup>/R; ‘iR<sup>2</sup>’ is not a power formula.", "exp_te": "సామర్థ్యం = VI = I<sup>2</sup>R = V<sup>2</sup>/R; 'iR<sup>2</sup>' సామర్థ్య సూత్రం కాదు."}, {"id": 82, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "The S.I. unit of resistivity", "q_te": "విశిష్ట నిరోధానికి S.I ప్రమాణం", "opts": [{"en": "Ω", "te": "Ω"}, {"en": "Ω–m", "te": "Ω–m"}, {"en": "$\\Omega\\,m^2$", "te": "$\\Omega\\,m^2$"}, {"en": "$\\Omega / m^2$", "te": "$\\Omega / m^2$"}], "ans": 2, "exp_en": "From ρ = RA/l, the unit is ohm-metre.", "exp_te": "ρ = RA/l నుండి ప్రమాణం ఓమ్-మీటరు."}, {"id": 83, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "$1\\text{ Volt} = \\frac{?}{1\\text{ coulomb}}$", "q_te": "$1\\text{ వోల్ట్} = \\frac{?}{1\\text{ కూలుంబ్}}$", "opts": [{"en": "1 joule", "te": "1 joule"}, {"en": "1 ohm", "te": "1 ohm"}, {"en": "1 watt", "te": "1 watt"}, {"en": "1 ampere", "te": "1 ampere"}], "ans": 1, "exp_en": "1 volt = 1 joule per coulomb.", "exp_te": "1 వోల్ట్ = కూలుంబుకు 1 జౌల్."}, {"id": 84, "sec": "విద్యుత్ | Electricity", "passage": "", "q_en": "$1\\text{ ohm} = \\frac{?}{1\\text{ ampere}}$", "q_te": "$1\\text{ ఓమ్} = \\frac{?}{1\\text{ ఆంపియర్}}$", "opts": [{"en": "1 coulomb", "te": "1 coulomb"}, {"en": "1 joule", "te": "1 joule"}, {"en": "1 volt", "te": "1 volt"}, {"en": "1 watt", "te": "1 watt"}], "ans": 3, "exp_en": "From V = IR, 1 ohm = 1 volt per ampere.", "exp_te": "V = IR నుండి 1 ఓమ్ = ఆంపియరుకు 1 వోల్ట్."}, {"id": 85, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "The physical quantity magnetic field has", "q_te": "అయస్కాంత క్షేత్రం అనే భౌతిక రాశికి", "opts": [{"en": "Only magnitude", "te": "పరిమాణం మాత్రమే"}, {"en": "Only direction", "te": "దిశ మాత్రమే"}, {"en": "Both magnitude and direction", "te": "పరిమాణం, దిశ రెండూ"}, {"en": "Neither magnitude nor direction", "te": "రెండూ ఉండవు"}], "ans": 3, "exp_en": "Magnetic field is a vector quantity — it has both magnitude and direction.", "exp_te": "అయస్కాంత క్షేత్రం ఒక సదిశ రాశి — పరిమాణం, దిశ రెండూ ఉంటాయి."}, {"id": 86, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "In the right hand thumb rule, the thumb indicates the direction of", "q_te": "కుడిచేతి బొటనవేలు నియమంలో బొటనవేలు సూచించే దిశ", "opts": [{"en": "Magnetic field", "te": "అయస్కాంత క్షేత్రం"}, {"en": "Electric current", "te": "విద్యుత్ ప్రవాహం"}, {"en": "Induced current", "te": "ప్రేరిత విద్యుత్"}, {"en": "Induced magnetic field", "te": "ప్రేరిత అయస్కాంత క్షేత్రం"}], "ans": 2, "exp_en": "The thumb shows the current direction and the curled fingers the magnetic field.", "exp_te": "బొటనవేలు విద్యుత్ ప్రవాహ దిశను, ముడుచుకున్న వేళ్ళు అయస్కాంత క్షేత్ర దిశను చూపుతాయి."}, {"id": 87, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "The direction of magnetic lines of force outside a bar magnet", "q_te": "దండాయస్కాంతం వెలుపల అయస్కాంత బలరేఖల దిశ", "opts": [{"en": "From north to south", "te": "ఉత్తరం నుండి దక్షిణానికి"}, {"en": "From south to north", "te": "దక్షిణం నుండి ఉత్తరానికి"}, {"en": "From east to west", "te": "తూర్పు నుండి పడమరకు"}, {"en": "From west to east", "te": "పడమర నుండి తూర్పుకు"}], "ans": 1, "exp_en": "Field lines run from the north pole to the south pole outside the magnet (and S to N inside).", "exp_te": "అయస్కాంతం వెలుపల బలరేఖలు ఉత్తర ధ్రువం నుండి దక్షిణ ధ్రువానికి (లోపల దక్షిణం నుండి ఉత్తరానికి) సాగుతాయి."}, {"id": 88, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "A current flows through a horizontal power line from east to west. The direction of the magnetic field at a point below the wire, when viewed from east to west, is", "q_te": "ఒక క్షితిజ సమాంతర విద్యుత్ తీగలో తూర్పు నుండి పడమరకు విద్యుత్ ప్రవహిస్తోంది. తూర్పు నుండి పడమర వైపు చూసినప్పుడు తీగ కింది బిందువు వద్ద అయస్కాంత క్షేత్ర దిశ", "opts": [{"en": "Clockwise in a plane perpendicular to the wire", "te": "తీగకు లంబ తలంలో సవ్యదిశలో"}, {"en": "Anticlockwise in a plane perpendicular to the wire", "te": "తీగకు లంబ తలంలో అపసవ్యదిశలో"}, {"en": "Clockwise in a plane parallel to the wire", "te": "తీగకు సమాంతర తలంలో సవ్యదిశలో"}, {"en": "Anticlockwise in a plane parallel to the wire", "te": "తీగకు సమాంతర తలంలో అపసవ్యదిశలో"}], "ans": 1, "exp_en": "By the right hand thumb rule the field forms circles in the plane perpendicular to the wire; as marked in the key, clockwise when viewed from the east.", "exp_te": "కుడిచేతి బొటనవేలి నిబంధన ప్రకారం క్షేత్రం తీగకు లంబ తలంలో వృత్తాలుగా ఏర్పడుతుంది; కీ ప్రకారం తూర్పు నుండి చూస్తే సవ్య దిశలో."}, {"id": 89, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "In Fleming’s left hand rule, the central (middle) finger indicates the direction of", "q_te": "ఫ్లెమింగ్ ఎడమచేతి నియమంలో మధ్యవేలు సూచించే దిశ", "opts": [{"en": "Magnetic field", "te": "అయస్కాంత క్షేత్రం"}, {"en": "Current", "te": "విద్యుత్ ప్రవాహం"}, {"en": "Force on the conductor", "te": "వాహకంపై పనిచేసే బలం"}, {"en": "Induced current", "te": "ప్రేరిత విద్యుత్"}], "ans": 2, "exp_en": "Fore finger = field, central finger = current, thumb = force.", "exp_te": "చూపుడు వేలు = క్షేత్రం, మధ్య వేలు = విద్యుత్ ప్రవాహం, బొటనవేలు = బలం."}, {"id": 90, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "In Fleming’s left hand rule, the fore finger indicates the direction of", "q_te": "ఫ్లెమింగ్ ఎడమచేతి నియమంలో చూపుడువేలు సూచించే దిశ", "opts": [{"en": "Magnetic field", "te": "అయస్కాంత క్షేత్రం"}, {"en": "Current", "te": "విద్యుత్ ప్రవాహం"}, {"en": "Force on the conductor", "te": "వాహకంపై పనిచేసే బలం"}, {"en": "Induced current", "te": "ప్రేరిత విద్యుత్"}], "ans": 1, "exp_en": "The fore finger points along the magnetic field.", "exp_te": "చూపుడు వేలు అయస్కాంత క్షేత్ర దిశను చూపుతుంది."}, {"id": 91, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "In Fleming’s left hand rule, the thumb indicates the direction of", "q_te": "ఫ్లెమింగ్ ఎడమచేతి నియమంలో బొటనవేలు సూచించే దిశ", "opts": [{"en": "Magnetic field", "te": "అయస్కాంత క్షేత్రం"}, {"en": "Current", "te": "విద్యుత్ ప్రవాహం"}, {"en": "Force on the conductor", "te": "వాహకంపై పనిచేసే బలం"}, {"en": "Induced current", "te": "ప్రేరిత విద్యుత్"}], "ans": 3, "exp_en": "The thumb gives the direction of the force (motion) on the conductor.", "exp_te": "బొటనవేలు వాహకంపై పనిచేసే బలం (చలనం) దిశను తెలుపుతుంది."}, {"id": 92, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "At the time of short circuit, the current in the circuit", "q_te": "లఘు వలయం (షార్ట్ సర్క్యూట్) సమయంలో వలయంలో విద్యుత్", "opts": [{"en": "Reduces substantially", "te": "బాగా తగ్గుతుంది"}, {"en": "Does not change", "te": "మారదు"}, {"en": "Increases heavily", "te": "బాగా పెరుగుతుంది"}, {"en": "Varies continuously", "te": "నిరంతరం మారుతుంది"}], "ans": 3, "exp_en": "Resistance falls almost to zero, so by I = V/R the current rises enormously.", "exp_te": "నిరోధం దాదాపు సున్నాకు పడిపోతుంది, కాబట్టి I = V/R ప్రకారం ప్రవాహం భారీగా పెరుగుతుంది."}, {"id": 93, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "Unit of magnetic flux density is", "q_te": "అయస్కాంత అభివాహ సాంద్రత ప్రమాణం", "opts": [{"en": "Weber", "te": "Weber"}, {"en": "Weber–metre", "te": "Weber–metre"}, {"en": "Weber/metre", "te": "Weber/metre"}, {"en": "$\\text{Weber}/m^2$", "te": "$\\text{Weber}/m^2$"}], "ans": 4, "exp_en": "Flux density = flux ÷ area = weber/m<sup>2</sup> (tesla).", "exp_te": "అభివాహ సాంద్రత = అభివాహం ÷ వైశాల్యం = వెబర్/మీ<sup>2</sup> (టెస్లా)."}, {"id": 94, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "If a charge ‘q’ moves with a velocity ‘v’ perpendicular to the magnetic field ‘B’, then the magnetic force on the charge is", "q_te": "‘q’ ఆవేశం ‘B’ అయస్కాంత క్షేత్రానికి లంబంగా ‘v’ వేగంతో కదిలితే దానిపై అయస్కాంత బలం", "opts": [{"en": "$qvB$", "te": "$qvB$"}, {"en": "$\\frac{qvB}{2}$", "te": "$\\frac{qvB}{2}$"}, {"en": "$\\frac{qvB}{3}$", "te": "$\\frac{qvB}{3}$"}, {"en": "0", "te": "0"}], "ans": 1, "exp_en": "F = qvB sinθ; for θ = 90°, sinθ = 1, so F = qvB.", "exp_te": "F = qvB sinθ; θ = 90° అయితే sinθ = 1, కాబట్టి F = qvB."}, {"id": 95, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "A non-magnetic material among the following is", "q_te": "క్రింది వాటిలో అయస్కాంత పదార్థం కానిది", "opts": [{"en": "Iron", "te": "ఇనుము"}, {"en": "Cobalt", "te": "కోబాల్ట్"}, {"en": "Nickel", "te": "నికెల్"}, {"en": "Wood", "te": "చెక్క"}], "ans": 4, "exp_en": "Iron, cobalt and nickel are ferromagnetic; wood is non-magnetic.", "exp_te": "ఐరన్, కోబాల్ట్, నికెల్ అయస్కాంత పదార్థాలు; చెక్క అయస్కాంతేతరం."}, {"id": 96, "sec": "విద్యుత్ అయస్కాంతత్వం | Magnetism & Electromagnetism", "passage": "", "q_en": "If you cut a magnet into two pieces, the number of poles each piece has", "q_te": "అయస్కాంతాన్ని రెండు ముక్కలు చేస్తే ఒక్కో ముక్కకు ఉండే ధ్రువాల సంఖ్య", "opts": [{"en": "1", "te": "1"}, {"en": "2", "te": "2"}, {"en": "3", "te": "3"}, {"en": "4", "te": "4"}], "ans": 2, "exp_en": "Magnetic poles always exist in pairs, so each piece again has a north and a south pole.", "exp_te": "అయస్కాంత ధ్రువాలు ఎప్పుడూ జతలుగానే ఉంటాయి, కాబట్టి ప్రతి ముక్కకూ ఉత్తర, దక్షిణ ధ్రువాలు ఉంటాయి."}, {"id": 97, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Bauxite is an ore of this metal", "q_te": "బాక్సైట్ ఈ లోహపు ధాతువు", "opts": [{"en": "Zinc", "te": "జింక్"}, {"en": "Barium", "te": "బేరియం"}, {"en": "Aluminium", "te": "అల్యూమినియం"}, {"en": "Iron", "te": "ఇనుము"}], "ans": 3, "exp_en": "Bauxite (Al₂O₃·2H₂O) is the chief ore of aluminium.", "exp_te": "బాక్సైట్ (Al₂O₃·2H₂O) అల్యూమినియం ప్రధాన ధాతువు."}, {"id": 98, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Formula of cinnabar is", "q_te": "సిన్నబార్ ఫార్ములా", "opts": [{"en": "$HgS$", "te": "$HgS$"}, {"en": "$PbS$", "te": "$PbS$"}, {"en": "$AlCl_3$", "te": "$AlCl_3$"}, {"en": "$MnO_2$", "te": "$MnO_2$"}], "ans": 1, "exp_en": "Cinnabar is mercury(II) sulphide, HgS.", "exp_te": "సిన్నబార్ అంటే మెర్క్యురీ సల్ఫైడ్, HgS."}, {"id": 99, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "The impurity present in the ore is called", "q_te": "ధాతువులో ఉండే మలినాలను ఈ విధంగా పిలుస్తారు", "opts": [{"en": "Gangue", "te": "గాంగ్ (ఖనిజ మాలిన్యం)"}, {"en": "Flux", "te": "ద్రవకారి"}, {"en": "Slag", "te": "లోహమలం"}, {"en": "Mineral", "te": "ఖనిజం"}], "ans": 1, "exp_en": "The earthy impurity in an ore is gangue (matrix).", "exp_te": "ధాతువులోని మట్టి మలినాన్ని గ్యాంగ్ అంటారు."}, {"id": 100, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "The reducing agent in thermite process is", "q_te": "థర్మైట్ విధానంలో క్షయకరణ కారకం", "opts": [{"en": "Al", "te": "Al"}, {"en": "Mg", "te": "Mg"}, {"en": "Fe", "te": "Fe"}, {"en": "Si", "te": "Si"}], "ans": 1, "exp_en": "In the thermite reaction aluminium powder reduces Fe₂O₃ to iron.", "exp_te": "థర్మిట్ చర్యలో అల్యూమినియం పొడి Fe₂O₃ ను ఐరన్‌గా క్షయకరణం చేస్తుంది."}, {"id": 101, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "The correct formula of gypsum", "q_te": "జిప్సం సరైన ఫార్ములా", "opts": [{"en": "$CuSO_4 \\cdot 2H_2O$", "te": "$CuSO_4 \\cdot 2H_2O$"}, {"en": "$CaSO_4 \\cdot \\frac12 H_2O$", "te": "$CaSO_4 \\cdot \\frac12 H_2O$"}, {"en": "$CuSO_4 \\cdot 5H_2O$", "te": "$CuSO_4 \\cdot 5H_2O$"}, {"en": "$CaSO_4 \\cdot 2H_2O$", "te": "$CaSO_4 \\cdot 2H_2O$"}], "ans": 4, "exp_en": "Gypsum is calcium sulphate dihydrate, CaSO<sub>4</sub>·2H<sub>2</sub>O — two water molecules of crystallisation. CaSO<sub>4</sub>·½H<sub>2</sub>O is Plaster of Paris, and the CuSO<sub>4</sub> formulas are copper salts (CuSO<sub>4</sub>·5H<sub>2</sub>O is blue vitriol).", "exp_te": "జిప్సం అనేది కాల్షియం సల్ఫేట్ డైహైడ్రేట్ — CaSO<sub>4</sub>·2H<sub>2</sub>O. దీనిలో రెండు స్ఫటిక జల అణువులు ఉంటాయి. CaSO<sub>4</sub>·½H<sub>2</sub>O అనేది ప్లాస్టర్ ఆఫ్ పారిస్; CuSO<sub>4</sub> ఫార్ములాలు రాగి లవణాలు (CuSO<sub>4</sub>·5H<sub>2</sub>O = మైలుతుత్తం)."}, {"id": 102, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Corrosion occurs in the presence of", "q_te": "లోహక్షయం వీటి సమక్షంలో జరుగుతుంది", "opts": [{"en": "Oxygen and carbon dioxide", "te": "ఆక్సిజన్, కార్బన్ డై ఆక్సైడ్"}, {"en": "Oxygen and water", "te": "ఆక్సిజన్, నీరు"}, {"en": "Nitrogen and water", "te": "నైట్రోజన్, నీరు"}, {"en": "Oxygen and nitrogen", "te": "ఆక్సిజన్, నైట్రోజన్"}], "ans": 2, "exp_en": "Corrosion (rusting of iron) is an electrochemical oxidation that needs BOTH moisture and oxygen. Iron rusts in damp air but not in dry air or in oxygen-free water: 4Fe + 3O<sub>2</sub> + 2xH<sub>2</sub>O → 2Fe<sub>2</sub>O<sub>3</sub>·xH<sub>2</sub>O.", "exp_te": "లోహ క్షయం (ఇనుము తుప్పు పట్టడం) ఒక విద్యుత్ రసాయన ఆక్సీకరణం. దీనికి తేమ (నీరు) మరియు ఆక్సిజన్ రెండూ అవసరం. పొడి గాలిలో లేదా ఆక్సిజన్ లేని నీటిలో ఇనుము తుప్పు పట్టదు: 4Fe + 3O<sub>2</sub> + 2xH<sub>2</sub>O → 2Fe<sub>2</sub>O<sub>3</sub>·xH<sub>2</sub>O."}, {"id": 103, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Heating the ore in the absence of air or oxygen is called", "q_te": "గాలి లేదా ఆక్సిజన్ లేకుండా ధాతువును వేడి చేయడాన్ని ఈ విధంగా పిలుస్తారు", "opts": [{"en": "Roasting", "te": "భర్జనం"}, {"en": "Smelting", "te": "ప్రగలనం"}, {"en": "Calcination", "te": "భస్మీకరణం"}, {"en": "Refining", "te": "శుద్ధి చేయడం"}], "ans": 3, "exp_en": "Calcination = strong heating of an ore in limited/no air. It drives off water, CO<sub>2</sub> and volatile matter, e.g. CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. It is used mainly for carbonate and hydrated ores.", "exp_te": "భస్మీకరణం (Calcination) = ధాతువును గాలి లేకుండా (లేదా పరిమిత గాలిలో) బలంగా వేడి చేయడం. దీనివల్ల నీరు, CO<sub>2</sub>, బాష్పశీల పదార్థాలు పోతాయి. ఉదా: CaCO<sub>3</sub> → CaO + CO<sub>2</sub>. ఇది ముఖ్యంగా కార్బొనేట్, జలయుత ధాతువులకు వాడతారు."}, {"id": 104, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Heating the ore strongly in the presence of air or oxygen is called", "q_te": "గాలి లేదా ఆక్సిజన్ సమక్షంలో ధాతువును అధిక ఉష్ణోగ్రతకు వేడి చేయడాన్ని ఈ విధంగా పిలుస్తారు", "opts": [{"en": "Roasting", "te": "భర్జనం"}, {"en": "Smelting", "te": "ప్రగలనం"}, {"en": "Calcination", "te": "భస్మీకరణం"}, {"en": "Refining", "te": "శుద్ధి చేయడం"}], "ans": 1, "exp_en": "Roasting = heating the ore strongly in a plentiful supply of air. It is used for sulphide ores, converting them to oxides: 2ZnS + 3O<sub>2</sub> → 2ZnO + 2SO<sub>2</sub>.", "exp_te": "భర్జనము (Roasting) = ధాతువును సమృద్ధిగా గాలి సరఫరా ఉన్న స్థితిలో బలంగా వేడి చేయడం. ఇది సల్ఫైడ్ ధాతువులను ఆక్సైడ్లుగా మార్చడానికి వాడతారు: 2ZnS + 3O<sub>2</sub> → 2ZnO + 2SO<sub>2</sub>."}, {"id": 105, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Heating the ore strongly by adding flux is called", "q_te": "ధాతువును ద్రవకారితో కలిపి అధిక ఉష్ణోగ్రతకు వేడి చేయడాన్ని ఈ విధంగా పిలుస్తారు", "opts": [{"en": "Roasting", "te": "భర్జనం"}, {"en": "Smelting", "te": "ప్రగలనం"}, {"en": "Calcination", "te": "భస్మీకరణం"}, {"en": "Refining", "te": "శుద్ధి చేయడం"}], "ans": 2, "exp_en": "Smelting = heating the roasted/calcined ore with a flux and a reducing agent (coke) in a furnace. The flux combines with the gangue to form fusible slag, e.g. CaO + SiO<sub>2</sub> → CaSiO<sub>3</sub> (slag), while the molten metal separates below.", "exp_te": "ప్రగలనము (Smelting) = భర్జనం/భస్మీకరణం చేసిన ధాతువును ద్రవకారి (flux) మరియు క్షయకరణి (కోక్)తో కలిపి కొలిమిలో వేడి చేయడం. ద్రవకారి మలినాలతో (gangue) కలిసి కరిగే స్లాగ్‌ను ఏర్పరుస్తుంది: CaO + SiO<sub>2</sub> → CaSiO<sub>3</sub>. కరిగిన లోహం కింద వేరుపడుతుంది."}, {"id": 106, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "The most abundant metal in the earth’s crust is", "q_te": "భూపటలంలో అత్యధికంగా లభించే లోహం", "opts": [{"en": "Silver", "te": "వెండి"}, {"en": "Aluminium", "te": "అల్యూమినియం"}, {"en": "Zinc", "te": "జింక్"}, {"en": "Iron", "te": "ఇనుము"}], "ans": 2, "exp_en": "By mass, the crust is about 8% aluminium and 5% iron, so aluminium is the most abundant METAL (oxygen and silicon are more abundant, but they are not metals). Iron is second.", "exp_te": "భారం ప్రకారం భూపటలంలో సుమారు 8% అల్యూమినియం, 5% ఇనుము ఉంటాయి. కాబట్టి అత్యధికంగా లభించే లోహం అల్యూమినియం. (ఆక్సిజన్, సిలికాన్ ఎక్కువగా ఉన్నా అవి లోహాలు కావు.) ఇనుము రెండవ స్థానం."}, {"id": 107, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "Bronze is an alloy of these metals", "q_te": "కంచు ఈ లోహాల మిశ్రమ లోహం", "opts": [{"en": "Iron and copper", "te": "ఇనుము, రాగి"}, {"en": "Copper and aluminium", "te": "రాగి, అల్యూమినియం"}, {"en": "Copper and tin", "te": "రాగి, తగరం"}, {"en": "Zinc and tin", "te": "జింక్, తగరం"}], "ans": 3, "exp_en": "Bronze = copper + tin (roughly 90% Cu, 10% Sn). Brass, in contrast, is copper + zinc. Bronze is harder than pure copper, which is why the Bronze Age followed the Copper Age.", "exp_te": "కంచు (Bronze) = రాగి + తగరం (సుమారు 90% Cu, 10% Sn). ఇత్తడి (Brass) అనేది రాగి + జింక్. కంచు స్వచ్ఛమైన రాగి కంటే గట్టిది, అందుకే రాగి యుగం తర్వాత కంచు యుగం వచ్చింది."}, {"id": 108, "sec": "లోహ సంగ్రహణం | Metallurgy", "passage": "", "q_en": "The oil used in froth floatation process is", "q_te": "నురుగు తేలే ప్రక్రియలో ఉపయోగించే నూనె", "opts": [{"en": "Kerosene oil", "te": "కిరోసిన్"}, {"en": "Pine oil", "te": "పైన్ నూనె"}, {"en": "Coconut oil", "te": "కొబ్బరి నూనె"}, {"en": "Olive oil", "te": "ఆలివ్ నూనె"}], "ans": 2, "exp_en": "Froth floatation concentrates sulphide ores. Pine oil acts as the collector/frother: it wets the sulphide ore particles so they cling to the air bubbles and float up as froth, while the water-wetted gangue sinks.", "exp_te": "నురుగు తేలియాడే పద్ధతి సల్ఫైడ్ ధాతువుల సాంద్రీకరణకు వాడతారు. పైన్ నూనె సంగ్రాహకం/నురుగుకారిగా పనిచేస్తుంది — ఇది సల్ఫైడ్ ధాతువు కణాలను తడిపి, అవి గాలి బుడగలకు అంటుకుని నురుగుగా పైకి తేలుతాయి. నీటితో తడిసిన మలినాలు కింద మునిగిపోతాయి."}, {"id": 109, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Formula of chloroform", "q_te": "క్లోరోఫామ్ ఫార్ములా", "opts": [{"en": "$CH_3COOH$", "te": "$CH_3COOH$"}, {"en": "$CHCl_3$", "te": "$CHCl_3$"}, {"en": "$CH_3CH_2OH$", "te": "$CH_3CH_2OH$"}, {"en": "$CH_4$", "te": "$CH_4$"}], "ans": 2, "exp_en": "Chloroform is trichloromethane, CHCl<sub>3</sub> — methane with three of its four hydrogens replaced by chlorine. CH<sub>3</sub>COOH is acetic acid, CH<sub>3</sub>CH<sub>2</sub>OH is ethanol, CH<sub>4</sub> is methane.", "exp_te": "క్లోరోఫామ్ అంటే ట్రైక్లోరో మీథేన్, CHCl<sub>3</sub> — మీథేన్‌లోని నాలుగు హైడ్రోజన్‌లలో మూడు క్లోరిన్‌తో ప్రతిక్షేపించబడతాయి. CH<sub>3</sub>COOH = ఎసిటిక్ ఆమ్లం, CH<sub>3</sub>CH<sub>2</sub>OH = ఇథనాల్, CH<sub>4</sub> = మీథేన్."}, {"id": 110, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "The major component of biogas and compressed natural gas is", "q_te": "బయోగ్యాస్, CNG లలో ప్రధాన అనుఘటకం", "opts": [{"en": "Ethane", "te": "ఈథేన్"}, {"en": "Methane", "te": "మీథేన్"}, {"en": "Propane", "te": "ప్రొపేన్"}, {"en": "Butane", "te": "బ్యూటేన్"}], "ans": 2, "exp_en": "Methane (CH<sub>4</sub>) is the main constituent — about 50–75% of biogas and about 90%+ of CNG. It is the simplest hydrocarbon and burns with a clean blue flame.", "exp_te": "మీథేన్ (CH<sub>4</sub>) ముఖ్య అనుఘటకం — బయోగ్యాస్‌లో సుమారు 50–75%, CNG లో సుమారు 90% పైగా ఉంటుంది. ఇది సరళమైన హైడ్రోకార్బన్; స్వచ్ఛమైన నీలి మంటతో మండుతుంది."}, {"id": 111, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Butanone is a four carbon compound with the functional group", "q_te": "బ్యూటనోన్ నాలుగు కార్బన్ల సమ్మేళనం, దాని ప్రమేయ సమూహం", "opts": [{"en": "Carboxylic acid", "te": "కార్బాక్సిలిక్ ఆమ్లం"}, {"en": "Aldehyde", "te": "ఆల్డిహైడ్"}, {"en": "Ketone", "te": "కీటోన్"}, {"en": "Alcohol", "te": "ఆల్కహాల్"}], "ans": 3, "exp_en": "The suffix '-one' marks a ketone (C=O in the middle of the chain). Butanone is CH<sub>3</sub>–CO–CH<sub>2</sub>–CH<sub>3</sub>. '-ol' would be an alcohol, '-al' an aldehyde, '-oic acid' a carboxylic acid.", "exp_te": "'-one' అనే ప్రత్యయం కీటోన్‌ను సూచిస్తుంది (గొలుసు మధ్యలో C=O). బ్యుటనోన్ = CH<sub>3</sub>–CO–CH<sub>2</sub>–CH<sub>3</sub>. '-ol' అంటే ఆల్కహాల్, '-al' అంటే ఆల్డిహైడ్, '-oic acid' అంటే కార్బాక్సిలిక్ ఆమ్లం."}, {"id": 112, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Saturated hydrocarbon among the following", "q_te": "క్రింది వాటిలో సంతృప్త హైడ్రోకార్బన్", "opts": [{"en": "Ethane", "te": "ఈథేన్"}, {"en": "Ethene", "te": "ఈథీన్"}, {"en": "Ethyne", "te": "ఈథైన్"}, {"en": "Methene", "te": "మీథీన్"}], "ans": 1, "exp_en": "Saturated hydrocarbons (alkanes, '-ane') have only single C–C bonds. Ethane is C<sub>2</sub>H<sub>6</sub>. Ethene (C<sub>2</sub>H<sub>4</sub>) has a double bond and ethyne (C<sub>2</sub>H<sub>2</sub>) a triple bond — both unsaturated. 'Methene' does not exist, as one carbon cannot form a C=C bond.", "exp_te": "సంతృప్త హైడ్రోకార్బన్‌లు (ఆల్కేన్‌లు, '-ane') కేవలం ఏక C–C బంధాలను మాత్రమే కలిగి ఉంటాయి. ఈథేన్ = C<sub>2</sub>H<sub>6</sub>. ఈథీన్ (C<sub>2</sub>H<sub>4</sub>) ద్విబంధం, ఇథైన్ (C<sub>2</sub>H<sub>2</sub>) త్రిబంధం కలిగి అసంతృప్తమైనవి. 'మీథీన్' అనేది ఉండదు — ఒకే కార్బన్‌తో C=C బంధం సాధ్యం కాదు."}, {"id": 113, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Chemical formula of benzene is", "q_te": "బెంజీన్ రసాయన ఫార్ములా", "opts": [{"en": "$C_4H_{10}$", "te": "$C_4H_{10}$"}, {"en": "$C_5H_6$", "te": "$C_5H_6$"}, {"en": "$C_6H_6$", "te": "$C_6H_6$"}, {"en": "$C_6H_{12}$", "te": "$C_6H_{12}$"}], "ans": 3, "exp_en": "Benzene is C<sub>6</sub>H<sub>6</sub> — a six-carbon ring with alternating double bonds, the simplest aromatic hydrocarbon. C<sub>4</sub>H<sub>10</sub> is butane and C<sub>6</sub>H<sub>12</sub> is cyclohexane/hexene.", "exp_te": "బెంజీన్ = C<sub>6</sub>H<sub>6</sub> — ఏకాంతర ద్విబంధాలు గల ఆరు కార్బన్ల వలయం; సరళమైన ఆరోమాటిక్ హైడ్రోకార్బన్. C<sub>4</sub>H<sub>10</sub> = బ్యూటేన్, C<sub>6</sub>H<sub>12</sub> = సైక్లోహెక్సేన్/హెక్సీన్."}, {"id": 114, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Formula of alcohol functional group", "q_te": "ఆల్కహాల్ ప్రమేయ సమూహ ఫార్ములా", "opts": [{"en": "$-OH$", "te": "$-OH$"}, {"en": "$-COOH$", "te": "$-COOH$"}, {"en": "$-CHO$", "te": "$-CHO$"}, {"en": "$-NH_2$", "te": "$-NH_2$"}], "ans": 1, "exp_en": "The alcohol functional group is the hydroxyl group –OH (as in ethanol, CH<sub>3</sub>CH<sub>2</sub>OH). –COOH is carboxylic acid, –CHO is aldehyde, –NH<sub>2</sub> is amine.", "exp_te": "ఆల్కహాల్ ప్రమేయ సమూహం హైడ్రాక్సిల్ సమూహం –OH (ఉదా: ఇథనాల్, CH<sub>3</sub>CH<sub>2</sub>OH). –COOH = కార్బాక్సిలిక్ ఆమ్లం, –CHO = ఆల్డిహైడ్, –NH<sub>2</sub> = అమైన్."}, {"id": 115, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Catalyst used in the hydrogenation of oils", "q_te": "నూనెల హైడ్రోజనీకరణంలో ఉపయోగించే ఉత్ప్రేరకం", "opts": [{"en": "Iron", "te": "ఇనుము"}, {"en": "Nickel", "te": "నికెల్"}, {"en": "Chromium", "te": "క్రోమియం"}, {"en": "Manganese", "te": "మాంగనీస్"}], "ans": 2, "exp_en": "Unsaturated vegetable oils are converted to solid fats (vanaspati) by adding hydrogen across their double bonds at about 200 °C using finely divided NICKEL as catalyst. Iron is the catalyst in the Haber process for ammonia, not here.", "exp_te": "అసంతృప్త వృక్ష నూనెలను, వాటి ద్విబంధాలకు హైడ్రోజన్ కలపడం ద్వారా ఘన కొవ్వులుగా (వనస్పతి) మారుస్తారు. ఇది సుమారు 200 °C వద్ద సన్నని నికెల్ పొడిని ఉత్ప్రేరకంగా వాడి జరుగుతుంది. ఐరన్ అనేది అమ్మోనియా తయారీ (హేబర్ పద్ధతి)లో ఉత్ప్రేరకం, ఇక్కడ కాదు."}, {"id": 116, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Ethanol is commonly called", "q_te": "ఇథనాల్‌ను సాధారణంగా ఇలా పిలుస్తారు", "opts": [{"en": "Alcohol", "te": "ఆల్కహాల్"}, {"en": "Acid", "te": "ఆమ్లం"}, {"en": "Ketone", "te": "కీటోన్"}, {"en": "Ester", "te": "ఎస్టర్"}], "ans": 1, "exp_en": "Ethanol, CH<sub>3</sub>CH<sub>2</sub>OH, is the alcohol in alcoholic drinks, so in everyday use 'alcohol' means ethanol. Its '-ol' ending marks the –OH group.", "exp_te": "ఇథనాల్, CH<sub>3</sub>CH<sub>2</sub>OH, మద్య పానీయాలలో ఉండే ఆల్కహాల్. అందుకే వాడుక భాషలో 'ఆల్కహాల్' అంటే ఇథనాల్. దీని '-ol' ప్రత్యయం –OH సమూహాన్ని సూచిస్తుంది."}, {"id": 117, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Ethanoic acid is commonly called", "q_te": "ఇథనోయిక్ ఆమ్లం సాధారణ నామం", "opts": [{"en": "Hydrochloric acid", "te": "హైడ్రోక్లోరిక్ ఆమ్లం"}, {"en": "Sulphuric acid", "te": "సల్ఫ్యూరిక్ ఆమ్లం"}, {"en": "Acetic acid", "te": "ఎసిటిక్ ఆమ్లం"}, {"en": "Nitric acid", "te": "నైట్రిక్ ఆమ్లం"}], "ans": 3, "exp_en": "Ethanoic acid (CH<sub>3</sub>COOH) is the IUPAC name; its common name is acetic acid. A 5–8% solution of it in water is vinegar.", "exp_te": "ఇథనోయిక్ ఆమ్లం (CH<sub>3</sub>COOH) అనేది IUPAC నామం; దీని సాధారణ నామం ఎసిటిక్ ఆమ్లం. నీటిలో దీని 5–8% ద్రావణమే వెనిగర్."}, {"id": 118, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "The name of the hydrocarbon $C_4H_8$", "q_te": "$C_4H_8$ హైడ్రోకార్బన్ పేరు", "opts": [{"en": "Butane", "te": "బ్యూటేన్"}, {"en": "Butene", "te": "బ్యూటీన్"}, {"en": "Butyne", "te": "బ్యూటైన్"}, {"en": "Propane", "te": "ప్రొపేన్"}], "ans": 2, "exp_en": "For n = 4: alkane C<sub>n</sub>H<sub>2n+2</sub> = C<sub>4</sub>H<sub>10</sub> (butane); alkene C<sub>n</sub>H<sub>2n</sub> = C<sub>4</sub>H<sub>8</sub> (butene); alkyne C<sub>n</sub>H<sub>2n−2</sub> = C<sub>4</sub>H<sub>6</sub> (butyne). So C<sub>4</sub>H<sub>8</sub> is butene.", "exp_te": "n = 4 కోసం: ఆల్కేన్ C<sub>n</sub>H<sub>2n+2</sub> = C<sub>4</sub>H<sub>10</sub> (బ్యూటేన్); ఆల్కీన్ C<sub>n</sub>H<sub>2n</sub> = C<sub>4</sub>H<sub>8</sub> (బ్యూటీన్); ఆల్కైన్ C<sub>n</sub>H<sub>2n−2</sub> = C<sub>4</sub>H<sub>6</sub> (బ్యూటైన్). కాబట్టి C<sub>4</sub>H<sub>8</sub> = బ్యూటీన్."}, {"id": 119, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Carbon has the ability to form long chains with other carbon atoms. This is called", "q_te": "కార్బన్ ఇతర కార్బన్ పరమాణువులతో పొడవైన గొలుసులు ఏర్పరచే సామర్థ్యం", "opts": [{"en": "Isomerism", "te": "సాదృశ్యత"}, {"en": "Catenation", "te": "శృంఖల సామర్థ్యం (కాటనేషన్)"}, {"en": "Formation of multiple bonds", "te": "బహుబంధాల ఏర్పాటు"}, {"en": "Substitution", "te": "ప్రతిక్షేపణ"}], "ans": 2, "exp_en": "Catenation is the self-linking of like atoms into chains or rings. Carbon shows it best because its C–C bond is short and very strong, which is why millions of carbon compounds exist. Isomerism is different compounds with the same formula.", "exp_te": "శృంఖల ధర్మం (Catenation) అంటే ఒకే మూలకపు పరమాణువులు తమలో తాము కలిసి గొలుసులు లేదా వలయాలు ఏర్పరచడం. కార్బన్ C–C బంధం చిన్నదిగా, చాలా బలంగా ఉండటం వల్ల ఇది కార్బన్‌లో అత్యధికం — అందుకే లక్షలాది కార్బన్ సమ్మేళనాలు ఉన్నాయి. సాదృశ్యత అంటే ఒకే ఫార్ములాతో వేరువేరు సమ్మేళనాలు."}, {"id": 120, "sec": "కార్బన్ సమ్మేళనాలు | Carbon Compounds", "passage": "", "q_en": "Methane undergoes substitution reaction with chlorine in the presence of sunlight to form", "q_te": "సూర్యకాంతి సమక్షంలో మీథేన్ క్లోరిన్‌తో ప్రతిక్షేపణ చర్య జరిపి ఏర్పరచేవి", "opts": [{"en": "Methyl chloride and HCl", "te": "మిథైల్ క్లోరైడ్, HCl"}, {"en": "Ethyl chloride and HCl", "te": "ఇథైల్ క్లోరైడ్, HCl"}, {"en": "Methyl chloride and $CO_2$", "te": "మిథైల్ క్లోరైడ్, $CO_2$"}, {"en": "Ethyl chloride and $CO_2$", "te": "ఇథైల్ క్లోరైడ్, $CO_2$"}], "ans": 1, "exp_en": "CH<sub>4</sub> + Cl<sub>2</sub> --(sunlight)--> CH<sub>3</sub>Cl + HCl. One hydrogen of methane is replaced (substituted) by chlorine, giving methyl chloride and hydrogen chloride. No carbon–carbon bond is made, so ethyl chloride cannot form, and with no oxygen present CO<sub>2</sub> cannot form either.", "exp_te": "CH<sub>4</sub> + Cl<sub>2</sub> --(సూర్యకాంతి)--> CH<sub>3</sub>Cl + HCl. మీథేన్‌లోని ఒక హైడ్రోజన్ స్థానంలో క్లోరిన్ ప్రతిక్షేపించబడి మిథైల్ క్లోరైడ్ మరియు హైడ్రోజన్ క్లోరైడ్ ఏర్పడతాయి. కార్బన్–కార్బన్ బంధం ఏర్పడదు కాబట్టి ఇథైల్ క్లోరైడ్ రాదు; ఆక్సిజన్ లేనందున CO<sub>2</sub> కూడా రాదు."}, {"id": 121, "sec": "స్థిర విద్యుత్ | Static Electricity", "passage": "", "q_en": "The following cannot be charged easily by friction", "q_te": "ఘర్షణ ద్వారా సులభంగా ఆవేశితం చేయలేనిది", "opts": [{"en": "A plastic scale", "te": "ప్లాస్టిక్ స్కేలు"}, {"en": "A copper rod", "te": "రాగి కడ్డీ"}, {"en": "An inflated balloon", "te": "గాలి నింపిన బెలూన్"}, {"en": "A woollen cloth", "te": "ఉన్ని వస్త్రం"}], "ans": 2, "exp_en": "Charging by friction works only on insulators, where the transferred charge stays put. Copper is a good conductor: any charge produced immediately leaks away through the hand and body to the earth, so a copper rod held in the hand cannot be charged by rubbing. Plastic, rubber and wool are insulators.", "exp_te": "ఘర్షణ ద్వారా ఆవేశీకరణ అవాహకాలలోనే (insulators) పనిచేస్తుంది — అక్కడ బదిలీ అయిన ఆవేశం ఆ స్థానంలోనే ఉండిపోతుంది. రాగి మంచి వాహకం: ఏర్పడిన ఆవేశం వెంటనే చేతి, శరీరం ద్వారా భూమికి ప్రవహించి పోతుంది. అందుకే చేతితో పట్టుకున్న రాగి కడ్డీని రుద్దడం ద్వారా ఆవేశితం చేయలేము. ప్లాస్టిక్, రబ్బరు, ఉన్ని అవాహకాలు."}, {"id": 122, "sec": "స్థిర విద్యుత్ | Static Electricity", "passage": "", "q_en": "Choose the correct option.\nA: Like charges repel each other.\nB: Unlike charges attract each other.", "q_te": "సరైన ఐచ్ఛికాన్ని ఎంచుకోండి.\nA: సజాతి ఆవేశాలు వికర్షించుకుంటాయి.\nB: విజాతి ఆవేశాలు ఆకర్షించుకుంటాయి.", "opts": [{"en": "Both A and B are correct", "te": "A, B రెండూ సరైనవి"}, {"en": "Both A and B are incorrect", "te": "A, B రెండూ సరికావు"}, {"en": "A is correct, B is incorrect", "te": "A సరైనది, B సరికాదు"}, {"en": "A is incorrect, B is correct", "te": "A సరికాదు, B సరైనది"}], "ans": 1, "exp_en": "Both statements state the basic law of electrostatics correctly: like charges (+ and +, or − and −) repel; unlike charges (+ and −) attract.", "exp_te": "రెండు ప్రవచనాలు స్థిర విద్యుత్ ప్రాథమిక నియమాన్ని సరిగ్గా తెలియజేస్తాయి: సజాతి ఆవేశాలు (+ మరియు +, లేదా − మరియు −) వికర్షించుకుంటాయి; విజాతి ఆవేశాలు (+ మరియు −) ఆకర్షించుకుంటాయి."}, {"id": 123, "sec": "స్థిర విద్యుత్ | Static Electricity", "passage": "", "q_en": "A device used to test whether an object is carrying a charge or not is", "q_te": "వస్తువుకు ఆవేశం ఉందో లేదో పరీక్షించే పరికరం", "opts": [{"en": "Microscope", "te": "సూక్ష్మదర్శిని"}, {"en": "Colonoscope", "te": "కొలనోస్కోప్"}, {"en": "Electroscope", "te": "విద్యుద్దర్శిని"}, {"en": "Telescope", "te": "దూరదర్శిని"}], "ans": 3, "exp_en": "An electroscope detects charge. In a gold-leaf electroscope, touching the metal disc with a charged body sends charge down to the two leaves; like charges on the leaves make them repel and diverge.", "exp_te": "ఎలక్ట్రోస్కోప్ ఆవేశాన్ని గుర్తిస్తుంది. బంగారు రేకు ఎలక్ట్రోస్కోప్‌లో లోహపు పళ్ళెంను ఆవేశిత వస్తువుతో తాకిస్తే ఆవేశం రెండు రేకులకు చేరుతుంది; రేకులపై సజాతి ఆవేశాలు ఉండటం వల్ల వికర్షించుకుని విచ్చుకుంటాయి."}, {"id": 124, "sec": "స్థిర విద్యుత్ | Static Electricity", "passage": "", "q_en": "When a glass rod is rubbed with a silk cloth", "q_te": "గాజు కడ్డీని పట్టు వస్త్రంతో రుద్దినప్పుడు", "opts": [{"en": "Both acquire positive charge", "te": "రెండూ ధనావేశం పొందుతాయి"}, {"en": "Both acquire negative charge", "te": "రెండూ ఋణావేశం పొందుతాయి"}, {"en": "The rod acquires positive charge and the cloth negative charge", "te": "కడ్డీ ధనావేశం, వస్త్రం ఋణావేశం పొందుతాయి"}, {"en": "The rod acquires negative charge and the cloth positive charge", "te": "కడ్డీ ఋణావేశం, వస్త్రం ధనావేశం పొందుతాయి"}], "ans": 3, "exp_en": "Glass holds electrons less tightly than silk, so on rubbing, electrons pass from the glass to the silk. Having lost electrons the glass rod becomes positively charged and the silk, having gained them, becomes negatively charged. Charge is only transferred, never created — the two charges are equal and opposite.", "exp_te": "సిల్కు కంటే గాజు ఎలక్ట్రాన్లను తక్కువ బలంగా పట్టి ఉంచుతుంది. కాబట్టి రుద్దినప్పుడు ఎలక్ట్రాన్లు గాజు నుండి సిల్కుకు బదిలీ అవుతాయి. ఎలక్ట్రాన్లు కోల్పోయిన గాజు కడ్డీ ధనావేశం, ఎలక్ట్రాన్లు పొందిన సిల్కు ఋణావేశం పొందుతాయి. ఆవేశం సృష్టించబడదు, కేవలం బదిలీ అవుతుంది — రెండు ఆవేశాలు సమానం, వ్యతిరేకం."}, {"id": 125, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The uppermost layer of the earth", "q_te": "భూమి పై పొర", "opts": [{"en": "Crust", "te": "భూపటలం"}, {"en": "Mantle", "te": "భూప్రావారం"}, {"en": "Inner core", "te": "అంతర కేంద్రం"}, {"en": "Outer core", "te": "బాహ్య కేంద్రం"}], "ans": 1, "exp_en": "Earth's layers from outside in are: crust (thinnest, about 5–70 km), mantle, outer core, inner core. So the topmost layer is the crust.", "exp_te": "భూమి పొరలు బయటి నుండి లోపలికి: భూపటలం (అతి పల్చన, సుమారు 5–70 కి.మీ.), భూప్రావారం, బాహ్య కేంద్రం, అంతర కేంద్రం. కాబట్టి అన్నిటికన్నా పైన ఉన్న పొర భూపటలం."}, {"id": 126, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Physical change among the following is", "q_te": "క్రింది వాటిలో భౌతిక మార్పు", "opts": [{"en": "Converting ice into water", "te": "మంచు నీరుగా మారడం"}, {"en": "Rusting of iron", "te": "ఇనుము తుప్పు పట్టడం"}, {"en": "Burning of magnesium ribbon", "te": "మెగ్నీషియం రిబ్బను మండడం"}, {"en": "Changing milk into curd", "te": "పాలు పెరుగుగా మారడం"}], "ans": 1, "exp_en": "Melting ice only changes the state of H<sub>2</sub>O; the substance is the same and the change is reversible by freezing — so it is physical. Rusting, burning magnesium and curdling all form new substances with new properties, so they are chemical changes.", "exp_te": "మంచు కరగడం వల్ల H<sub>2</sub>O యొక్క స్థితి మాత్రమే మారుతుంది; పదార్థం అదే, మరల ఘనీభవనం ద్వారా వెనక్కి తేవచ్చు — కాబట్టి ఇది భౌతిక మార్పు. తుప్పు పట్టడం, మెగ్నీషియం మండటం, పాలు పెరుగవడం — ఇవన్నీ నూతన ధర్మాలు గల కొత్త పదార్థాలను ఏర్పరుస్తాయి, కాబట్టి రసాయన మార్పులు."}, {"id": 127, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The gas released by the action of vinegar with baking soda", "q_te": "వెనిగర్, వంటసోడా చర్యలో విడుదలయ్యే వాయువు", "opts": [{"en": "Hydrogen", "te": "హైడ్రోజన్"}, {"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Carbon dioxide", "te": "కార్బన్ డై ఆక్సైడ్"}, {"en": "Nitrogen", "te": "నైట్రోజన్"}], "ans": 3, "exp_en": "CH<sub>3</sub>COOH + NaHCO<sub>3</sub> → CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub>. The brisk fizzing is carbon dioxide, which turns lime water milky — the standard test.", "exp_te": "CH<sub>3</sub>COOH + NaHCO<sub>3</sub> → CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub>. వేగంగా వచ్చే బుడగలు కార్బన్ డైఆక్సైడ్. ఇది సున్నపు తేటను పాలవలె తెల్లగా మారుస్తుంది — ఇదే ప్రామాణిక పరీక్ష."}, {"id": 128, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The chemical change among the following is", "q_te": "క్రింది వాటిలో రసాయన మార్పు", "opts": [{"en": "Converting ice into water", "te": "మంచుగడ్డ నీరుగా మారడం"}, {"en": "Cutting a paper into four parts", "te": "కాగితాన్ని నాలుగు భాగాలుగా కత్తిరించడం"}, {"en": "Stretching a rubber band", "te": "రబ్బరు బ్యాండును సాగదీయడం"}, {"en": "Burning crackers", "te": "బాణసంచా కాల్చడం"}], "ans": 4, "exp_en": "Burning crackers produces new substances (gases, smoke, ash) with heat, light and sound, and cannot be reversed — a chemical change. Melting ice, cutting paper and stretching rubber only change form or state, so they are physical changes.", "exp_te": "బాణాసంచా కాల్చడం వల్ల వేడి, కాంతి, ధ్వనితో పాటు కొత్త పదార్థాలు (వాయువులు, పొగ, బూడిద) ఏర్పడతాయి; దీనిని వెనక్కి తేలేము — కాబట్టి రసాయన మార్పు. మంచు కరగడం, కాగితం కత్తిరించడం, రబ్బరు సాగదీయడం — ఇవి ఆకారం/స్థితి మాత్రమే మారుస్తాయి, కాబట్టి భౌతిక మార్పులు."}, {"id": 129, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The process of depositing a layer of this metal on iron articles is called galvanisation", "q_te": "ఇనుప వస్తువులపై ఈ లోహపు పొర పూయడాన్ని గాల్వనైజేషన్ అంటారు", "opts": [{"en": "Aluminium", "te": "అల్యూమినియం"}, {"en": "Chromium", "te": "క్రోమియం"}, {"en": "Zinc", "te": "జింక్"}, {"en": "Copper", "te": "రాగి"}], "ans": 3, "exp_en": "Galvanisation is coating iron or steel with a thin layer of ZINC. The zinc both seals out air and moisture and, being more reactive than iron, corrodes in its place (sacrificial protection) — so the iron is protected even where the coating is scratched.", "exp_te": "గాల్వనీకరణం అంటే ఇనుము లేదా ఉక్కుపై పలుచని జింక్ పొరను పూయడం. జింక్ గాలి, తేమను అడ్డుకోవడంతో పాటు, ఇనుము కంటే అధిక చర్యాశీలత కలిగి ఉండటం వల్ల ఇనుముకు బదులుగా తానే క్షయమవుతుంది (బలిదాన రక్షణ) — అందుకే పూత గీసుకుపోయిన చోట కూడా ఇనుము రక్షింపబడుతుంది."}, {"id": 130, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The chemical name of baking soda is", "q_te": "వంటసోడా రసాయన నామం", "opts": [{"en": "Sodium carbonate", "te": "సోడియం కార్బొనేట్"}, {"en": "Sodium bicarbonate", "te": "సోడియం బైకార్బొనేట్"}, {"en": "Sodium sulphate", "te": "సోడియం సల్ఫేట్"}, {"en": "Sodium chloride", "te": "సోడియం క్లోరైడ్"}], "ans": 2, "exp_en": "Baking soda is sodium bicarbonate (sodium hydrogen carbonate), NaHCO<sub>3</sub>. Washing soda is sodium carbonate, Na<sub>2</sub>CO<sub>3</sub>·10H<sub>2</sub>O, and common salt is sodium chloride.", "exp_te": "వంట సోడా అంటే సోడియం బై కార్బొనేట్ (సోడియం హైడ్రోజన్ కార్బొనేట్), NaHCO<sub>3</sub>. వాషింగ్ సోడా = సోడియం కార్బొనేట్, Na<sub>2</sub>CO<sub>3</sub>·10H<sub>2</sub>O; సాధారణ ఉప్పు = సోడియం క్లోరైడ్."}, {"id": 131, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Choose the correct option.\nA: Iron and rust are different substances.\nB: Condensation is a physical change.", "q_te": "సరైన ఐచ్ఛికాన్ని ఎంచుకోండి.\nA: ఇనుము, తుప్పు వేర్వేరు పదార్థాలు.\nB: సాంద్రీకరణం భౌతిక మార్పు.", "opts": [{"en": "Both A and B are correct", "te": "A, B రెండూ సరైనవి"}, {"en": "Both A and B are incorrect", "te": "A, B రెండూ సరికావు"}, {"en": "A is correct, B is incorrect", "te": "A సరైనది, B సరికాదు"}, {"en": "A is incorrect, B is correct", "te": "A సరికాదు, B సరైనది"}], "ans": 1, "exp_en": "A is correct: iron is the element Fe, rust is hydrated iron(III) oxide Fe<sub>2</sub>O<sub>3</sub>·xH<sub>2</sub>O — a different substance with different properties. B is also correct: condensation is only a change of state from gas to liquid and is reversible, so it is physical. Hence both are correct. NOTE: the printed answer key shows option (4); scientifically option (1) is right, so write (4) if your exam follows the printed key.", "exp_te": "A సరైనది: ఇనుము అనేది మూలకం Fe; తుప్పు అనేది జలయుత ఐరన్(III) ఆక్సైడ్ Fe<sub>2</sub>O<sub>3</sub>·xH<sub>2</sub>O — వేరే ధర్మాలు గల వేరే పదార్థం. B కూడా సరైనది: సాంద్రీకరణం వాయు స్థితి నుండి ద్రవ స్థితికి జరిగే స్థితి మార్పు మాత్రమే, తిరిగి మార్చదగినది — కాబట్టి భౌతిక మార్పు. అందువల్ల రెండూ సరైనవి. గమనిక: ముద్రిత కీలో (4) ఇవ్వబడింది; శాస్త్రీయంగా (1) సరైనది. పరీక్షలో ముద్రిత కీని అనుసరిస్తే (4) రాయండి."}, {"id": 132, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Freezing mixture is a combination of", "q_te": "శీతలీకరణ మిశ్రమం దీని కలయిక", "opts": [{"en": "Ice and water", "te": "మంచు, నీరు"}, {"en": "Ice and common salt", "te": "మంచు, ఉప్పు"}, {"en": "Water and common salt", "te": "నీరు, ఉప్పు"}, {"en": "Water and starch", "te": "నీరు, పిండి పదార్థం"}], "ans": 2, "exp_en": "A freezing mixture is crushed ice + common salt. The salt lowers the freezing point of the ice–water mixture and the melting absorbs latent heat from the surroundings, so the temperature falls well below 0 °C (to about −18 °C) — this is how hand-churned ice cream is made.", "exp_te": "ఘనీభవన మిశ్రమం = పగిలిన మంచు + సాధారణ ఉప్పు. ఉప్పు మంచు–నీటి మిశ్రమం ఘనీభవన స్థానాన్ని తగ్గిస్తుంది; కరిగే సమయంలో పరిసరాల నుండి గుప్త ఉష్ణాన్ని గ్రహిస్తుంది. అందువల్ల ఉష్ణోగ్రత 0 °C కంటే చాలా కిందకు (సుమారు −18 °C) పడిపోతుంది — ఐస్‌క్రీం తయారీలో ఇదే వాడతారు."}, {"id": 133, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The surface phenomenon among the following", "q_te": "క్రింది వాటిలో ఉపరితల దృగ్విషయం", "opts": [{"en": "Melting", "te": "ద్రవీభవనం"}, {"en": "Boiling", "te": "మరుగుట"}, {"en": "Evaporation", "te": "బాష్పీభవనం"}, {"en": "Deposition", "te": "నిక్షేపణం"}], "ans": 3, "exp_en": "Evaporation happens only at the free SURFACE of a liquid, where fast-moving molecules escape, and it occurs at all temperatures. Boiling, in contrast, takes place throughout the bulk of the liquid at a fixed boiling point.", "exp_te": "భాష్పీభవనం ద్రవం యొక్క స్వేచ్ఛా ఉపరితలం వద్ద మాత్రమే జరుగుతుంది — అక్కడ వేగంగా చలించే అణువులు తప్పించుకుంటాయి; ఇది అన్ని ఉష్ణోగ్రతల వద్ద జరుగుతుంది. మరుగుట అనేది నిర్దిష్ట బాష్పీభవన స్థానం వద్ద ద్రవం మొత్తం అంతటా జరుగుతుంది."}, {"id": 134, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Metal present in liquid state at room temperature", "q_te": "గది ఉష్ణోగ్రత వద్ద ద్రవస్థితిలో ఉండే లోహం", "opts": [{"en": "Sodium", "te": "సోడియం"}, {"en": "Potassium", "te": "పొటాషియం"}, {"en": "Calcium", "te": "కాల్షియం"}, {"en": "Mercury", "te": "పాదరసం"}], "ans": 4, "exp_en": "Mercury melts at −39 °C, so it is liquid at room temperature — the only metal that is. (Bromine is the only liquid non-metal.) Sodium, potassium and calcium are all solids at room temperature.", "exp_te": "పాదరసం −39 °C వద్ద ద్రవీభవిస్తుంది, కాబట్టి గది ఉష్ణోగ్రత వద్ద ద్రవంగా ఉంటుంది — ఇదొక్కటే అలాంటి లోహం. (ద్రవ అలోహం బ్రోమిన్ ఒక్కటే.) సోడియం, పొటాషియం, కాల్షియం గది ఉష్ణోగ్రత వద్ద ఘనాలు."}, {"id": 135, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "An example of a metalloid among the following", "q_te": "క్రింది వాటిలో అర్ధలోహానికి ఉదాహరణ", "opts": [{"en": "Silicon", "te": "సిలికాన్"}, {"en": "Iron", "te": "ఇనుము"}, {"en": "Sulphur", "te": "సల్ఫర్"}, {"en": "Chlorine", "te": "క్లోరిన్"}], "ans": 1, "exp_en": "Metalloids show properties of both metals and non-metals — silicon, boron, germanium, arsenic, antimony. Silicon looks metallic and is a semiconductor, but is brittle like a non-metal. Iron is a metal; sulphur and chlorine are non-metals.", "exp_te": "అర్ధలోహాలు లోహాలు, అలోహాల ధర్మాలు రెండింటినీ చూపుతాయి — సిలికాన్, బోరాన్, జెర్మేనియం, ఆర్సెనిక్, ఆంటిమొని. సిలికాన్ లోహంవలె కనిపిస్తుంది, అర్ధవాహకం; కానీ అలోహం వలె పెళుసుగా ఉంటుంది. ఐరన్ లోహం; సల్ఫర్, క్లోరిన్ అలోహాలు."}, {"id": 136, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Example of a homogeneous mixture", "q_te": "సజాతీయ మిశ్రమానికి ఉదాహరణ", "opts": [{"en": "Sand and salt", "te": "ఇసుక, ఉప్పు"}, {"en": "Sugar and salt", "te": "చక్కెర, ఉప్పు"}, {"en": "Water and oil", "te": "నీరు, నూనె"}, {"en": "Salt and water", "te": "ఉప్పు, నీరు"}], "ans": 4, "exp_en": "In a homogeneous mixture the composition is uniform throughout and the parts cannot be seen separately. Salt dissolves fully in water to give one clear solution. Sand+salt and sugar+salt are visibly separate solids, and water+oil forms two distinct layers.", "exp_te": "సజాతీయ మిశ్రమంలో సంఘటనం అంతటా ఏకరీతిగా ఉంటుంది, భాగాలను వేరుగా చూడలేము. ఉప్పు నీటిలో పూర్తిగా కరిగి ఒకే స్వచ్ఛమైన ద్రావణాన్ని ఇస్తుంది. ఇసుక+ఉప్పు, చక్కెర+ఉప్పు వేరువేరుగా కనిపించే ఘనాలు; నీరు+నూనె రెండు వేరువేరు పొరలుగా ఉంటాయి."}, {"id": 137, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Example of a heterogeneous mixture", "q_te": "విజాతీయ మిశ్రమానికి ఉదాహరణ", "opts": [{"en": "Water in alcohol", "te": "ఆల్కహాల్‌లో నీరు"}, {"en": "Salt in water", "te": "నీటిలో ఉప్పు"}, {"en": "Sulphur in carbon disulphide", "te": "కార్బన్ డై సల్ఫైడ్‌లో సల్ఫర్"}, {"en": "Water in oil", "te": "నూనెలో నీరు"}], "ans": 4, "exp_en": "Water and oil are immiscible: they do not dissolve in each other and settle as two visible layers, so the mixture is heterogeneous. The other three are true solutions — the solute dissolves completely, giving a uniform (homogeneous) mixture.", "exp_te": "నీరు, నూనె మిశ్రణీయం కావు: ఒకదానిలో మరొకటి కరగవు, రెండు కనిపించే పొరలుగా ఉంటాయి — కాబట్టి ఇది విజాతీయ మిశ్రమం. మిగిలిన మూడు యథార్థ ద్రావణాలు — ద్రావితం పూర్తిగా కరిగి ఏకరీతి (సజాతీయ) మిశ్రమాన్ని ఇస్తుంది."}, {"id": 138, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The percentage of oxygen and nitrogen in air respectively", "q_te": "గాలిలో ఆక్సిజన్, నైట్రోజన్ శాతాలు వరుసగా", "opts": [{"en": "21, 78", "te": "21, 78"}, {"en": "78, 21", "te": "78, 21"}, {"en": "10, 80", "te": "10, 80"}, {"en": "80, 10", "te": "80, 10"}], "ans": 1, "exp_en": "Dry air by volume is about 78% nitrogen and 21% oxygen, with the remaining ~1% argon, CO<sub>2</sub> and other gases. The question asks oxygen FIRST, so the order is 21, 78.", "exp_te": "ఘనపరిమాణం ప్రకారం పొడి గాలిలో సుమారు 78% నైట్రోజన్, 21% ఆక్సిజన్ ఉంటాయి; మిగిలిన ~1% ఆర్గాన్, CO<sub>2</sub> మరియు ఇతర వాయువులు. ప్రశ్నలో మొదట ఆక్సిజన్ అడిగారు, కాబట్టి క్రమం 21, 78."}, {"id": 139, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "CNG means", "q_te": "CNG అంటే", "opts": [{"en": "Controlled Natural Gas", "te": "Controlled Natural Gas"}, {"en": "Compressed Natural Gas", "te": "Compressed Natural Gas"}, {"en": "Compressed Nature Gas", "te": "Compressed Nature Gas"}, {"en": "Controlled Nature Gas", "te": "Controlled Nature Gas"}], "ans": 2, "exp_en": "CNG = Compressed Natural Gas — natural gas (mainly methane) compressed to about 200–250 times atmospheric pressure so that enough can be stored in a cylinder. It is a clean fuel used in buses and autos.", "exp_te": "CNG = Compressed Natural Gas (సంపీడ్య సహజ వాయువు) — సహజ వాయువు (ముఖ్యంగా మీథేన్)ను వాతావరణ పీడనానికి సుమారు 200–250 రెట్లు సంపీడనం చేస్తారు, అలా సిలిండరులో తగినంత నిల్వ చేయవచ్చు. ఇది బస్సులు, ఆటోలలో వాడే స్వచ్ఛమైన ఇంధనం."}, {"id": 140, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The melting point of ice is nearly (in Kelvin)", "q_te": "మంచు ద్రవీభవన స్థానం సుమారు (కెల్విన్‌లో)", "opts": [{"en": "100", "te": "100"}, {"en": "273.15", "te": "273.15"}, {"en": "0", "te": "0"}, {"en": "373.15", "te": "373.15"}], "ans": 2, "exp_en": "Ice melts at 0 °C. Converting: K = °C + 273.15 = 0 + 273.15 = 273.15 K. (373.15 K = 100 °C is the boiling point of water.)", "exp_te": "మంచు 0 °C వద్ద ద్రవీభవిస్తుంది. మార్పిడి: K = °C + 273.15 = 0 + 273.15 = 273.15 K. (373.15 K = 100 °C అనేది నీటి బాష్పీభవన స్థానం.)"}, {"id": 141, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "An example of a substance that sublimes", "q_te": "ఉత్పతనం చెందే పదార్థానికి ఉదాహరణ", "opts": [{"en": "Camphor", "te": "కర్పూరం"}, {"en": "Common salt", "te": "ఉప్పు"}, {"en": "Ice", "te": "మంచు"}, {"en": "Magnesium", "te": "మెగ్నీషియం"}], "ans": 1, "exp_en": "Sublimation is solid → gas directly, without melting. Camphor does this — a camphor tablet left in the open slowly disappears. Naphthalene balls, iodine, ammonium chloride and dry ice behave the same way.", "exp_te": "ఉత్పతనం అంటే ఘన స్థితి నుండి నేరుగా వాయు స్థితికి మారడం (ద్రవీభవనం లేకుండా). కర్పూరం ఇలాగే చేస్తుంది — బయట ఉంచిన కర్పూరం బిళ్ళ నెమ్మదిగా అదృశ్యమవుతుంది. నాఫ్తలీన్ బంతులు, అయోడిన్, అమ్మోనియం క్లోరైడ్, డ్రై ఐస్ కూడా ఇలాగే ప్రవర్తిస్తాయి."}, {"id": 142, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "Changing directly from gaseous state to solid state without converting into liquid state is called", "q_te": "ద్రవస్థితికి మారకుండా వాయుస్థితి నుండి నేరుగా ఘనస్థితికి మారడం", "opts": [{"en": "Melting", "te": "ద్రవీభవనం"}, {"en": "Sublimation", "te": "ఉత్పతనం"}, {"en": "Deposition", "te": "నిక్షేపణం"}, {"en": "Crystallization", "te": "స్ఫటికీకరణం"}], "ans": 3, "exp_en": "Deposition is the reverse of sublimation: gas → solid directly. Frost forming on a cold windowpane from water vapour is deposition. Sublimation is solid → gas, so it is the opposite of what is asked.", "exp_te": "నిక్షేపణం (Deposition) అనేది ఉత్పతనానికి వ్యతిరేకం: వాయువు → ఘనం నేరుగా. చల్లని కిటికీ అద్దంపై నీటి ఆవిరి నుండి మంచు పొర ఏర్పడటం నిక్షేపణం. ఉత్పతనం అంటే ఘనం → వాయువు, అంటే అడిగినదానికి వ్యతిరేకం."}, {"id": 143, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "The rate of evaporation increases with", "q_te": "బాష్పీభవన రేటు దీనితో పెరుగుతుంది", "opts": [{"en": "Increase in surface area", "te": "ఉపరితల వైశాల్యం పెరుగుదల"}, {"en": "Decrease in temperature", "te": "ఉష్ణోగ్రత తగ్గుదల"}, {"en": "High humidity", "te": "అధిక ఆర్ద్రత"}, {"en": "Decrease in wind speed", "te": "గాలి వేగం తగ్గుదల"}], "ans": 1, "exp_en": "Evaporation is a surface process, so a larger free surface lets more molecules escape per second — spread-out clothes dry faster than bundled ones. Evaporation is also faster at higher temperature, lower humidity and higher wind speed, so the other three options all SLOW it down.", "exp_te": "భాష్పీభవనం ఉపరితల ప్రక్రియ కాబట్టి, స్వేచ్ఛా ఉపరితలం పెద్దదైతే సెకనుకు ఎక్కువ అణువులు తప్పించుకుంటాయి — విడదీసి ఆరబెట్టిన బట్టలు మూటగా ఉన్నవాటికంటే వేగంగా ఆరుతాయి. అధిక ఉష్ణోగ్రత, తక్కువ ఆర్ద్రత, అధిక గాలి వేగం వద్ద కూడా భాష్పీభవనం వేగంగా జరుగుతుంది; కాబట్టి మిగిలిన మూడు ఐచ్ఛికాలు దానిని తగ్గిస్తాయి."}, {"id": 144, "sec": "పదార్థం, మార్పులు, మిశ్రమాలు | Matter, Changes & Mixtures", "passage": "", "q_en": "300 K in Celsius scale", "q_te": "300 K సెల్సియస్ మానంలో", "opts": [{"en": "$100^\\circ C$", "te": "$100^\\circ C$"}, {"en": "$273^\\circ C$", "te": "$273^\\circ C$"}, {"en": "$27^\\circ C$", "te": "$27^\\circ C$"}, {"en": "$573^\\circ C$", "te": "$573^\\circ C$"}], "ans": 3, "exp_en": "Step 1: °C = K − 273. Step 2: °C = 300 − 273 = 27. So 300 K = 27 °C — about normal room temperature.", "exp_te": "సోపానం 1: °C = K − 273. సోపానం 2: °C = 300 − 273 = 27. కాబట్టి 300 K = 27 °C — ఇది సుమారుగా సాధారణ గది ఉష్ణోగ్రత."}, {"id": 145, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The chemical formula of magnesium chloride", "q_te": "మెగ్నీషియం క్లోరైడ్ రసాయన ఫార్ములా", "opts": [{"en": "$MgCl$", "te": "$MgCl$"}, {"en": "$MgCl_2$", "te": "$MgCl_2$"}, {"en": "$Mg_2Cl$", "te": "$Mg_2Cl$"}, {"en": "$Mg_2Cl_2$", "te": "$Mg_2Cl_2$"}], "ans": 2, "exp_en": "Mg has valency 2 and Cl valency 1. Criss-crossing the valencies: Mg<sub>1</sub>Cl<sub>2</sub>, i.e. MgCl<sub>2</sub>. Each Mg<sup>2+</sup> needs two Cl<sup>−</sup> ions to balance the charge.", "exp_te": "Mg సంయోజకత 2, Cl సంయోజకత 1. సంయోజకతలను క్రాస్ చేస్తే: Mg<sub>1</sub>Cl<sub>2</sub>, అంటే MgCl<sub>2</sub>. ప్రతి Mg<sup>2+</sup> ఆవేశాన్ని సమతుల్యం చేయడానికి రెండు Cl<sup>−</sup> అయాన్లు అవసరం."}, {"id": 146, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The molecular mass of $CaCl_2$ is (Ca = 40 u, Cl = 35.5 u)", "q_te": "$CaCl_2$ అణుభారం (Ca = 40 u, Cl = 35.5 u)", "opts": [{"en": "75 u", "te": "75 u"}, {"en": "11 u", "te": "11 u"}, {"en": "106 u", "te": "106 u"}, {"en": "111 u", "te": "111 u"}], "ans": 4, "exp_en": "Step 1: atomic masses — Ca = 40 u, Cl = 35.5 u. Step 2: CaCl<sub>2</sub> = 40 + (2 × 35.5) = 40 + 71 = 111 u.", "exp_te": "సోపానం 1: పరమాణు ద్రవ్యరాశులు — Ca = 40 u, Cl = 35.5 u. సోపానం 2: CaCl<sub>2</sub> = 40 + (2 × 35.5) = 40 + 71 = 111 u."}, {"id": 147, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "Among the following, the element with atomicity one", "q_te": "క్రింది వాటిలో పరమాణుకత ఒకటిగా గల మూలకం", "opts": [{"en": "Helium", "te": "హీలియం"}, {"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Hydrogen", "te": "హైడ్రోజన్"}, {"en": "Nitrogen", "te": "నైట్రోజన్"}], "ans": 1, "exp_en": "Atomicity = number of atoms in one molecule of the element. Helium is a noble gas with a complete outer shell, so it exists as single atoms (He) — atomicity 1, monoatomic. O<sub>2</sub>, H<sub>2</sub> and N<sub>2</sub> are all diatomic (atomicity 2).", "exp_te": "పరమాణుకత = మూలకం యొక్క ఒక అణువులో ఉండే పరమాణువుల సంఖ్య. హీలియం జడ వాయువు; దీని బాహ్య కక్ష్య పూర్తిగా నిండి ఉంటుంది, కాబట్టి ఒంటి పరమాణువుగానే (He) ఉంటుంది — పరమాణుకత 1, ఏక పరమాణుకం. O<sub>2</sub>, H<sub>2</sub>, N<sub>2</sub> అన్నీ ద్విపరమాణుకాలు (పరమాణుకత 2)."}, {"id": 148, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The ratio of nitrogen and hydrogen in ammonia by mass", "q_te": "అమ్మోనియాలో ద్రవ్యరాశి ప్రకారం నైట్రోజన్, హైడ్రోజన్ నిష్పత్తి", "opts": [{"en": "14:3", "te": "14:3"}, {"en": "7:3", "te": "7:3"}, {"en": "7:1", "te": "7:1"}, {"en": "14:1", "te": "14:1"}], "ans": 1, "exp_en": "Step 1: Ammonia is NH<sub>3</sub>. Step 2: mass of N = 1 × 14 = 14 u; mass of H = 3 × 1 = 3 u. Step 3: N : H = 14 : 3.", "exp_te": "సోపానం 1: అమ్మోనియా = NH<sub>3</sub>. సోపానం 2: N ద్రవ్యరాశి = 1 × 14 = 14 u; H ద్రవ్యరాశి = 3 × 1 = 3 u. సోపానం 3: N : H = 14 : 3."}, {"id": 149, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The symbol of carbonate ion is", "q_te": "కార్బొనేట్ అయాన్ సంకేతం", "opts": [{"en": "$CO_3^-$", "te": "$CO_3^-$"}, {"en": "$CO_3^{2-}$", "te": "$CO_3^{2-}$"}, {"en": "$CO_3^{3-}$", "te": "$CO_3^{3-}$"}, {"en": "$CO^{2+}$", "te": "$CO^{2+}$"}], "ans": 2, "exp_en": "The carbonate ion is CO<sub>3</sub><sup>2−</sup> — a polyatomic anion carrying two units of negative charge, which is why it combines with one Ca<sup>2+</sup> (CaCO<sub>3</sub>) or two Na<sup>+</sup> (Na<sub>2</sub>CO<sub>3</sub>).", "exp_te": "కార్బొనేట్ అయాన్ = CO<sub>3</sub><sup>2−</sup> — ఇది రెండు యూనిట్ల ఋణావేశం గల బహుపరమాణుక ఋణ అయాన్. అందుకే ఇది ఒక Ca<sup>2+</sup> (CaCO<sub>3</sub>) తో లేదా రెండు Na<sup>+</sup> (Na<sub>2</sub>CO<sub>3</sub>) లతో కలుస్తుంది."}, {"id": 150, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "Tetra-atomic element among the following is", "q_te": "క్రింది వాటిలో చతుర్ పరమాణుక మూలకం", "opts": [{"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Sulphur", "te": "సల్ఫర్"}, {"en": "Argon", "te": "ఆర్గాన్"}, {"en": "Phosphorus", "te": "ఫాస్ఫరస్"}], "ans": 4, "exp_en": "Phosphorus exists as P<sub>4</sub> molecules — four atoms in a tetrahedron, so atomicity 4 (tetra-atomic). Oxygen is O<sub>2</sub> (diatomic), argon is monoatomic, and sulphur is S<sub>8</sub> (octa-atomic).", "exp_te": "ఫాస్ఫరస్ P<sub>4</sub> అణువులుగా ఉంటుంది — చతుర్ముఖిలో నాలుగు పరమాణువులు, కాబట్టి పరమాణుకత 4 (చతుఃపరమాణుకం). ఆక్సిజన్ O<sub>2</sub> (ద్విపరమాణుకం), ఆర్గాన్ ఏకపరమాణుకం, సల్ఫర్ S<sub>8</sub> (అష్టపరమాణుకం)."}, {"id": 151, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The number of valence shell electrons present in a chlorine atom", "q_te": "క్లోరిన్ పరమాణువు బాహ్య కక్ష్యలో ఎలక్ట్రాన్ల సంఖ్య", "opts": [{"en": "1", "te": "1"}, {"en": "2", "te": "2"}, {"en": "7", "te": "7"}, {"en": "8", "te": "8"}], "ans": 3, "exp_en": "Chlorine has atomic number 17, so its configuration is 2, 8, 7. The outermost (valency) shell holds 7 electrons — it needs just one more to complete the octet, which is why Cl is highly reactive and forms Cl<sup>−</sup>.", "exp_te": "క్లోరిన్ పరమాణు సంఖ్య 17, కాబట్టి దాని ఎలక్ట్రాన్ విన్యాసం 2, 8, 7. బాహ్య (సంయోజకత) కక్ష్యలో 7 ఎలక్ట్రాన్లు ఉంటాయి — అష్టకం పూర్తి చేయడానికి ఇంకొక్క ఎలక్ట్రాన్ చాలు. అందుకే Cl అధిక చర్యాశీలత కలిగి Cl<sup>−</sup> ను ఏర్పరుస్తుంది."}, {"id": 152, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The number of protons present in tritium ($_1H^3$)", "q_te": "ట్రిటియం ($_1H^3$) లో ప్రోటాన్ల సంఖ్య", "opts": [{"en": "1", "te": "1"}, {"en": "2", "te": "2"}, {"en": "3", "te": "3"}, {"en": "4", "te": "4"}], "ans": 1, "exp_en": "In <sub>Z</sub>X<sup>A</sup>, the subscript Z is the atomic number = number of protons, and A is the mass number. For tritium Z = 1, so it has 1 proton; neutrons = A − Z = 3 − 1 = 2. All three hydrogen isotopes (protium, deuterium, tritium) have exactly 1 proton — only their neutron counts differ.", "exp_te": "<sub>Z</sub>X<sup>A</sup> లో కింది సంఖ్య Z అనేది పరమాణు సంఖ్య = ప్రొటాన్ల సంఖ్య; A అనేది ద్రవ్యరాశి సంఖ్య. ట్రిటియంకు Z = 1, కాబట్టి 1 ప్రొటాన్; న్యూట్రాన్లు = A − Z = 3 − 1 = 2. హైడ్రోజన్ మూడు ఐసోటోపులు (ప్రోటియం, డ్యూటీరియం, ట్రిటియం) అన్నిటికీ సరిగ్గా 1 ప్రొటాన్ ఉంటుంది — న్యూట్రాన్ల సంఖ్యలో మాత్రమే తేడా."}, {"id": 153, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "The correct electron configuration of sodium (Na)", "q_te": "సోడియం ఎలక్ట్రాన్ విన్యాసం", "opts": [{"en": "2, 8", "te": "2, 8"}, {"en": "2, 8, 1", "te": "2, 8, 1"}, {"en": "2, 1, 8", "te": "2, 1, 8"}, {"en": "8, 2, 1", "te": "8, 2, 1"}], "ans": 2, "exp_en": "Sodium has atomic number 11, so 11 electrons are filled shell by shell using the 2n<sup>2</sup> rule: K shell 2, L shell 8, M shell the remaining 1 → 2, 8, 1. Its single outer electron is lost easily to give Na<sup>+</sup>.", "exp_te": "సోడియం పరమాణు సంఖ్య 11, కాబట్టి 11 ఎలక్ట్రాన్లను 2n<sup>2</sup> నియమం ప్రకారం కక్ష్యలవారీగా నింపుతారు: K కక్ష్య 2, L కక్ష్య 8, M కక్ష్యలో మిగిలిన 1 → 2, 8, 1. బాహ్య కక్ష్యలోని ఒక్క ఎలక్ట్రాన్ సులభంగా కోల్పోయి Na<sup>+</sup> ఏర్పడుతుంది."}, {"id": 154, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "Rutherford’s alpha particle scattering experiment was responsible for the discovery of", "q_te": "రూథర్‌ఫర్డ్ ఆల్ఫా కణ పరిక్షేపణ ప్రయోగం దీని ఆవిష్కరణకు దారితీసింది", "opts": [{"en": "Atomic nucleus", "te": "పరమాణు కేంద్రకం"}, {"en": "Electron", "te": "ఎలక్ట్రాన్"}, {"en": "Proton", "te": "ప్రోటాన్"}, {"en": "Neutron", "te": "న్యూట్రాన్"}], "ans": 1, "exp_en": "Most alpha particles passed straight through the gold foil, but a very few bounced back through large angles. Rutherford concluded that the atom's positive charge and nearly all its mass are packed into a tiny central NUCLEUS, with the rest of the atom mostly empty space. (Electron — J. J. Thomson; neutron — James Chadwick.)", "exp_te": "బంగారు రేకు గుండా చాలా ఆల్ఫా కణాలు నేరుగా వెళ్ళిపోయాయి, కానీ అతి కొద్ది కణాలు పెద్ద కోణాలలో వెనక్కి మళ్ళాయి. దీని ఆధారంగా పరమాణువు ధనావేశం మరియు దాదాపు మొత్తం ద్రవ్యరాశి అతి చిన్న కేంద్రకంలో కేంద్రీకృతమై ఉన్నాయని, మిగిలిన భాగం ఖాళీ స్థలమని రూథర్‌ఫర్డ్ నిర్ణయించారు. (ఎలక్ట్రాన్ — జె.జె. థామ్సన్; న్యూట్రాన్ — జేమ్స్ ఛాడ్విక్.)"}, {"id": 155, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "Isotopes of an element have", "q_te": "ఒక మూలకపు ఐసోటోపులకు", "opts": [{"en": "The same physical properties", "te": "ఒకే భౌతిక ధర్మాలు"}, {"en": "Different chemical properties", "te": "వేర్వేరు రసాయన ధర్మాలు"}, {"en": "Different number of neutrons", "te": "వేర్వేరు న్యూట్రాన్ల సంఖ్య"}, {"en": "Different atomic numbers", "te": "వేర్వేరు పరమాణు సంఖ్యలు"}], "ans": 3, "exp_en": "Isotopes have the SAME atomic number (same protons) but DIFFERENT mass numbers, so they differ in the number of neutrons — e.g. <sub>6</sub>C<sup>12</sup> and <sub>6</sub>C<sup>14</sup>. Since the electron arrangement is identical, their chemical properties are the same; only physical properties such as mass and density differ.", "exp_te": "ఐసోటోపులకు పరమాణు సంఖ్య ఒకటే (ప్రొటాన్లు సమానం) కానీ ద్రవ్యరాశి సంఖ్యలు వేరువేరు; కాబట్టి న్యూట్రాన్ల సంఖ్యలో తేడా ఉంటుంది — ఉదా: <sub>6</sub>C<sup>12</sup>, <sub>6</sub>C<sup>14</sup>. ఎలక్ట్రాన్ విన్యాసం ఒకటే కాబట్టి రసాయన ధర్మాలు సమానం; ద్రవ్యరాశి, సాంద్రత వంటి భౌతిక ధర్మాలు మాత్రమే వేరుగా ఉంటాయి."}, {"id": 156, "sec": "పరమాణు నిర్మాణం, అణువులు | Atoms & Molecules", "passage": "", "q_en": "Isotope used as a fuel in nuclear reactors", "q_te": "అణు రియాక్టర్లలో ఇంధనంగా ఉపయోగించే ఐసోటోపు", "opts": [{"en": "Cobalt", "te": "కోబాల్ట్"}, {"en": "Uranium", "te": "యురేనియం"}, {"en": "Iodine", "te": "అయోడిన్"}, {"en": "Carbon", "te": "కార్బన్"}], "ans": 2, "exp_en": "Uranium-235 undergoes controlled nuclear fission in a reactor, releasing enormous energy. Cobalt-60 is used in cancer treatment, and iodine-131 in treating goitre — medical uses, not fuel.", "exp_te": "యురేనియం-235 రియాక్టర్‌లో నియంత్రిత కేంద్రక విచ్ఛిత్తికి లోనై అపారమైన శక్తిని విడుదల చేస్తుంది. కోబాల్ట్-60 క్యాన్సర్ చికిత్సలో, అయోడిన్-131 గాయిటర్ చికిత్సలో వాడతారు — అవి వైద్య ఉపయోగాలు, ఇంధనం కాదు."}, {"id": 157, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "The ability of metals to be drawn into thin wires is called", "q_te": "లోహాలను సన్నని తీగలుగా సాగదీయగల సామర్థ్యం", "opts": [{"en": "Malleability", "te": "స్తరణీయత"}, {"en": "Ductility", "te": "తాంతవత"}, {"en": "Sonority", "te": "ధ్వని గుణం"}, {"en": "Lustrous", "te": "ద్యుతి"}], "ans": 2, "exp_en": "Ductility = can be drawn into WIRES (gold and silver are the most ductile). Malleability = can be beaten into thin SHEETS. Sonority = gives a ringing sound when struck; lustre = shines.", "exp_te": "తంతుత్వం (Ductility) = తీగలుగా సాగదీయగల ధర్మం (బంగారం, వెండి అత్యధిక తంతుత్వం కలిగినవి). సారణీయత (Malleability) = పలుచని రేకులుగా సాగగొట్టగల ధర్మం. ధ్వనిగుణం = కొట్టినప్పుడు ధ్వని ఇవ్వడం; ద్యుతిగుణం = మెరుపు."}, {"id": 158, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "All metals exist as solids at room temperature except", "q_te": "గది ఉష్ణోగ్రత వద్ద ఘనస్థితిలో లేని లోహం", "opts": [{"en": "Sodium", "te": "సోడియం"}, {"en": "Magnesium", "te": "మెగ్నీషియం"}, {"en": "Zinc", "te": "జింక్"}, {"en": "Mercury", "te": "పాదరసం"}], "ans": 4, "exp_en": "Mercury's melting point is −39 °C, so it is the only metal that is liquid at room temperature. It is used in thermometers because it expands uniformly and does not wet glass.", "exp_te": "పాదరసం ద్రవీభవన స్థానం −39 °C, కాబట్టి గది ఉష్ణోగ్రత వద్ద ద్రవంగా ఉండే ఒకే ఒక లోహం ఇది. ఇది ఏకరీతిగా వ్యాకోచించడం, గాజును తడపకపోవడం వల్ల థర్మామీటర్లలో వాడతారు."}, {"id": 159, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Most non-metals produce these when their oxides dissolve in water", "q_te": "చాలా అలోహాల ఆక్సైడ్లు నీటిలో కరిగి ఏర్పరచేవి", "opts": [{"en": "Acidic oxides", "te": "ఆమ్ల ఆక్సైడ్లు"}, {"en": "Basic oxides", "te": "క్షార ఆక్సైడ్లు"}, {"en": "Neutral oxides", "te": "తటస్థ ఆక్సైడ్లు"}, {"en": "Peroxides", "te": "పెరాక్సైడ్లు"}], "ans": 1, "exp_en": "Non-metal oxides are acidic: they dissolve in water to give acids, e.g. SO<sub>2</sub> + H<sub>2</sub>O → H<sub>2</sub>SO<sub>3</sub> and CO<sub>2</sub> + H<sub>2</sub>O → H<sub>2</sub>CO<sub>3</sub>. They turn blue litmus red. Metal oxides, by contrast, are basic.", "exp_te": "అలోహ ఆక్సైడ్లు ఆమ్ల స్వభావం కలిగి ఉంటాయి: నీటిలో కరిగి ఆమ్లాలను ఇస్తాయి — ఉదా: SO<sub>2</sub> + H<sub>2</sub>O → H<sub>2</sub>SO<sub>3</sub>, CO<sub>2</sub> + H<sub>2</sub>O → H<sub>2</sub>CO<sub>3</sub>. ఇవి నీలి లిట్మస్‌ను ఎరుపుగా మారుస్తాయి. దీనికి భిన్నంగా లోహ ఆక్సైడ్లు క్షార స్వభావం కలిగి ఉంటాయి."}, {"id": 160, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Metals that have low melting points", "q_te": "అల్ప ద్రవీభవన స్థానాలు గల లోహాలు", "opts": [{"en": "Sodium, Magnesium", "te": "సోడియం, మెగ్నీషియం"}, {"en": "Zinc, Potassium", "te": "జింక్, పొటాషియం"}, {"en": "Gallium, Caesium", "te": "గాలియం, సీజియం"}, {"en": "Calcium, Barium", "te": "కాల్షియం, బేరియం"}], "ans": 3, "exp_en": "Gallium (about 30 °C) and caesium (about 28 °C) melt so easily that they turn liquid on the palm of the hand — the lowest melting points among the metals given. All the other metals listed melt at several hundred degrees.", "exp_te": "గాలియం (సుమారు 30 °C), సీజియం (సుమారు 28 °C) చాలా తక్కువ ఉష్ణోగ్రత వద్దే కరుగుతాయి — అరచేతిలో పెట్టుకుంటేనే ద్రవంగా మారతాయి. ఇచ్చిన లోహాలలో అత్యల్ప ద్రవీభవన స్థానాలు ఇవే. మిగిలిన లోహాలన్నీ కొన్ని వందల డిగ్రీల వద్ద కరుగుతాయి."}, {"id": 161, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Metal that reacts with water", "q_te": "నీటితో చర్య జరిపే లోహం", "opts": [{"en": "Sodium", "te": "సోడియం"}, {"en": "Gold", "te": "బంగారం"}, {"en": "Silver", "te": "వెండి"}, {"en": "Copper", "te": "రాగి"}], "ans": 1, "exp_en": "Sodium is very high in the reactivity series and reacts vigorously even with cold water: 2Na + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub>↑, with so much heat that the hydrogen catches fire. That is why sodium is stored under kerosene. Gold, silver and copper do not react with water.", "exp_te": "సోడియం చర్యాశీలత శ్రేణిలో చాలా పైన ఉంటుంది; చల్లని నీటితో కూడా తీవ్రంగా చర్య జరుపుతుంది: 2Na + 2H<sub>2</sub>O → 2NaOH + H<sub>2</sub>↑. ఇందులో వెలువడే వేడి వల్ల హైడ్రోజన్ మంట పట్టుకుంటుంది. అందుకే సోడియంను కిరోసిన్‌లో నిల్వ చేస్తారు. బంగారం, వెండి, రాగి నీటితో చర్య జరపవు."}, {"id": 162, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Cation present in NaCl", "q_te": "NaCl లో ఉండే కాటయాన్", "opts": [{"en": "$Na^+$", "te": "$Na^+$"}, {"en": "$Na^{2+}$", "te": "$Na^{2+}$"}, {"en": "$Cl^-$", "te": "$Cl^-$"}, {"en": "$Cl^{2-}$", "te": "$Cl^{2-}$"}], "ans": 1, "exp_en": "A cation is the positive ion. Sodium has 1 outer electron (2, 8, 1); losing it gives Na<sup>+</sup>. Chlorine gains that electron to give the anion Cl<sup>−</sup>. Na<sup>2+</sup> does not form, because removing a second electron from the stable 2, 8 core needs far too much energy.", "exp_te": "కేటయాన్ అంటే ధన అయాన్. సోడియంకు బాహ్య కక్ష్యలో 1 ఎలక్ట్రాన్ ఉంటుంది (2, 8, 1); దానిని కోల్పోయి Na<sup>+</sup> అవుతుంది. క్లోరిన్ ఆ ఎలక్ట్రాన్‌ను గ్రహించి ఋణ అయాన్ Cl<sup>−</sup> ను ఇస్తుంది. స్థిరమైన 2, 8 విన్యాసం నుండి రెండో ఎలక్ట్రాన్ తొలగించడానికి చాలా అధిక శక్తి కావాలి, కాబట్టి Na<sup>2+</sup> ఏర్పడదు."}, {"id": 163, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Cation present in $MgCl_2$", "q_te": "$MgCl_2$ లో ఉండే కాటయాన్", "opts": [{"en": "$Mg^+$", "te": "$Mg^+$"}, {"en": "$Mg^{2+}$", "te": "$Mg^{2+}$"}, {"en": "$Cl^-$", "te": "$Cl^-$"}, {"en": "$Cl^{2-}$", "te": "$Cl^{2-}$"}], "ans": 2, "exp_en": "Magnesium's configuration is 2, 8, 2. It loses both outer electrons to reach the stable 2, 8 arrangement, giving Mg<sup>2+</sup> — the cation. The two chlorine atoms take one electron each to become 2 Cl<sup>−</sup>.", "exp_te": "మెగ్నీషియం విన్యాసం 2, 8, 2. స్థిరమైన 2, 8 విన్యాసం పొందడానికి బాహ్య కక్ష్యలోని రెండు ఎలక్ట్రాన్లను కోల్పోయి Mg<sup>2+</sup> కేటయాన్ ఏర్పడుతుంది. రెండు క్లోరిన్ పరమాణువులు ఒక్కొక్క ఎలక్ట్రాన్ గ్రహించి 2 Cl<sup>−</sup> అవుతాయి."}, {"id": 164, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Bond formed by the transfer of electrons from metals to non-metals is", "q_te": "లోహాల నుండి అలోహాలకు ఎలక్ట్రాన్ల బదిలీతో ఏర్పడే బంధం", "opts": [{"en": "Ionic bond", "te": "అయానిక బంధం"}, {"en": "Covalent bond", "te": "సంయోజనీయ బంధం"}, {"en": "Polar covalent bond", "te": "ధ్రువ సంయోజనీయ బంధం"}, {"en": "Non-polar covalent bond", "te": "అధ్రువ సంయోజనీయ బంధం"}], "ans": 1, "exp_en": "Complete TRANSFER of electrons forms oppositely charged ions held by electrostatic attraction — an ionic (electrovalent) bond, as in NaCl. SHARING of electrons, on the other hand, gives a covalent bond.", "exp_te": "ఎలక్ట్రాన్లు పూర్తిగా బదిలీ అయి, వ్యతిరేక ఆవేశ అయాన్లు ఏర్పడి, స్థిర విద్యుత్ ఆకర్షణతో కలిసి ఉండటమే అయానిక (విద్యుత్ సంయోజనీయ) బంధం — ఉదా: NaCl. ఎలక్ట్రాన్లను పంచుకోవడం (sharing) వల్ల సంయోజనీయ బంధం ఏర్పడుతుంది."}, {"id": 165, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "The layer of the earth that is the major source of metals", "q_te": "లోహాలకు ప్రధాన వనరైన భూమి పొర", "opts": [{"en": "Crust", "te": "భూపటలం"}, {"en": "Mantle", "te": "భూప్రావారం"}, {"en": "Inner core", "te": "అంతర కేంద్రం"}, {"en": "Outer core", "te": "బాహ్య కేంద్రం"}], "ans": 1, "exp_en": "All mining is done in the crust — it is the only layer we can reach, and the ores of iron, aluminium, copper and the rest are found there. The mantle and core are far too deep and too hot.", "exp_te": "మొత్తం గనుల తవ్వకం భూపటలంలోనే జరుగుతుంది — మనం చేరగలిగే పొర ఇదొక్కటే; ఇనుము, అల్యూమినియం, రాగి మొదలైన ధాతువులు ఇక్కడే లభిస్తాయి. భూప్రావారం, కేంద్రం చాలా లోతుగా, అత్యధిక వేడిగా ఉంటాయి."}, {"id": 166, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Galvanization is a method of coating a thin layer of this metal", "q_te": "గాల్వనైజేషన్‌లో పూసే పలుచని లోహపు పొర", "opts": [{"en": "Iron", "te": "ఇనుము"}, {"en": "Zinc", "te": "జింక్"}, {"en": "Aluminium", "te": "అల్యూమినియం"}, {"en": "Chromium", "te": "క్రోమియం"}], "ans": 2, "exp_en": "Galvanisation coats iron or steel with ZINC to prevent rusting. Zinc is more reactive than iron, so it corrodes first and protects the iron underneath even if the coating gets scratched.", "exp_te": "గాల్వనీకరణం అంటే తుప్పు పట్టకుండా ఇనుము లేదా ఉక్కుపై జింక్ పూత పూయడం. జింక్ ఇనుము కంటే అధిక చర్యాశీలత కలిగి ఉంటుంది, కాబట్టి అదే ముందు క్షయమై, పూత గీసుకుపోయినా కింద ఉన్న ఇనుమును కాపాడుతుంది."}, {"id": 167, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "To get stainless steel, iron is mixed with", "q_te": "స్టెయిన్‌లెస్ స్టీల్ కోసం ఇనుముతో కలిపేవి", "opts": [{"en": "Nickel and copper", "te": "నికెల్, రాగి"}, {"en": "Nickel and chromium", "te": "నికెల్, క్రోమియం"}, {"en": "Chromium and platinum", "te": "క్రోమియం, ప్లాటినం"}, {"en": "Nickel and platinum", "te": "నికెల్, ప్లాటినం"}], "ans": 2, "exp_en": "Stainless steel = iron + about 18% chromium + about 8% nickel (plus a little carbon). The chromium forms an invisible, tightly-bound oxide film that stops rusting, and the nickel adds strength and shine.", "exp_te": "స్టెయిన్‌లెస్ స్టీల్ = ఇనుము + సుమారు 18% క్రోమియం + సుమారు 8% నికెల్ (కొద్దిగా కార్బన్‌తో). క్రోమియం కంటికి కనిపించని గట్టి ఆక్సైడ్ పొరను ఏర్పరచి తుప్పు పట్టడాన్ని ఆపుతుంది; నికెల్ దృఢత్వం, మెరుపును ఇస్తుంది."}, {"id": 168, "sec": "లోహాలు, అలోహాలు, రసాయన బంధం | Metals, Non-metals & Bonding", "passage": "", "q_en": "Example of a molecule with covalent bond", "q_te": "సంయోజనీయ బంధం గల అణువుకు ఉదాహరణ", "opts": [{"en": "$NaCl$", "te": "$NaCl$"}, {"en": "$AlCl_3$", "te": "$AlCl_3$"}, {"en": "$MgCl_2$", "te": "$MgCl_2$"}, {"en": "$HCl$", "te": "$HCl$"}], "ans": 4, "exp_en": "HCl is formed between two NON-METALS, hydrogen and chlorine, which SHARE a pair of electrons — a covalent bond. NaCl and MgCl<sub>2</sub> are metal + non-metal, so they are ionic.", "exp_te": "HCl రెండు అలోహాల (హైడ్రోజన్, క్లోరిన్) మధ్య ఏర్పడుతుంది; ఇవి ఒక ఎలక్ట్రాన్ జతను పంచుకుంటాయి — ఇదే సంయోజనీయ బంధం. NaCl, MgCl<sub>2</sub> లోహం + అలోహం కలయిక కాబట్టి అయానిక బంధాలు."}, {"id": 169, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "This fibre is called artificial silk", "q_te": "కృత్రిమ పట్టు అని పిలువబడే దారం", "opts": [{"en": "Nylon", "te": "నైలాన్"}, {"en": "Rayon", "te": "రేయాన్"}, {"en": "Acrylic", "te": "యాక్రిలిక్"}, {"en": "Polyester", "te": "పాలిస్టర్"}], "ans": 2, "exp_en": "Rayon is made by chemically treating natural wood pulp (cellulose). It looks and feels like silk but is much cheaper, so it is called artificial silk. Unlike nylon and polyester, it is not fully synthetic — it is a regenerated fibre.", "exp_te": "సహజ కలప గుజ్జు (సెల్యులోజ్)ను రసాయనికంగా శుద్ధి చేసి రేయాన్‌ను తయారుచేస్తారు. ఇది పట్టువలె కనిపిస్తుంది, తగులుతుంది కానీ ధర చాలా తక్కువ; అందుకే కృత్రిమ పట్టు అంటారు. నైలాన్, పాలిస్టర్ లాగా ఇది పూర్తిగా కృత్రిమం కాదు — ఇది పునరుత్పాదిత దారం."}, {"id": 170, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "Polycot is a mixture of", "q_te": "పాలీకాట్ దీని మిశ్రమం", "opts": [{"en": "Polyester and wool", "te": "పాలిస్టర్, ఉన్ని"}, {"en": "Polyester and cotton", "te": "పాలిస్టర్, నూలు"}, {"en": "Polyester and silk", "te": "పాలిస్టర్, పట్టు"}, {"en": "Polyester and nylon", "te": "పాలిస్టర్, నైలాన్"}], "ans": 2, "exp_en": "The name itself tells us: POLY(ester) + COT(ton). Polyester gives strength and wrinkle resistance, cotton gives softness and absorbency. Polywool is polyester + wool.", "exp_te": "పేరే చెబుతుంది: POLY(ester) + COT(ton), అంటే పాలిస్టర్ + నూలు. పాలిస్టర్ దృఢత్వం, ముడతలు పడకుండా ఉండే గుణాన్ని ఇస్తుంది; నూలు మెత్తదనం, చెమటను పీల్చుకునే గుణాన్ని ఇస్తుంది. పాలివూల్ = పాలిస్టర్ + ఉన్ని."}, {"id": 171, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "Thermosetting plastic used in making electrical switches and handles of utensils", "q_te": "విద్యుత్ స్విచ్‌లు, పాత్రల పిడుల తయారీలో వాడే థర్మోసెట్టింగ్ ప్లాస్టిక్", "opts": [{"en": "Bakelite", "te": "బేకలైట్"}, {"en": "Melamine", "te": "మెలమైన్"}, {"en": "Polythene", "te": "పాలిథీన్"}, {"en": "PVC", "te": "PVC"}], "ans": 1, "exp_en": "Bakelite is a thermosetting plastic — once moulded it cannot be softened again by heating. It is a poor conductor of heat and electricity, so it is ideal for switches, plugs and pan handles. Melamine (used in floor tiles and fire-resistant fabric) is also thermosetting, but bakelite is the standard answer for switches and handles. Polythene and PVC are thermoplastics.", "exp_te": "బేకలైట్ ఒక థర్మోసెట్టింగ్ ప్లాస్టిక్ — ఒకసారి అచ్చు వేసిన తర్వాత వేడి చేసి మళ్ళీ మెత్తగా చేయలేము. ఇది ఉష్ణం, విద్యుత్‌లకు అల్ప వాహకం కాబట్టి స్విచ్‌లు, ప్లగ్‌లు, పాత్రల పిడులకు అనుకూలం. మెలమైన్ (నేల టైల్స్, అగ్నినిరోధక వస్త్రాలు) కూడా థర్మోసెట్టింగే, కానీ స్విచ్‌లు, పిడులకు ప్రామాణిక సమాధానం బేకలైట్. పాలిథీన్, పీవీసీ థర్మోప్లాస్టిక్‌లు."}, {"id": 172, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "Artificial fibre used in making parachutes and ropes for rock climbing", "q_te": "పారాచూట్లు, కొండలెక్కే తాళ్ళ తయారీలో వాడే కృత్రిమ దారం", "opts": [{"en": "Rayon", "te": "రేయాన్"}, {"en": "Nylon", "te": "నైలాన్"}, {"en": "Acrylic", "te": "యాక్రిలిక్"}, {"en": "Polyester", "te": "పాలిస్టర్"}], "ans": 2, "exp_en": "Nylon was the first fully synthetic fibre. It is extremely strong, elastic and light, and a nylon thread is stronger than a steel wire of the same thickness — hence parachutes, climbing ropes, seat belts and fishing nets.", "exp_te": "నైలాన్ పూర్తిగా కృత్రిమంగా తయారైన మొదటి దారం. ఇది అత్యంత దృఢం, స్థితిస్థాపకం, తేలికైనది; అదే మందం గల ఉక్కు తీగ కంటే నైలాన్ దారం బలంగా ఉంటుంది — అందుకే పారాచూట్లు, పర్వతారోహణ తాళ్ళు, సీటు బెల్టులు, చేపల వలలు తయారుచేస్తారు."}, {"id": 173, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "Inexhaustible natural resource among the following", "q_te": "క్రింది వాటిలో తరగని సహజ వనరు", "opts": [{"en": "Forest", "te": "అడవులు"}, {"en": "Minerals", "te": "ఖనిజాలు"}, {"en": "Petroleum", "te": "పెట్రోలియం"}, {"en": "Sunlight", "te": "సూర్యకాంతి"}], "ans": 4, "exp_en": "Sunlight is inexhaustible — it keeps arriving no matter how much we use. Minerals and petroleum are exhaustible (they took millions of years to form), and forests, though renewable, can be destroyed by over-exploitation.", "exp_te": "సూర్యరశ్మి తరగని వనరు — ఎంత వాడినా అది నిరంతరం లభిస్తుంది. ఖనిజాలు, పెట్రోలియం తరిగిపోయే వనరులు (ఏర్పడటానికి కోట్ల సంవత్సరాలు పట్టింది); అడవులు పునరుత్పాదకమైనా అతిగా వినియోగిస్తే నశిస్తాయి."}, {"id": 174, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "The process of conversion of dead vegetation into coal is called", "q_te": "చనిపోయిన వృక్షాలు బొగ్గుగా మారే ప్రక్రియ", "opts": [{"en": "Carbonisation", "te": "కార్బనీకరణం"}, {"en": "Oxidation", "te": "ఆక్సీకరణం"}, {"en": "Calcination", "te": "భస్మీకరణం"}, {"en": "Reduction", "te": "క్షయకరణం"}], "ans": 1, "exp_en": "Carbonisation is the very slow conversion of buried dead vegetation into coal under high pressure and temperature, over millions of years and in the absence of air. Because it took so long, coal is a non-renewable fossil fuel.", "exp_te": "కార్బొనైజేషన్ అంటే భూమిలో కూరుకుపోయిన మృత వృక్ష సంపద అధిక పీడనం, ఉష్ణోగ్రతల వద్ద, గాలి లేకుండా, కోట్ల సంవత్సరాలలో నేలబొగ్గుగా నెమ్మదిగా మారే ప్రక్రియ. అంత కాలం పట్టడం వల్లనే బొగ్గు పునరుత్పాదకం కాని శిలాజ ఇంధనం."}, {"id": 175, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "The purest form of carbon among the following is", "q_te": "క్రింది వాటిలో కార్బన్ యొక్క అత్యంత శుద్ధ రూపం", "opts": [{"en": "Coal", "te": "బొగ్గు"}, {"en": "Coke", "te": "కోక్"}, {"en": "Coal tar", "te": "కోల్ తారు"}, {"en": "Coal gas", "te": "కోల్ గ్యాస్"}], "ans": 2, "exp_en": "Coke is what remains when coal is heated strongly in the absence of air (destructive distillation): the volatile matter leaves as coal gas and coal tar, and an almost pure, tough, porous black carbon — coke — is left behind. It is used as a reducing agent in smelting.", "exp_te": "బొగ్గును గాలి లేకుండా బలంగా వేడి చేస్తే (భంజన స్వేదనం) మిగిలేదే కోక్: బాష్పశీల పదార్థాలు కోల్ వాయువు, కోల్ తారు రూపంలో పోతాయి; దాదాపు స్వచ్ఛమైన, గట్టి, సచ్ఛిద్ర నల్ల కార్బన్ — కోక్ — మిగులుతుంది. ఇది ప్రగలనంలో క్షయకరణిగా వాడతారు."}, {"id": 176, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "CNG means", "q_te": "CNG అంటే", "opts": [{"en": "Compressed Natural Gas", "te": "Compressed Natural Gas"}, {"en": "Contract Natural Gas", "te": "Contract Natural Gas"}, {"en": "Compressed Nano Gas", "te": "Compressed Nano Gas"}, {"en": "Contract Nano Gas", "te": "Contract Nano Gas"}], "ans": 1, "exp_en": "CNG stands for Compressed Natural Gas. Because it burns almost completely and leaves very little unburnt carbon or harmful gas, it is a clean fuel used in buses, autos and some industries.", "exp_te": "CNG అంటే Compressed Natural Gas (సంపీడ్య సహజ వాయువు). ఇది దాదాపు పూర్తిగా మండి, కాలని కార్బన్ లేదా హానికర వాయువులను చాలా తక్కువగా మిగిల్చడం వల్ల బస్సులు, ఆటోలు, కొన్ని పరిశ్రమలలో వాడే స్వచ్ఛమైన ఇంధనం."}, {"id": 177, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "This is not an inflammable substance", "q_te": "క్రింది వాటిలో త్వరగా మండే పదార్థం కానిది", "opts": [{"en": "Wood", "te": "కలప"}, {"en": "Petrol", "te": "పెట్రోల్"}, {"en": "Alcohol", "te": "ఆల్కహాల్"}, {"en": "LPG", "te": "ఎల్.పి.జి"}], "ans": 1, "exp_en": "'Inflammable' means it catches fire at once at ordinary temperature — it has a very low ignition temperature. Petrol, alcohol and LPG are inflammable. Wood does burn, but only after being heated to a fairly high ignition temperature, so it is not classed as inflammable.", "exp_te": "'దహనశీలి' (inflammable) అంటే సాధారణ ఉష్ణోగ్రత వద్దే వెంటనే మంట పట్టుకునేది — దీని దహన ఉష్ణోగ్రత చాలా తక్కువ. పెట్రోల్, ఆల్కహాల్, LPG దహనశీలులు. చెక్క మండుతుంది కానీ చాలా ఎక్కువ దహన ఉష్ణోగ్రత వరకు వేడి చేసిన తర్వాతే; కాబట్టి దానిని దహనశీలిగా పరిగణించరు."}, {"id": 178, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "The best fire extinguisher for fires involving electrical equipment and inflammable materials", "q_te": "విద్యుత్ పరికరాలు, త్వరగా మండే పదార్థాల మంటలకు ఉత్తమ అగ్నిమాపకం", "opts": [{"en": "Water", "te": "నీరు"}, {"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Coconut oil", "te": "కొబ్బరి నూనె"}, {"en": "Carbon dioxide", "te": "కార్బన్ డై ఆక్సైడ్"}], "ans": 4, "exp_en": "CO<sub>2</sub> is heavier than air, so it blankets the fire and cuts off the oxygen supply; it also cools as it expands, and being a non-conductor it is safe on live electrical equipment. Water must never be used there — it conducts electricity and can spread burning oil.", "exp_te": "CO<sub>2</sub> గాలి కంటే భారమైనది కాబట్టి మంటపై దుప్పటిలా పరచుకుని ఆక్సిజన్ సరఫరాను ఆపేస్తుంది; వ్యాకోచించేటప్పుడు చల్లబరుస్తుంది కూడా. ఇది అవాహకం కాబట్టి విద్యుత్ ప్రవహిస్తున్న పరికరాలపై సురక్షితం. అక్కడ నీరు ఎప్పుడూ వాడకూడదు — నీరు విద్యుత్‌ను ప్రవహింపజేస్తుంది, మండే నూనెను వ్యాపింపజేస్తుంది."}, {"id": 179, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "The dangerous gas released by the incomplete combustion of fuels is", "q_te": "ఇంధనాల అసంపూర్ణ దహనంలో విడుదలయ్యే ప్రమాదకర వాయువు", "opts": [{"en": "Carbon monoxide", "te": "కార్బన్ మోనాక్సైడ్"}, {"en": "Carbon dioxide", "te": "కార్బన్ డై ఆక్సైడ్"}, {"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Hydrogen", "te": "హైడ్రోజన్"}], "ans": 1, "exp_en": "When oxygen is insufficient, carbon burns only partly and forms carbon monoxide (CO) instead of CO<sub>2</sub>. CO is colourless and odourless and binds to haemoglobin far more strongly than oxygen does, so it can kill — which is why a coal sigri must never be left burning in a closed room.", "exp_te": "ఆక్సిజన్ సరిపడకపోతే కార్బన్ పూర్తిగా మండక CO<sub>2</sub> కు బదులుగా కార్బన్ మోనాక్సైడ్ (CO) ఏర్పడుతుంది. CO రంగు, వాసన లేని వాయువు; ఆక్సిజన్ కంటే ఎంతో బలంగా హీమోగ్లోబిన్‌తో బంధమవుతుంది, కాబట్టి ప్రాణాంతకం. అందుకే మూసిన గదిలో బొగ్గు కుంపటిని మండనివ్వకూడదు."}, {"id": 180, "sec": "కృత్రిమ దారాలు, ఇంధనాలు, దహనం | Synthetic Fibres, Fuels & Combustion", "passage": "", "q_en": "The cleaner fuel among the following is", "q_te": "క్రింది వాటిలో శుభ్రమైన ఇంధనం", "opts": [{"en": "Petrol", "te": "పెట్రోల్"}, {"en": "Diesel", "te": "డీజిల్"}, {"en": "Coal", "te": "బొగ్గు"}, {"en": "CNG", "te": "CNG"}], "ans": 4, "exp_en": "CNG (mainly methane) burns almost completely, giving out very little smoke, unburnt carbon, sulphur dioxide or carbon monoxide. Coal is the dirtiest of the four, releasing smoke, ash and SO<sub>2</sub>.", "exp_te": "CNG (ముఖ్యంగా మీథేన్) దాదాపు పూర్తిగా మండుతుంది; పొగ, కాలని కార్బన్, సల్ఫర్ డై ఆక్సైడ్, కార్బన్ మోనాక్సైడ్ చాలా తక్కువగా వెలువడతాయి. ఇచ్చిన నాలుగింటిలో బొగ్గు అత్యంత కాలుష్యకారి — పొగ, బూడిద, SO<sub>2</sub> విడుదల చేస్తుంది."}, {"id": 181, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Acid among the following", "q_te": "క్రింది వాటిలో ఆమ్లం", "opts": [{"en": "$NaOH$", "te": "$NaOH$"}, {"en": "$CH_3COOH$", "te": "$CH_3COOH$"}, {"en": "$KOH$", "te": "$KOH$"}, {"en": "$NH_4OH$", "te": "$NH_4OH$"}], "ans": 2, "exp_en": "CH<sub>3</sub>COOH (acetic acid) has the –COOH group and releases H<sup>+</sup> in water, so it is an acid. NaOH, KOH and NH<sub>4</sub>OH all contain –OH and release OH<sup>−</sup>, so they are bases.", "exp_te": "CH<sub>3</sub>COOH (ఎసిటిక్ ఆమ్లం) లో –COOH సమూహం ఉంది; నీటిలో H<sup>+</sup> ను విడుదల చేస్తుంది, కాబట్టి ఇది ఆమ్లం. NaOH, KOH, NH<sub>4</sub>OH అన్నిటిలో –OH ఉంది; OH<sup>−</sup> ను విడుదల చేస్తాయి, కాబట్టి ఇవి క్షారాలు."}, {"id": 182, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "This cannot be used as an olfactory indicator", "q_te": "ఘ్రాణ సూచికగా ఉపయోగించలేనిది", "opts": [{"en": "Vanilla essence", "te": "వెనీలా ఎసెన్స్"}, {"en": "Clove oil", "te": "లవంగ నూనె"}, {"en": "Hibiscus", "te": "మందార"}, {"en": "Onion", "te": "ఉల్లిపాయ"}], "ans": 3, "exp_en": "An olfactory indicator works by SMELL — vanilla, clove oil and onion lose their smell in a base but keep it in an acid, so a blind person can use them. Hibiscus has no characteristic smell; it works by changing COLOUR, so it is a visual indicator, not an olfactory one.", "exp_te": "ఘ్రాణ సూచిక వాసన ఆధారంగా పనిచేస్తుంది — వెనీలా, లవంగ నూనె, ఉల్లిపాయ క్షారంలో తమ వాసనను కోల్పోతాయి, ఆమ్లంలో నిలుపుకుంటాయి; కాబట్టి అంధులు వాటిని ఉపయోగించగలరు. మందారానికి ప్రత్యేక వాసన లేదు; అది రంగు మార్పు ద్వారా పనిచేస్తుంది, కాబట్టి అది దృశ్య సూచిక, ఘ్రాణ సూచిక కాదు."}, {"id": 183, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "The gas released by the reaction of zinc with hydrochloric acid", "q_te": "జింక్, హైడ్రోక్లోరిక్ ఆమ్లం చర్యలో విడుదలయ్యే వాయువు", "opts": [{"en": "Oxygen", "te": "ఆక్సిజన్"}, {"en": "Hydrogen", "te": "హైడ్రోజన్"}, {"en": "Nitrogen", "te": "నైట్రోజన్"}, {"en": "Carbon dioxide", "te": "కార్బన్ డై ఆక్సైడ్"}], "ans": 2, "exp_en": "Zn + 2HCl → ZnCl<sub>2</sub> + H<sub>2</sub>↑. Metal + dilute acid always gives salt + hydrogen. The test: bring a burning splinter near the gas and it burns with a pop sound.", "exp_te": "Zn + 2HCl → ZnCl<sub>2</sub> + H<sub>2</sub>↑. లోహం + విలీన ఆమ్లం ఎప్పుడూ లవణం + హైడ్రోజన్‌ను ఇస్తుంది. పరీక్ష: మండుతున్న పుల్లను వాయువు దగ్గర పెడితే 'పప్' అనే శబ్దంతో మండుతుంది."}, {"id": 184, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Acids react with bases to form", "q_te": "ఆమ్లాలు క్షారాలతో చర్య జరిపి ఏర్పరచేవి", "opts": [{"en": "Only salts", "te": "లవణాలు మాత్రమే"}, {"en": "Only water", "te": "నీరు మాత్రమే"}, {"en": "Salt and water", "te": "లవణం, నీరు"}, {"en": "Bases", "te": "క్షారాలు"}], "ans": 3, "exp_en": "This is neutralisation: acid + base → salt + water. For example HCl + NaOH → NaCl + H<sub>2</sub>O. The H<sup>+</sup> of the acid and the OH<sup>−</sup> of the base join to form water, and the rest forms the salt.", "exp_te": "ఇదే తటస్థీకరణ చర్య: ఆమ్లం + క్షారం → లవణం + నీరు. ఉదా: HCl + NaOH → NaCl + H<sub>2</sub>O. ఆమ్లంలోని H<sup>+</sup>, క్షారంలోని OH<sup>−</sup> కలిసి నీరు ఏర్పడుతుంది; మిగిలినవి లవణాన్ని ఏర్పరుస్తాయి."}, {"id": 185, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Bases that are soluble in water are called", "q_te": "నీటిలో కరిగే క్షారాలను ఇలా అంటారు", "opts": [{"en": "Alcohols", "te": "ఆల్కహాల్స్"}, {"en": "Alkaloids", "te": "ఆల్కలాయిడ్లు"}, {"en": "Alkalis", "te": "ఆల్కలీలు"}, {"en": "Alkyls", "te": "ఆల్కైల్స్"}], "ans": 3, "exp_en": "A water-soluble base is an alkali — NaOH, KOH, Ca(OH)<sub>2</sub>. So all alkalis are bases, but not all bases are alkalis: copper hydroxide, for instance, is a base that does not dissolve in water.", "exp_te": "నీటిలో కరిగే క్షారాన్ని ఆల్కలీ అంటారు — NaOH, KOH, Ca(OH)<sub>2</sub>. కాబట్టి ఆల్కలీలన్నీ క్షారాలే, కానీ క్షారాలన్నీ ఆల్కలీలు కావు: ఉదాహరణకు కాపర్ హైడ్రాక్సైడ్ ఒక క్షారం, కానీ నీటిలో కరగదు."}, {"id": 186, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Acidic solution among the following is", "q_te": "క్రింది వాటిలో ఆమ్ల ద్రావణం", "opts": [{"en": "Gastric juice", "te": "జఠర రసం"}, {"en": "Pure water", "te": "శుద్ధ నీరు"}, {"en": "Milk of magnesia", "te": "మిల్క్ ఆఫ్ మెగ్నీషియా"}, {"en": "Sodium hydroxide", "te": "సోడియం హైడ్రాక్సైడ్"}], "ans": 1, "exp_en": "Gastric juice in the stomach contains hydrochloric acid, with pH about 1.2–3 — strongly acidic. Pure water is neutral (pH 7), while milk of magnesia and NaOH are basic (pH above 7).", "exp_te": "కడుపులోని జీర్ణరసంలో హైడ్రోక్లోరిక్ ఆమ్లం ఉంటుంది; దీని pH సుమారు 1.2–3 — బలమైన ఆమ్లం. స్వచ్ఛమైన నీరు తటస్థం (pH 7); మిల్క్ ఆఫ్ మెగ్నీషియా, NaOH క్షార స్వభావం కలిగినవి (pH 7 కంటే ఎక్కువ)."}, {"id": 187, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Milk of magnesia is a", "q_te": "మిల్క్ ఆఫ్ మెగ్నీషియా ఒక", "opts": [{"en": "Strong acid", "te": "బలమైన ఆమ్లం"}, {"en": "Weak acid", "te": "బలహీన ఆమ్లం"}, {"en": "Strong base", "te": "బలమైన క్షారం"}, {"en": "Weak base", "te": "బలహీన క్షారం"}], "ans": 4, "exp_en": "Milk of magnesia is magnesium hydroxide, Mg(OH)<sub>2</sub>. It dissolves only slightly and ionises only partly, so it is a WEAK base (pH about 10). That mildness is exactly why it is safe to swallow as an antacid for indigestion.", "exp_te": "మిల్క్ ఆఫ్ మెగ్నీషియా అంటే మెగ్నీషియం హైడ్రాక్సైడ్, Mg(OH)<sub>2</sub>. ఇది కొద్దిగానే కరుగుతుంది, పాక్షికంగానే అయనీకరణం చెందుతుంది; కాబట్టి ఇది బలహీన క్షారం (pH సుమారు 10). ఆ మృదు స్వభావం వల్లనే అజీర్ణానికి యాంటాసిడ్‌గా మింగడం సురక్షితం."}, {"id": 188, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "The acid present in tomato", "q_te": "టమాటోలో ఉండే ఆమ్లం", "opts": [{"en": "Oxalic acid", "te": "ఆక్సాలిక్ ఆమ్లం"}, {"en": "Tartaric acid", "te": "టార్టారిక్ ఆమ్లం"}, {"en": "Citric acid", "te": "సిట్రిక్ ఆమ్లం"}, {"en": "Acetic acid", "te": "ఎసిటిక్ ఆమ్లం"}], "ans": 1, "exp_en": "Tomato contains oxalic acid. For comparison: lemon and orange — citric acid; tamarind — tartaric acid; vinegar — acetic acid; curd — lactic acid; ant sting — formic acid.", "exp_te": "టొమాటోలో ఆక్సాలిక్ ఆమ్లం ఉంటుంది. పోల్చి చూస్తే: నిమ్మ, నారింజ — సిట్రిక్ ఆమ్లం; చింతపండు — టార్టారిక్ ఆమ్లం; వెనిగర్ — ఎసిటిక్ ఆమ్లం; పెరుగు — లాక్టిక్ ఆమ్లం; చీమ కుట్టు — ఫార్మిక్ ఆమ్లం."}, {"id": 189, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Number of water molecules present in the formula of washing soda", "q_te": "బట్టల సోడా ఫార్ములాలో నీటి అణువుల సంఖ్య", "opts": [{"en": "2", "te": "2"}, {"en": "5", "te": "5"}, {"en": "8", "te": "8"}, {"en": "10", "te": "10"}], "ans": 4, "exp_en": "Washing soda is Na<sub>2</sub>CO<sub>3</sub>·10H<sub>2</sub>O — sodium carbonate decahydrate, with 10 molecules of water of crystallisation. (Gypsum has 2, blue vitriol has 5.)", "exp_te": "వాషింగ్ సోడా = Na<sub>2</sub>CO<sub>3</sub>·10H<sub>2</sub>O — సోడియం కార్బొనేట్ డెకాహైడ్రేట్; ఇందులో 10 స్ఫటిక జల అణువులు ఉంటాయి. (జిప్సంలో 2, మైలుతుత్తంలో 5.)"}, {"id": 190, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "Plaster of Paris is obtained by heating", "q_te": "ప్లాస్టర్ ఆఫ్ పారిస్‌ను దీనిని వేడిచేసి పొందుతారు", "opts": [{"en": "Sodium carbonate", "te": "సోడియం కార్బొనేట్"}, {"en": "Copper sulphate", "te": "కాపర్ సల్ఫేట్"}, {"en": "Gypsum", "te": "జిప్సం"}, {"en": "Sodium chloride", "te": "సోడియం క్లోరైడ్"}], "ans": 3, "exp_en": "Heating gypsum to about 100 °C drives off most of its water: CaSO<sub>4</sub>·2H<sub>2</sub>O → CaSO<sub>4</sub>·½H<sub>2</sub>O + 1½H<sub>2</sub>O. The product, Plaster of Paris, sets hard again when mixed with water, so it is used for plaster casts and ceilings.", "exp_te": "జిప్సంను సుమారు 100 °C వరకు వేడి చేస్తే దానిలోని ఎక్కువ భాగం నీరు పోతుంది: CaSO<sub>4</sub>·2H<sub>2</sub>O → CaSO<sub>4</sub>·½H<sub>2</sub>O + 1½H<sub>2</sub>O. ఫలితంగా వచ్చే ప్లాస్టర్ ఆఫ్ పారిస్‌ను నీటితో కలిపితే తిరిగి గట్టిపడుతుంది; అందుకే కట్టు కట్టడానికి, పైకప్పులకు వాడతారు."}, {"id": 191, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "The substance that turns red litmus into blue colour is", "q_te": "ఎర్ర లిట్మస్‌ను నీలి రంగులోకి మార్చేది", "opts": [{"en": "Acid", "te": "ఆమ్లం"}, {"en": "Base", "te": "క్షారం"}, {"en": "Neutral", "te": "తటస్థం"}, {"en": "Water", "te": "నీరు"}], "ans": 2, "exp_en": "Bases turn red litmus BLUE; acids turn blue litmus RED. A neutral substance and water leave litmus unchanged. A handy way to remember it: 'Blue for base.'", "exp_te": "క్షారాలు ఎరుపు లిట్మస్‌ను నీలంగా మారుస్తాయి; ఆమ్లాలు నీలి లిట్మస్‌ను ఎరుపుగా మారుస్తాయి. తటస్థ పదార్థాలు, నీరు లిట్మస్ రంగును మార్చవు. గుర్తుంచుకోవడానికి: 'క్షారం — నీలం'."}, {"id": 192, "sec": "ఆమ్లాలు, క్షారాలు, లవణాలు | Acids, Bases & Salts", "passage": "", "q_en": "The type of medicines used for treating indigestion", "q_te": "అజీర్ణం చికిత్సకు వాడే ఔషధాలు", "opts": [{"en": "Antibiotic", "te": "యాంటీబయోటిక్"}, {"en": "Analgesic", "te": "నొప్పి నివారిణి"}, {"en": "Antacid", "te": "యాంటాసిడ్"}, {"en": "Antiseptic", "te": "యాంటీసెప్టిక్"}], "ans": 3, "exp_en": "Indigestion and acidity are caused by excess hydrochloric acid in the stomach. An antacid is a mild base (e.g. milk of magnesia, NaHCO<sub>3</sub>) that neutralises the excess acid. Antibiotics kill bacteria, analgesics relieve pain, antiseptics kill germs on wounds.", "exp_te": "కడుపులో హైడ్రోక్లోరిక్ ఆమ్లం అధికమవడం వల్ల అజీర్ణం, ఆమ్లత్వం కలుగుతాయి. యాంటాసిడ్ అనేది మృదువైన క్షారం (ఉదా: మిల్క్ ఆఫ్ మెగ్నీషియా, NaHCO<sub>3</sub>); ఇది అధిక ఆమ్లాన్ని తటస్థీకరిస్తుంది. యాంటీబయోటిక్‌లు బాక్టీరియాను చంపుతాయి, అనాల్జెసిక్‌లు నొప్పిని తగ్గిస్తాయి, యాంటీసెప్టిక్‌లు గాయాలపై సూక్ష్మజీవులను నాశనం చేస్తాయి."}, {"id": 193, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The statement of an actual event or a physical event is", "q_te": "వాస్తవ సంఘటన లేదా భౌతిక సంఘటన యొక్క ప్రవచనం", "opts": [{"en": "Fact", "te": "వాస్తవం"}, {"en": "Generalization", "te": "సాధారణీకరణం"}, {"en": "Concept", "te": "భావన"}, {"en": "Hypothesis", "te": "పరికల్పన"}], "ans": 1, "exp_en": "A FACT is a statement about a single actual object or event that can be directly observed and verified — 'this piece of iron is attracted by this magnet'. A generalization covers many such cases; a concept is a mental category; a hypothesis is a testable guess.", "exp_te": "యథార్థం (Fact) అంటే ప్రత్యక్షంగా పరిశీలించి, ధ్రువపరచగలిగే ఒక నిర్దిష్ట వస్తువు లేదా సంఘటన గురించిన ప్రవచనం — ఉదా: 'ఈ ఇనుప ముక్కను ఈ అయస్కాంతం ఆకర్షిస్తుంది'. సాధారణీకరణం అనేక అలాంటి సందర్భాలను కలుపుతుంది; భావన ఒక మానసిక వర్గం; ప్రాకల్పన అనేది పరీక్షించదగిన ఊహ."}, {"id": 194, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "“Magnets attract iron objects” – this statement is an example of", "q_te": "“అయస్కాంతాలు ఇనుప వస్తువులను ఆకర్షిస్తాయి” – ఈ ప్రవచనం దీనికి ఉదాహరణ", "opts": [{"en": "Fact", "te": "వాస్తవం"}, {"en": "Generalization", "te": "సాధారణీకరణం"}, {"en": "Concept", "te": "భావన"}, {"en": "Hypothesis", "te": "పరికల్పన"}], "ans": 2, "exp_en": "The statement is not about one particular magnet but about ALL magnets and ALL iron objects. Such a broad statement drawn from many observed facts is a GENERALIZATION. A single observed instance would be a fact.", "exp_te": "ఈ ప్రవచనం ఏదో ఒక నిర్దిష్ట అయస్కాంతం గురించి కాదు — అన్ని అయస్కాంతాలు, అన్ని ఇనుప వస్తువుల గురించి. అనేక పరిశీలిత యథార్థాల నుండి రాబట్టిన ఇలాంటి విస్తృత ప్రవచనమే సాధారణీకరణం. ఒక్క పరిశీలిత సందర్భం అయితే అది యథార్థం అవుతుంది."}, {"id": 195, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "‘Can water be boiled at any temperature?’ – this is an example of this type of hypothesis", "q_te": "‘నీటిని ఏ ఉష్ణోగ్రత వద్దనైనా మరిగించవచ్చా?’ – ఇది ఈ రకమైన పరికల్పన", "opts": [{"en": "Null hypothesis", "te": "శూన్య పరికల్పన"}, {"en": "Declarative hypothesis", "te": "ప్రకటనాత్మక పరికల్పన"}, {"en": "Prediction hypothesis", "te": "ప్రాగుక్తి పరికల్పన"}, {"en": "Question hypothesis", "te": "ప్రశ్నా పరికల్పన"}], "ans": 4, "exp_en": "The statement is framed as a QUESTION, ending with a question mark, so it is a question hypothesis. A declarative hypothesis states a relationship ('There is a relation between…'); a null hypothesis denies any relation; a prediction hypothesis foretells an outcome.", "exp_te": "ఈ ప్రవచనం ప్రశ్న రూపంలో, ప్రశ్నార్థకంతో ముగుస్తుంది; కాబట్టి ఇది ప్రశ్న ప్రాకల్పన. ప్రకటనాత్మక ప్రాకల్పన ఒక సంబంధాన్ని ప్రకటిస్తుంది ('...మధ్య సంబంధం ఉంది'); నల్ ప్రాకల్పన ఎలాంటి సంబంధాన్ని నిరాకరిస్తుంది; ప్రాగుక్తి ప్రాకల్పన ఫలితాన్ని ముందే ఊహిస్తుంది."}, {"id": 196, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "‘There is a relation between pressure and boiling point of water’ – this is an example of this type of hypothesis", "q_te": "‘పీడనానికి, నీటి బాష్పీభవన స్థానానికి సంబంధం ఉంది’ – ఇది ఈ రకమైన పరికల్పన", "opts": [{"en": "Null hypothesis", "te": "శూన్య పరికల్పన"}, {"en": "Declarative hypothesis", "te": "ప్రకటనాత్మక పరికల్పన"}, {"en": "Prediction hypothesis", "te": "ప్రాగుక్తి పరికల్పన"}, {"en": "Question hypothesis", "te": "ప్రశ్నా పరికల్పన"}], "ans": 2, "exp_en": "It is a plain declarative sentence asserting that a relation EXISTS between two variables, so it is a declarative hypothesis. Had it said 'there is NO relation', it would be a null hypothesis.", "exp_te": "ఇది రెండు చరరాశుల మధ్య సంబంధం ఉందని ప్రకటించే సాధారణ ప్రకటనాత్మక వాక్యం; కాబట్టి ఇది ప్రకటనాత్మక ప్రాకల్పన. 'సంబంధం లేదు' అని ఉంటే అది నల్ ప్రాకల్పన అయ్యేది."}, {"id": 197, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "‘Science learning is useful for entering into different professions like doctors, engineers and teachers’ indicates this value", "q_te": "‘సైన్స్ అభ్యసనం డాక్టర్లు, ఇంజనీర్లు, ఉపాధ్యాయులు వంటి వృత్తుల్లో ప్రవేశానికి ఉపయోగపడుతుంది’ – ఇది సూచించే విలువ", "opts": [{"en": "Intellectual value", "te": "బౌద్ధిక విలువ"}, {"en": "Cultural value", "te": "సాంస్కృతిక విలువ"}, {"en": "Moral value", "te": "నైతిక విలువ"}, {"en": "Vocational value", "te": "వృత్తిపరమైన విలువ"}], "ans": 4, "exp_en": "The statement links science learning directly to entering PROFESSIONS or occupations, which is the vocational value of teaching science. Intellectual value refers to developing thinking and reasoning; moral value to honesty and truthfulness.", "exp_te": "ఈ ప్రవచనం విజ్ఞానశాస్త్ర అభ్యసనాన్ని నేరుగా వృత్తులలో ప్రవేశించడంతో అనుసంధానిస్తుంది; ఇదే విజ్ఞానశాస్త్ర బోధన యొక్క వృత్తిపరమైన విలువ. బౌద్ధిక విలువ ఆలోచన, తార్కికత అభివృద్ధికి సంబంధించినది; నైతిక విలువ నిజాయితీ, సత్యనిష్ఠకు సంబంధించినది."}, {"id": 198, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "‘Learning science develops discipline in taking readings and while working in the laboratory’ indicates this value", "q_te": "‘ప్రయోగశాలలో రీడింగులు తీసుకోవడంలో, పనిచేయడంలో సైన్స్ అభ్యసనం క్రమశిక్షణ పెంచుతుంది’ – ఇది సూచించే విలువ", "opts": [{"en": "Moral value", "te": "నైతిక విలువ"}, {"en": "Aesthetic value", "te": "సౌందర్యాత్మక విలువ"}, {"en": "Disciplinary value", "te": "క్రమశిక్షణా విలువ"}, {"en": "Utilitarian value", "te": "ప్రయోజనాత్మక విలువ"}], "ans": 3, "exp_en": "Careful, orderly, accurate work in the laboratory — following a set procedure, recording readings honestly — trains the mind in orderliness. This is the disciplinary value of science teaching.", "exp_te": "ప్రయోగశాలలో నిర్దిష్ట పద్ధతిని అనుసరించడం, రీడింగులను నిజాయితీగా నమోదు చేయడం వంటి జాగ్రత్తైన, క్రమబద్ధమైన, ఖచ్చితమైన పని మనసుకు క్రమబద్ధతను అలవరుస్తుంది. ఇదే విజ్ఞానశాస్త్ర బోధన యొక్క క్రమశిక్షణ విలువ."}, {"id": 199, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The first step in the ‘scientific method’ is", "q_te": "‘శాస్త్రీయ పద్ధతి’ లో మొదటి సోపానం", "opts": [{"en": "Identification of problem", "te": "సమస్యను గుర్తించడం"}, {"en": "Analysing problem", "te": "సమస్యను విశ్లేషించడం"}, {"en": "Testing hypothesis", "te": "పరికల్పన పరీక్ష"}, {"en": "Generalization of results", "te": "ఫలితాల సాధారణీకరణ"}], "ans": 1, "exp_en": "The scientific method runs: identify the problem → analyse/define it → form a hypothesis → test it by experiment → draw conclusions → generalize. Nothing can begin until the problem itself is recognised, so identification comes first.", "exp_te": "శాస్త్రీయ పద్ధతి క్రమం: సమస్యను గుర్తించడం → విశ్లేషించడం/నిర్వచించడం → ప్రాకల్పన ఏర్పరచడం → ప్రయోగం ద్వారా పరీక్షించడం → నిర్ణయాలు రాబట్టడం → సాధారణీకరించడం. సమస్యను గుర్తించకుండా ఏదీ ప్రారంభం కాదు, కాబట్టి మొదటి సోపానం గుర్తించడమే."}, {"id": 200, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The cognitive domain was explained by", "q_te": "జ్ఞానాత్మక రంగాన్ని వివరించినవారు", "opts": [{"en": "B.S. Bloom", "te": "బి.ఎస్. బ్లూమ్"}, {"en": "David R. Krathwohl", "te": "డేవిడ్ ఆర్. క్రాత్‌వోల్"}, {"en": "R. H. Dave", "te": "ఆర్.హెచ్. డేవ్"}, {"en": "Jeevan", "te": "Jeevan"}], "ans": 1, "exp_en": "B. S. Bloom gave the classification of educational objectives in 1956 and explained the COGNITIVE domain (knowledge, understanding, application, analysis, synthesis, evaluation). Krathwohl worked out the affective domain, and Simpson/Dave the psychomotor domain.", "exp_te": "బి.ఎస్. బ్లూమ్ 1956 లో విద్యా లక్ష్యాల వర్గీకరణను ఇచ్చి, జ్ఞానాత్మక రంగాన్ని (జ్ఞానం, అవగాహన, అనువర్తనం, విశ్లేషణ, సంశ్లేషణ, మూల్యాంకనం) వివరించారు. భావావేశ రంగాన్ని క్రాత్‌వోల్, మానసిక చాలక రంగాన్ని సింప్సన్/డేవ్ వివరించారు."}, {"id": 201, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The first level in the cognitive domain of Bloom’s classification of educational objectives", "q_te": "బ్లూమ్ వర్గీకరణలో జ్ఞానాత్మక రంగం మొదటి స్థాయి", "opts": [{"en": "Understanding", "te": "అవగాహన"}, {"en": "Application", "te": "వినియోగం"}, {"en": "Knowledge", "te": "జ్ఞానం"}, {"en": "Evaluation", "te": "మూల్యాంకనం"}], "ans": 3, "exp_en": "Bloom's cognitive domain has six levels in order: Knowledge → Understanding → Application → Analysis → Synthesis → Evaluation. Knowledge (simple recall) is the lowest and first; evaluation is the highest and last.", "exp_te": "బ్లూమ్ జ్ఞానాత్మక రంగంలో ఆరు స్థాయిలు ఈ క్రమంలో ఉంటాయి: జ్ఞానం → అవగాహన → అనువర్తనం → విశ్లేషణ → సంశ్లేషణ → మూల్యాంకనం. జ్ఞానం (సాధారణ జ్ఞప్తి) అత్యల్ప స్థాయి, మొదటిది; మూల్యాంకనం అత్యున్నత స్థాయి, చివరిది."}, {"id": 202, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The first level in the ‘affective domain’ of Bloom’s classification of educational objectives", "q_te": "బ్లూమ్ వర్గీకరణలో భావావేశ రంగం మొదటి స్థాయి", "opts": [{"en": "Responding", "te": "ప్రతిస్పందించడం"}, {"en": "Valuing", "te": "విలువకట్టడం"}, {"en": "Organisation", "te": "వ్యవస్థాపనం"}, {"en": "Receiving", "te": "గ్రహించడం"}], "ans": 4, "exp_en": "Krathwohl's affective domain runs: Receiving (attending) → Responding → Valuing → Organisation → Characterisation. A learner must first pay attention (receive) before he can respond, so Receiving is the first step.", "exp_te": "క్రాత్‌వోల్ భావావేశ రంగం క్రమం: గ్రహించడం (శ్రద్ధ వహించడం) → ప్రతిస్పందన → విలువ కట్టడం → వ్యవస్థాపనం → లక్షణీకరణం. విద్యార్థి ప్రతిస్పందించే ముందు శ్రద్ధ వహించాలి (గ్రహించాలి), కాబట్టి మొదటి సోపానం గ్రహించడం."}, {"id": 203, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The first level in the ‘psychomotor domain’ of educational objectives", "q_te": "మనోచాలక రంగం మొదటి స్థాయి", "opts": [{"en": "Imitation", "te": "అనుకరణ"}, {"en": "Manipulation", "te": "హస్తలాఘవం"}, {"en": "Precision", "te": "సునిశితత్వం"}, {"en": "Articulation", "te": "సమన్వయం"}], "ans": 1, "exp_en": "Simpson/Dave's psychomotor domain runs: Imitation → Manipulation → Precision → Articulation → Naturalisation. A skill is first learnt by watching and copying (imitation), so that is the first step.", "exp_te": "సింప్సన్/డేవ్ మానసిక చాలక రంగం క్రమం: అనుకరణ → హస్తలాఘవం → సునిశితత్వం → సమన్వయం → సహజీకరణం. ఏ నైపుణ్యాన్నైనా మొదట చూసి, అనుకరించడం ద్వారానే నేర్చుకుంటారు; కాబట్టి మొదటి సోపానం అనుకరణ."}, {"id": 204, "sec": "సైన్స్ స్వభావం, విద్యా లక్ష్యాలు | Nature of Science & Objectives", "passage": "", "q_en": "The specification “Recall” belongs to this objective", "q_te": "“జ్ఞప్తికి తెచ్చుకోవడం” అనే స్పష్టీకరణ చెందే లక్ష్యం", "opts": [{"en": "Knowledge", "te": "జ్ఞానం"}, {"en": "Understanding", "te": "అవగాహన"}, {"en": "Application", "te": "వినియోగం"}, {"en": "Skill", "te": "నైపుణ్యం"}], "ans": 1, "exp_en": "The specifications of the KNOWLEDGE objective are recall and recognise. Understanding shows itself as explaining, illustrating and comparing; application as using knowledge in a new situation.", "exp_te": "జ్ఞానం లక్ష్యానికి సంబంధించిన స్పష్టీకరణలు — జ్ఞప్తికి తెచ్చుకోవడం (recall), గుర్తించడం (recognise). అవగాహన లక్ష్యం వివరించడం, ఉదాహరించడం, పోల్చడం రూపంలో వ్యక్తమవుతుంది; అనువర్తనం కొత్త సందర్భంలో జ్ఞానాన్ని వినియోగించడం."}, {"id": 205, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Teaching is an interaction process’ was defined by", "q_te": "‘బోధన ఒక పరస్పర చర్యా ప్రక్రియ’ అని నిర్వచించినవారు", "opts": [{"en": "Edmund Amidon", "te": "ఎడ్మండ్ అమిడాన్"}, {"en": "N. A. Flanders", "te": "ఎన్.ఎ. ఫ్లాండర్స్"}, {"en": "B. O. Smith", "te": "బి.ఓ. స్మిత్"}, {"en": "H. C. Morrison", "te": "హెచ్.సి. మారిసన్"}], "ans": 2, "exp_en": "Flanders developed Interaction Analysis, which studies teaching as a continuous give-and-take between teacher talk and pupil talk — hence teaching as an interaction process. NOTE: many textbooks credit this exact wording to Amidon & Hunter (1966); the printed answer key here gives Flanders, so write Flanders in the exam.", "exp_te": "ఫ్లాండర్స్ పరస్పర చర్యా విశ్లేషణ (Interaction Analysis) ను అభివృద్ధి చేశారు; ఇది ఉపాధ్యాయుని మాట, విద్యార్థి మాట మధ్య నిరంతర ఇచ్చిపుచ్చుకోవడంగా బోధనను అధ్యయనం చేస్తుంది — కాబట్టి బోధన ఒక పరస్పర చర్యా ప్రక్రియ. గమనిక: ఈ నిర్వచనాన్ని అనేక పాఠ్యపుస్తకాలు అమిడాన్ & హంటర్ (1966) కు ఆపాదిస్తాయి; ఇక్కడి ముద్రిత కీ ఫ్లాండర్స్ అని ఇచ్చింది, కాబట్టి పరీక్షలో ఫ్లాండర్స్ రాయండి."}, {"id": 206, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Memory level of teaching’ was designed by", "q_te": "‘జ్ఞాపకశక్తి స్థాయి బోధన’ ను రూపొందించినవారు", "opts": [{"en": "Edmund Amidon", "te": "ఎడ్మండ్ అమిడాన్"}, {"en": "N. A. Flanders", "te": "ఎన్.ఎ. ఫ్లాండర్స్"}, {"en": "J. F. Herbart", "te": "జె.ఎఫ్. హెర్బార్ట్"}, {"en": "H. C. Morrison", "te": "హెచ్.సి. మారిసన్"}], "ans": 3, "exp_en": "The three levels of teaching are: memory level (Herbart), understanding level (Morrison) and reflective level (Hunt). At the memory level teaching is only cramming of facts, with the teacher fully in charge.", "exp_te": "బోధనలో మూడు స్థాయులు: స్మృతి స్థాయి (హెర్బార్ట్), అవగాహన స్థాయి (మోరిసన్), విమర్శనాత్మక/చింతనాత్మక స్థాయి (హంట్). స్మృతి స్థాయిలో బోధన కేవలం విషయాలను కంఠస్థం చేయించడమే; ఉపాధ్యాయుడే పూర్తి బాధ్యత వహిస్తాడు."}, {"id": 207, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "Student-centred teaching method among the following", "q_te": "క్రింది వాటిలో విద్యార్థి కేంద్రీకృత బోధనా పద్ధతి", "opts": [{"en": "Heuristic method", "te": "అన్వేషణ పద్ధతి"}, {"en": "Lecture method", "te": "ఉపన్యాస పద్ధతి"}, {"en": "Lecture demonstration method", "te": "ఉపన్యాస–ప్రదర్శన పద్ధతి"}, {"en": "Historical method", "te": "చారిత్రక పద్ధతి"}], "ans": 1, "exp_en": "In the heuristic method the pupil himself acts like a little discoverer — he investigates, experiments and arrives at the result, with the teacher only guiding. So it is fully child-centred. The lecture method is the most teacher-centred.", "exp_te": "అన్వేషణా పద్ధతిలో విద్యార్థి ఒక చిన్న పరిశోధకుని వలె స్వయంగా పరిశోధిస్తూ, ప్రయోగాలు చేస్తూ ఫలితాన్ని రాబడతాడు; ఉపాధ్యాయుడు మార్గదర్శిగా మాత్రమే ఉంటాడు. కాబట్టి ఇది పూర్తిగా విద్యార్థి కేంద్రకం. ఉపన్యాస పద్ధతి అత్యధికంగా ఉపాధ్యాయ కేంద్రకం."}, {"id": 208, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "Teacher-centred teaching method among the following", "q_te": "క్రింది వాటిలో ఉపాధ్యాయ కేంద్రీకృత బోధనా పద్ధతి", "opts": [{"en": "Lecture method", "te": "ఉపన్యాస పద్ధతి"}, {"en": "Heuristic method", "te": "అన్వేషణ పద్ధతి"}, {"en": "Project method", "te": "ప్రాజెక్టు పద్ధతి"}, {"en": "Laboratory method", "te": "ప్రయోగశాల పద్ధతి"}], "ans": 1, "exp_en": "In the lecture method the teacher does all the talking and the pupils only listen — there is no pupil activity, so it is the most teacher-centred method. The other three all put the pupil to work.", "exp_te": "ఉపన్యాస పద్ధతిలో ఉపాధ్యాయుడే మాట్లాడతాడు, విద్యార్థులు వినడం మాత్రమే చేస్తారు — విద్యార్థి కృత్యం ఉండదు, కాబట్టి ఇది అత్యధిక ఉపాధ్యాయ కేంద్రక పద్ధతి. మిగిలిన మూడు పద్ధతులు విద్యార్థిని చురుకుగా పనిచేయిస్తాయి."}, {"id": 209, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The first step in project method is", "q_te": "ప్రాజెక్టు పద్ధతిలో మొదటి సోపానం", "opts": [{"en": "Planning", "te": "ప్రణాళిక"}, {"en": "Execution", "te": "అమలు"}, {"en": "Evaluation", "te": "మూల్యాంకనం"}, {"en": "Providing a situation", "te": "సందర్భం కల్పించడం"}], "ans": 4, "exp_en": "Kilpatrick's project method runs: providing a situation → purposing (choosing the project) → planning → executing → evaluating → recording. The teacher must first create a situation that raises a felt need in the pupils, so that comes first.", "exp_te": "కిల్‌పాట్రిక్ ప్రాజెక్టు పద్ధతి క్రమం: పరిస్థితిని కల్పించడం → ప్రాజెక్టును ఎంచుకోవడం → ప్రణాళిక → నిర్వహణ → మూల్యాంకనం → నివేదిక రాయడం. విద్యార్థులలో ఆవశ్యకతను కలిగించే పరిస్థితిని ఉపాధ్యాయుడు ముందుగా కల్పించాలి, కాబట్టి అదే మొదటి సోపానం."}, {"id": 210, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The last step in project method is", "q_te": "ప్రాజెక్టు పద్ధతిలో చివరి సోపానం", "opts": [{"en": "Preparing a report", "te": "నివేదిక తయారీ"}, {"en": "Evaluation", "te": "మూల్యాంకనం"}, {"en": "Planning", "te": "ప్రణాళిక"}, {"en": "Providing a situation", "te": "సందర్భం కల్పించడం"}], "ans": 1, "exp_en": "The final step is recording — the pupils write up a full report of what they did, how they did it and what they found, in their project diary. It comes even after evaluation, and gives permanent record and practice in written expression.", "exp_te": "చివరి సోపానం నివేదిక రాయడం (Recording) — విద్యార్థులు తాము ఏమి చేశారు, ఎలా చేశారు, ఏమి తెలుసుకున్నారు అనే పూర్తి వివరాలను ప్రాజెక్టు డైరీలో రాస్తారు. ఇది మూల్యాంకనం తర్వాతే వస్తుంది; శాశ్వత రికార్డును, రాత అభివ్యక్తి అభ్యాసాన్ని ఇస్తుంది."}, {"id": 211, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "In this method students learn the lesson by doing experiments on their own", "q_te": "విద్యార్థులు స్వయంగా ప్రయోగాలు చేసి పాఠం నేర్చుకునే పద్ధతి", "opts": [{"en": "Lecture demonstration method", "te": "ఉపన్యాస–ప్రదర్శన పద్ధతి"}, {"en": "Lecture method", "te": "ఉపన్యాస పద్ధతి"}, {"en": "Historical method", "te": "చారిత్రక పద్ధతి"}, {"en": "Laboratory method", "te": "ప్రయోగశాల పద్ధతి"}], "ans": 4, "exp_en": "In the laboratory method each pupil performs the experiment himself, following the instruction card, and learns by 'learning by doing'. In the lecture-demonstration method, by contrast, only the TEACHER performs it while pupils watch.", "exp_te": "ప్రయోగశాల పద్ధతిలో ప్రతి విద్యార్థి సూచనా పత్రాన్ని అనుసరించి స్వయంగా ప్రయోగం చేస్తూ 'చేయడం ద్వారా అభ్యసనం' పొందుతాడు. దీనికి భిన్నంగా ఉపన్యాస-ప్రదర్శనా పద్ధతిలో ఉపాధ్యాయుడే ప్రయోగం చేస్తాడు, విద్యార్థులు చూస్తారు."}, {"id": 212, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The first step in ‘problem solving method’ is", "q_te": "‘సమస్యా పరిష్కార పద్ధతి’ లో మొదటి సోపానం", "opts": [{"en": "Conclusion", "te": "నిర్ధారణ"}, {"en": "Analysing the problem", "te": "సమస్యను విశ్లేషించడం"}, {"en": "Defining the problem", "te": "సమస్యను నిర్వచించడం"}, {"en": "Identifying the problem", "te": "సమస్యను గుర్తించడం"}], "ans": 4, "exp_en": "The order is: identify the problem → define it → collect data → form and test a hypothesis → draw conclusions. Until the problem is recognised nothing else can start, so identification is first.", "exp_te": "క్రమం: సమస్యను గుర్తించడం → నిర్వచించడం → సమాచార సేకరణ → ప్రాకల్పన ఏర్పరచి పరీక్షించడం → నిర్ణయాలు రాబట్టడం. సమస్యను గుర్తించకుండా మిగిలినవి ప్రారంభం కావు, కాబట్టి మొదటిది గుర్తించడమే."}, {"id": 213, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Heuristic’ is derived from the Greek word ‘Heurisco’. The meaning of heurisco is", "q_te": "‘Heuristic’ గ్రీకు పదం ‘Heurisco’ నుండి వచ్చింది. Heurisco అంటే", "opts": [{"en": "Experiment", "te": "ప్రయోగం"}, {"en": "Investigation / I find out", "te": "అన్వేషణ / కనుగొనడం"}, {"en": "Doing work", "te": "పని చేయడం"}, {"en": "Hypothesis", "te": "పరికల్పన"}], "ans": 2, "exp_en": "The Greek 'heurisko' means 'I find out / I discover', that is, to investigate and discover for oneself. That is exactly the spirit of the heuristic method, in which the pupil discovers knowledge instead of being told it.", "exp_te": "గ్రీకు పదం 'హ్యూరిస్కో' అంటే 'నేను కనుగొంటాను / వెలికితీస్తాను', అనగా స్వయంగా పరిశోధించి కనుగొనడం. అన్వేషణా పద్ధతి స్వభావం ఇదే — విద్యార్థికి చెప్పకుండా, అతడే జ్ఞానాన్ని కనుగొనేలా చేయడం."}, {"id": 214, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Communication’ is derived from the following Latin word", "q_te": "‘Communication’ ఈ లాటిన్ పదం నుండి వచ్చింది", "opts": [{"en": "Comments", "te": "Comments"}, {"en": "Communis", "te": "Communis"}, {"en": "Commons", "te": "Commons"}, {"en": "Connections", "te": "Connections"}], "ans": 2, "exp_en": "'Communication' comes from the Latin 'communis', meaning 'common' — to communicate is to make something common or shared between sender and receiver.", "exp_te": "'కమ్యూనికేషన్' అనే పదం లాటిన్ 'కమ్యూనిస్' (communis) నుండి వచ్చింది; దాని అర్థం 'ఉమ్మడి'. సమాచార ప్రసారం అంటే పంపేవారికి, స్వీకరించేవారికి మధ్య ఒక విషయాన్ని ఉమ్మడిగా (పంచుకున్నదిగా) చేయడం."}, {"id": 215, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "In this teaching method, the teacher explains the concept by showing the experiment to the students", "q_te": "ఉపాధ్యాయుడు ప్రయోగం చేసి చూపిస్తూ భావనను వివరించే బోధనా పద్ధతి", "opts": [{"en": "Lecture method", "te": "ఉపన్యాస పద్ధతి"}, {"en": "Lecture demonstration method", "te": "ఉపన్యాస–ప్రదర్శన పద్ధతి"}, {"en": "Heuristic method", "te": "అన్వేషణ పద్ధతి"}, {"en": "Problem solving method", "te": "సమస్యా పరిష్కార పద్ధతి"}], "ans": 2, "exp_en": "The lecture-demonstration method combines telling with showing: the teacher performs the experiment before the class and explains alongside. It suits costly or risky experiments and large classes, but the pupils remain onlookers.", "exp_te": "ఉపన్యాస-ప్రదర్శనా పద్ధతి చెప్పడం + చూపడం రెండింటినీ కలుపుతుంది: ఉపాధ్యాయుడు తరగతి ముందు ప్రయోగం చేసి, అదే సమయంలో వివరిస్తాడు. ఖరీదైన లేదా ప్రమాదకర ప్రయోగాలకు, పెద్ద తరగతులకు ఇది అనుకూలం; కానీ విద్యార్థులు ప్రేక్షకులుగానే ఉండిపోతారు."}, {"id": 216, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Heuristic method’ was first introduced by", "q_te": "‘అన్వేషణ పద్ధతి’ ని మొదట ప్రవేశపెట్టినవారు", "opts": [{"en": "H. E. Armstrong", "te": "హెచ్.ఇ. ఆర్మ్‌స్ట్రాంగ్"}, {"en": "F. W. Westaway", "te": "ఎఫ్.డబ్ల్యు. వెస్ట్‌వే"}, {"en": "Kilpatrick", "te": "కిల్‌పాట్రిక్"}, {"en": "H. C. Morrison", "te": "హెచ్.సి. మారిసన్"}], "ans": 1, "exp_en": "H. E. Armstrong, an English chemistry professor, introduced the heuristic method. Kilpatrick gave the project method; Westaway wrote on science teaching; Morrison gave the understanding level of teaching.", "exp_te": "ఇంగ్లీషు రసాయన శాస్త్ర ఆచార్యులు హెచ్.ఈ. ఆర్మ్‌స్ట్రాంగ్ అన్వేషణా పద్ధతిని ప్రవేశపెట్టారు. కిల్‌పాట్రిక్ ప్రాజెక్టు పద్ధతిని ఇచ్చారు; వెస్ట్‌వే విజ్ఞానశాస్త్ర బోధనపై రచనలు చేశారు; మోరిసన్ అవగాహన స్థాయి బోధనను ఇచ్చారు."}, {"id": 217, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "Plan prepared to teach the lessons in the curriculum for the whole year", "q_te": "పాఠ్యప్రణాళికలోని పాఠాలను సంవత్సరం పొడవునా బోధించడానికి తయారుచేసే పథకం", "opts": [{"en": "Unit plan", "te": "యూనిట్ పథకం"}, {"en": "Period plan", "te": "పీరియడ్ పథకం"}, {"en": "Year plan", "te": "వార్షిక పథకం"}, {"en": "Monthly plan", "te": "మాసిక పథకం"}], "ans": 3, "exp_en": "The year plan spreads the whole year's syllabus over the available working months and days, allotting time to each unit. The unit plan covers one unit and the period (lesson) plan one class period.", "exp_te": "వార్షిక పథకం సంవత్సరం మొత్తం సిలబస్‌ను అందుబాటులో ఉన్న పని నెలలు, రోజులపై పంచి, ప్రతి యూనిట్‌కు కాలాన్ని కేటాయిస్తుంది. యూనిట్ పథకం ఒక యూనిట్‌కు, పీరియడ్ (పాఠ్య) పథకం ఒక తరగతి పీరియడ్‌కు సంబంధించినవి."}, {"id": 218, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘A unit is a large block of related subject matter as can be overviewed by the learner’ – said by", "q_te": "‘యూనిట్ అనేది అభ్యాసకుడు సమగ్రంగా చూడగలిగే సంబంధిత విషయాల పెద్ద భాగం’ – అన్నవారు", "opts": [{"en": "Bossing", "te": "బాసింగ్"}, {"en": "Preston", "te": "ప్రెస్టన్"}, {"en": "Bagley", "te": "బాగ్లే"}, {"en": "Morrison", "te": "మారిసన్"}], "ans": 2, "exp_en": "This definition of a unit is Preston's. Bossing defined the unit plan; Morrison gave the units of learning at the understanding level.", "exp_te": "యూనిట్‌కు ఈ నిర్వచనాన్ని ఇచ్చినవారు ప్రెస్టన్. బాసింగ్ యూనిట్ పథకాన్ని నిర్వచించారు; మోరిసన్ అవగాహన స్థాయిలో అభ్యసన యూనిట్లను ఇచ్చారు."}, {"id": 219, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The educationist who prepared the steps in ‘lesson planning’", "q_te": "‘పాఠ్యపథకం’ సోపానాలను రూపొందించిన విద్యావేత్త", "opts": [{"en": "Herbart", "te": "హెర్బార్ట్"}, {"en": "Bossing", "te": "బాసింగ్"}, {"en": "Morrison", "te": "మారిసన్"}, {"en": "Bagley", "te": "బాగ్లే"}], "ans": 1, "exp_en": "The German educationist J. F. Herbart gave the five formal steps of lesson planning — preparation, presentation, association/comparison, generalization and application — which is why they are called the Herbartian steps.", "exp_te": "జర్మన్ విద్యావేత్త జె.ఎఫ్. హెర్బార్ట్ పాఠ్య పథక రచనలోని ఐదు ఔపచారిక సోపానాలను — సన్నాహం, ప్రదర్శన (వివరణ), సంసర్గం/పోలిక, సాధారణీకరణం, అనువర్తనం — ఇచ్చారు. అందుకే వాటిని హెర్బార్టియన్ సోపానాలు అంటారు."}, {"id": 220, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The first step in the execution of ‘steps in lesson planning’", "q_te": "‘పాఠ్యపథక సోపానాల’ అమలులో మొదటి సోపానం", "opts": [{"en": "Preparation", "te": "సన్నాహం"}, {"en": "Presentation", "te": "సమర్పణ"}, {"en": "Association", "te": "సంసర్గం"}, {"en": "Generalization", "te": "సాధారణీకరణం"}], "ans": 1, "exp_en": "The Herbartian order is: Preparation → Presentation → Association/Comparison → Generalization → Application. Preparation (also called introduction) comes first: the teacher tests previous knowledge and creates interest before the new matter is taught.", "exp_te": "హెర్బార్టియన్ క్రమం: సన్నాహం → ప్రదర్శన → సంసర్గం/పోలిక → సాధారణీకరణం → అనువర్తనం. మొదటిది సన్నాహం (ఉపోద్ఘాతం): కొత్త విషయాన్ని బోధించే ముందు ఉపాధ్యాయుడు పూర్వ జ్ఞానాన్ని పరీక్షించి, ఆసక్తిని కలిగిస్తాడు."}, {"id": 221, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Curriculum should be prepared based on the physical and mental levels of students.’ The principle involved in this sentence", "q_te": "‘విద్యార్థుల శారీరక, మానసిక స్థాయిలను బట్టి పాఠ్యప్రణాళిక తయారుచేయాలి.’ ఇందులోని సూత్రం", "opts": [{"en": "Principle of balance", "te": "సమతుల్య సూత్రం"}, {"en": "Principle of articulation", "te": "సమన్వయ సూత్రం"}, {"en": "Principle of utility", "te": "ప్రయోజన సూత్రం"}, {"en": "Principle of maturity", "te": "పరిపక్వతా సూత్రం"}], "ans": 4, "exp_en": "Matching the content to the learner's physical and mental development — his level of maturity — is the principle of maturity. Balance means giving due weight to all areas; utility means the content should be useful in life.", "exp_te": "విషయాన్ని విద్యార్థి శారీరక, మానసిక వికాస స్థాయికి — అనగా పరిపక్వతా స్థాయికి — అనుగుణంగా ఉంచడమే పరిపక్వతా సూత్రం. సమతౌల్యతా సూత్రం అన్ని రంగాలకు తగిన ప్రాధాన్యత ఇవ్వడం; ఉపయోగితా సూత్రం విషయం జీవితంలో ఉపయోగపడాలి అనడం."}, {"id": 222, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "‘Curriculum must include learning by doing activities.’ The principle involved in this sentence", "q_te": "‘పాఠ్యప్రణాళికలో చేయడం ద్వారా నేర్చుకునే కృత్యాలు ఉండాలి.’ ఇందులోని సూత్రం", "opts": [{"en": "Principle of activity centredness", "te": "కృత్యకేంద్రీకృత సూత్రం"}, {"en": "Principle of articulation", "te": "సమన్వయ సూత్రం"}, {"en": "Principle of creativity", "te": "సృజనాత్మక సూత్రం"}, {"en": "Principle of conservation", "te": "పరిరక్షణ సూత్రం"}], "ans": 1, "exp_en": "'Learning by doing' puts the pupil's own activity at the centre of the curriculum, which is the principle of activity centredness. Knowledge gained through one's own doing is clearer and lasts longer.", "exp_te": "'చేయడం ద్వారా అభ్యసనం' అనేది విద్యార్థి స్వీయ కృత్యాన్ని పాఠ్య ప్రణాళిక కేంద్రంగా ఉంచుతుంది; ఇదే కృత్యకేంద్రీకృత సూత్రం. స్వయంగా చేయడం ద్వారా పొందిన జ్ఞానం స్పష్టంగా, శాశ్వతంగా నిలుస్తుంది."}, {"id": 223, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "In programmed learning, the principle by which a student learns at his own pace based on individual differences", "q_te": "కార్యక్రమయుత అభ్యసనంలో వైయక్తిక భేదాల ఆధారంగా విద్యార్థి తన వేగంతో నేర్చుకునే సూత్రం", "opts": [{"en": "Principle of small steps", "te": "చిన్న సోపానాల సూత్రం"}, {"en": "Principle of self pacing", "te": "స్వీయ వేగ సూత్రం"}, {"en": "Principle of immediate reinforcement", "te": "తక్షణ పునర్బలన సూత్రం"}, {"en": "Principle of student testing", "te": "విద్యార్థి పరీక్ష సూత్రం"}], "ans": 2, "exp_en": "Self pacing means each learner moves through the programme at HIS OWN speed — a quick learner goes ahead, a slow learner takes more time, and nobody is left behind. This is how programmed learning respects individual differences.", "exp_te": "స్వీయ గమన సూత్రం అంటే ప్రతి అభ్యాసకుడు కార్యక్రమాన్ని తన స్వంత వేగంతో పూర్తి చేయడం — వేగంగా నేర్చుకునేవాడు ముందుకు వెళతాడు, నెమ్మదిగా నేర్చుకునేవాడు ఎక్కువ సమయం తీసుకుంటాడు, ఎవరూ వెనుకబడరు. ఈ విధంగా కార్యక్రమయుత అభ్యసనం వైయక్తిక భేదాలను గౌరవిస్తుంది."}, {"id": 224, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The first step in micro teaching is", "q_te": "సూక్ష్మబోధనలో మొదటి సోపానం", "opts": [{"en": "Skill demonstration", "te": "నైపుణ్య ప్రదర్శన"}, {"en": "Micro teaching", "te": "సూక్ష్మబోధన"}, {"en": "Defining the skill", "te": "నైపుణ్యాన్ని నిర్వచించడం"}, {"en": "Transfer of skill", "te": "నైపుణ్య బదలాయింపు"}], "ans": 3, "exp_en": "Micro teaching runs: defining the skill → demonstrating it → planning the lesson → teach–feedback–replan–reteach–refeedback cycle → transfer of the skill to the real classroom. The trainee must first know exactly WHAT skill he is to practise, so defining comes first.", "exp_te": "సూక్ష్మ బోధన క్రమం: నైపుణ్యాన్ని నిర్వచించడం → ప్రదర్శించడం → పాఠ్య పథక రచన → బోధన–పునఃపుష్టి–పునఃప్రణాళిక–పునఃబోధన–పునఃపుష్టి చక్రం → నైపుణ్య బదిలీ. శిక్షణార్థి తాను ఏ నైపుణ్యాన్ని అభ్యసించాలో ముందుగా స్పష్టంగా తెలుసుకోవాలి, కాబట్టి నిర్వచించడమే మొదటి సోపానం."}, {"id": 225, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The final step in micro teaching is", "q_te": "సూక్ష్మబోధనలో చివరి సోపానం", "opts": [{"en": "Defining the skill", "te": "నైపుణ్యాన్ని నిర్వచించడం"}, {"en": "Skill demonstration", "te": "నైపుణ్య ప్రదర్శన"}, {"en": "Micro teaching", "te": "సూక్ష్మబోధన"}, {"en": "Transfer of skill", "te": "నైపుణ్య బదలాయింపు"}], "ans": 4, "exp_en": "The last step is transfer of the skill: the skill practised separately in short micro lessons is integrated and carried over into real full-length teaching in an actual classroom. Without this transfer, the whole training would serve no purpose.", "exp_te": "చివరి సోపానం నైపుణ్య బదిలీ: చిన్న సూక్ష్మ పాఠాలలో విడిగా అభ్యసించిన నైపుణ్యాన్ని సమీకృతం చేసి, వాస్తవ తరగతి గదిలో పూర్తి నిడివి బోధనలోనికి బదిలీ చేస్తారు. ఈ బదిలీ లేకపోతే మొత్తం శిక్షణ వ్యర్థమే."}, {"id": 226, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "The word ‘Curriculum’ is derived from the Latin word ‘Currere’, which means", "q_te": "‘Curriculum’ లాటిన్ పదం ‘Currere’ నుండి వచ్చింది. దాని అర్థం", "opts": [{"en": "To run", "te": "పరుగెత్తడం"}, {"en": "To learn", "te": "నేర్చుకోవడం"}, {"en": "To understand", "te": "అర్థం చేసుకోవడం"}, {"en": "To write", "te": "రాయడం"}], "ans": 1, "exp_en": "Latin 'currere' means 'to run', and curriculum meant the race course to be run. In education it is the whole course of learning experiences the pupil must run through to reach the goal.", "exp_te": "లాటిన్ 'కర్రెరె' అంటే 'పరుగెత్తడం'; కర్రికులం అంటే పరుగెత్తాల్సిన మార్గం (పందెపు మార్గం). విద్యలో ఇది లక్ష్యాన్ని చేరడానికి విద్యార్థి దాటవలసిన మొత్తం అభ్యసనానుభవాల మార్గం."}, {"id": 227, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "This occupies a major role in the teaching-learning process apart from teacher and student", "q_te": "ఉపాధ్యాయుడు, విద్యార్థి తర్వాత బోధనాభ్యసన ప్రక్రియలో ప్రధాన పాత్ర పోషించేది", "opts": [{"en": "Black board", "te": "నల్లబల్ల"}, {"en": "Laboratory", "te": "ప్రయోగశాల"}, {"en": "Text book", "te": "పాఠ్యపుస్తకం"}, {"en": "Atmosphere", "te": "వాతావరణం"}], "ans": 3, "exp_en": "The text book is the third essential element after the teacher and the pupil. It fixes the content and its sequence, guides both teacher and pupil, and is the pupil's main reference for revision at home.", "exp_te": "ఉపాధ్యాయుడు, విద్యార్థి తర్వాత మూడవ ఆవశ్యక అంశం పాఠ్య పుస్తకం. ఇది విషయాన్ని, దాని క్రమాన్ని నిర్ణయిస్తుంది; ఉపాధ్యాయునికి, విద్యార్థికి మార్గదర్శిగా ఉంటుంది; ఇంటిలో పునశ్చరణకు విద్యార్థికి ప్రధాన ఆధారం."}, {"id": 228, "sec": "బోధనా పద్ధతులు, ప్రణాళికలు | Teaching Methods & Planning", "passage": "", "q_en": "This is not a mechanical (physical) feature of a text book", "q_te": "పాఠ్యపుస్తకం యొక్క బాహ్య (యాంత్రిక) లక్షణం కానిది", "opts": [{"en": "Book binding should be neat", "te": "బైండింగ్ చక్కగా ఉండాలి"}, {"en": "The cover page should be attractive", "te": "ముఖచిత్రం ఆకర్షణీయంగా ఉండాలి"}, {"en": "The size of letters should be visible", "te": "అక్షరాలు స్పష్టంగా కనిపించాలి"}, {"en": "The content should be logical and meaningful", "te": "విషయం తార్కికంగా, అర్థవంతంగా ఉండాలి"}], "ans": 4, "exp_en": "Mechanical features concern the physical make-up of the book — binding, cover, paper, print and letter size. Logical and meaningful CONTENT is an academic (subject-matter) feature, not a mechanical one.", "exp_te": "యాంత్రిక లక్షణాలు పుస్తకం భౌతిక నిర్మాణానికి సంబంధించినవి — బైండింగ్, కవర్, కాగితం, ముద్రణ, అక్షర పరిమాణం. తార్కికంగా, అర్థవంతంగా ఉండే విషయం అనేది విద్యా (పాఠ్యాంశ) లక్షణం, యాంత్రిక లక్షణం కాదు."}, {"id": 229, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "Choose the correct option.\nA: Evaluation depends on measurement.\nB: Measurement depends on evaluation.", "q_te": "సరైన ఐచ్ఛికాన్ని ఎంచుకోండి.\nA: మూల్యాంకనం మాపనంపై ఆధారపడుతుంది.\nB: మాపనం మూల్యాంకనంపై ఆధారపడుతుంది.", "opts": [{"en": "Both A and B are correct", "te": "A, B రెండూ సరైనవి"}, {"en": "Both A and B are incorrect", "te": "A, B రెండూ సరికావు"}, {"en": "A is correct, B is incorrect", "te": "A సరైనది, B సరికాదు"}, {"en": "A is incorrect, B is correct", "te": "A సరికాదు, B సరైనది"}], "ans": 3, "exp_en": "Measurement only assigns a number (35 out of 50). Evaluation then judges that number against objectives and gives it meaning. So evaluation NEEDS measurement, but measurement can be done without any evaluation. Hence A is correct and B is incorrect. Evaluation is the wider concept: Evaluation = Measurement + value judgement.", "exp_te": "మాపనం కేవలం ఒక సంఖ్యను కేటాయిస్తుంది (50 కి 35). మూల్యాంకనం ఆ సంఖ్యను లక్ష్యాల దృష్ట్యా విలువ కట్టి అర్థాన్ని ఇస్తుంది. కాబట్టి మూల్యాంకనానికి మాపనం అవసరం; కానీ మూల్యాంకనం లేకుండా మాపనం చేయవచ్చు. అందువల్ల A సరైనది, B సరికాదు. మూల్యాంకనం విస్తృత భావన: మూల్యాంకనం = మాపనం + విలువ నిర్ణయం."}, {"id": 230, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The evaluation that occurs during the teaching-learning process is called", "q_te": "బోధనాభ్యసన ప్రక్రియ జరుగుతున్నప్పుడు చేసే మూల్యాంకనం", "opts": [{"en": "Placement evaluation", "te": "స్థాన నిర్ణయ మూల్యాంకనం"}, {"en": "Formative evaluation", "te": "నిర్మాణాత్మక మూల్యాంకనం"}, {"en": "Summative evaluation", "te": "సంగ్రహణాత్మక మూల్యాంకనం"}, {"en": "Diagnostic evaluation", "te": "లోపనిర్ధారణ మూల్యాంకనం"}], "ans": 2, "exp_en": "Formative evaluation goes on WHILE teaching is in progress — oral questions, slip tests, assignments, observation. Its purpose is not to award marks but to give immediate feedback so that teaching can be improved at once.", "exp_te": "రూపణ మూల్యాంకనం బోధన జరుగుతున్న సమయంలోనే జరుగుతుంది — మౌఖిక ప్రశ్నలు, స్లిప్ టెస్టులు, అసైన్‌మెంట్లు, పరిశీలన. దీని ఉద్దేశ్యం మార్కులు ఇవ్వడం కాదు; తక్షణ పునఃపుష్టి ఇచ్చి బోధనను వెంటనే మెరుగుపరచడం."}, {"id": 231, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The type of evaluation used before the teaching-learning process is", "q_te": "బోధనాభ్యసన ప్రక్రియకు ముందు చేసే మూల్యాంకనం", "opts": [{"en": "Placement evaluation", "te": "స్థాన నిర్ణయ మూల్యాంకనం"}, {"en": "Formative evaluation", "te": "నిర్మాణాత్మక మూల్యాంకనం"}, {"en": "Diagnostic evaluation", "te": "లోపనిర్ధారణ మూల్యాంకనం"}, {"en": "Summative evaluation", "te": "సంగ్రహణాత్మక మూల్యాంకనం"}], "ans": 1, "exp_en": "Placement evaluation is done BEFORE teaching begins, to find out the pupils' entry level and previous knowledge so that the teacher knows where to start and how to group them.", "exp_te": "స్థాన నిర్దేశిత మూల్యాంకనం బోధన ప్రారంభానికి ముందే జరుగుతుంది; విద్యార్థుల ప్రవేశ స్థాయిని, పూర్వ జ్ఞానాన్ని తెలుసుకోవడం దీని ఉద్దేశ్యం. దీనివల్ల ఎక్కడ నుండి ప్రారంభించాలి, ఎలా విభజించాలి అని ఉపాధ్యాయునికి తెలుస్తుంది."}, {"id": 232, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The tests used to identify the problems faced by students in a particular area and their solution are", "q_te": "ఒక నిర్దిష్ట అంశంలో విద్యార్థుల సమస్యలను, పరిష్కారాలను గుర్తించే పరీక్షలు", "opts": [{"en": "Achievement tests", "te": "సాధన పరీక్షలు"}, {"en": "Diagnostic tests", "te": "లోపనిర్ధారణ పరీక్షలు"}, {"en": "Aptitude tests", "te": "సహజ సామర్థ్య పరీక్షలు"}, {"en": "Attitude tests", "te": "వైఖరి పరీక్షలు"}], "ans": 2, "exp_en": "Like a doctor's diagnosis, a diagnostic test pinpoints exactly WHERE and WHY a pupil is going wrong in a particular topic, so that remedial teaching can follow. An achievement test only measures how much has been learnt.", "exp_te": "వైద్యుని రోగ నిర్ధారణ వలెనే, లోప నిర్ధారణ పరీక్ష ఒక నిర్దిష్ట అంశంలో విద్యార్థి ఎక్కడ, ఎందుకు తప్పు చేస్తున్నాడో కచ్చితంగా గుర్తిస్తుంది; ఆ తర్వాత నివారణ బోధన చేయవచ్చు. సాధనా పరీక్ష ఎంత నేర్చుకున్నాడో మాత్రమే కొలుస్తుంది."}, {"id": 233, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The type of evaluation in which ‘students evaluate their progress themselves’ is called", "q_te": "‘విద్యార్థులు తమ ప్రగతిని తామే మదింపు చేసుకోవడం’", "opts": [{"en": "Formative evaluation", "te": "నిర్మాణాత్మక మూల్యాంకనం"}, {"en": "Summative evaluation", "te": "సంగ్రహణాత్మక మూల్యాంకనం"}, {"en": "Self evaluation", "te": "స్వీయ మూల్యాంకనం"}, {"en": "Diagnostic evaluation", "te": "లోపనిర్ధారణ మూల్యాంకనం"}], "ans": 3, "exp_en": "In self evaluation the learner himself judges his own progress against the objectives. It builds honesty, self-awareness and responsibility for one's own learning, and is a key part of continuous comprehensive evaluation.", "exp_te": "స్వీయ మూల్యాంకనంలో అభ్యాసకుడే లక్ష్యాల దృష్ట్యా తన ప్రగతిని అంచనా వేసుకుంటాడు. ఇది నిజాయితీ, స్వీయ అవగాహన, తన అభ్యసనంపై బాధ్యతను పెంపొందిస్తుంది; నిరంతర సమగ్ర మూల్యాంకనంలో ఇది కీలక భాగం."}, {"id": 234, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "In the process of evaluation, subject matter, learning experiences and evaluation are three components; the fourth component is", "q_te": "మూల్యాంకన ప్రక్రియలో విషయం, అభ్యసన అనుభవాలు, మూల్యాంకనం మూడు అంశాలు; నాలుగవది", "opts": [{"en": "Educational objectives", "te": "విద్యా లక్ష్యాలు"}, {"en": "Laboratories", "te": "ప్రయోగశాలలు"}, {"en": "Attitudes", "te": "వైఖరులు"}, {"en": "Aptitudes", "te": "సహజ సామర్థ్యాలు"}], "ans": 1, "exp_en": "Educational objectives are the fourth — and indeed the first — component. Everything else flows from them: objectives decide the subject matter, the learning experiences to be provided and what is to be evaluated. This is the well-known evaluation triangle with objectives at its apex.", "exp_te": "నాలుగవ — నిజానికి మొదటి — అంశం విద్యా లక్ష్యాలు. మిగిలినవన్నీ వాటి నుండే వస్తాయి: లక్ష్యాలే విషయాన్ని, కల్పించాల్సిన అభ్యసనానుభవాలను, మూల్యాంకనం చేయవలసిన అంశాలను నిర్ణయిస్తాయి. ఇదే ప్రసిద్ధ మూల్యాంకన త్రిభుజం — దీని శిఖరంలో లక్ష్యాలు ఉంటాయి."}, {"id": 235, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The evaluation used after the completion of some chapters", "q_te": "కొన్ని అధ్యాయాలు పూర్తయిన తర్వాత చేసే మూల్యాంకనం", "opts": [{"en": "Self evaluation", "te": "స్వీయ మూల్యాంకనం"}, {"en": "Formative evaluation", "te": "నిర్మాణాత్మక మూల్యాంకనం"}, {"en": "Summative evaluation", "te": "సంగ్రహణాత్మక మూల్యాంకనం"}, {"en": "Diagnostic evaluation", "te": "లోపనిర్ధారణ మూల్యాంకనం"}], "ans": 3, "exp_en": "Summative evaluation comes at the END of a set of chapters, a term or a year — unit tests, quarterly and annual examinations. It sums up total achievement and is used for grading and promotion.", "exp_te": "సంకలన మూల్యాంకనం కొన్ని అధ్యాయాలు, ఒక సెమిస్టర్ లేదా సంవత్సరం ముగిసిన తర్వాత జరుగుతుంది — యూనిట్ పరీక్షలు, త్రైమాసిక, వార్షిక పరీక్షలు. ఇది మొత్తం సాధనను సంగ్రహిస్తుంది; గ్రేడింగ్, పై తరగతికి పంపడం కోసం వాడతారు."}, {"id": 236, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "In this type of test, the student answers orally the questions asked orally", "q_te": "మౌఖికంగా అడిగిన ప్రశ్నలకు విద్యార్థి మౌఖికంగా జవాబిచ్చే పరీక్ష", "opts": [{"en": "Written tests", "te": "రాత పరీక్షలు"}, {"en": "Summative tests", "te": "సంగ్రహణాత్మక పరీక్షలు"}, {"en": "Rating scales", "te": "రేటింగ్ స్కేళ్ళు"}, {"en": "Oral tests", "te": "మౌఖిక పరీక్షలు"}], "ans": 4, "exp_en": "Oral tests are questions asked and answered by speech. They are quick, allow the teacher to probe further, and are the only way to test pronunciation, fluency and reading — but they take much time for a large class and are harder to score objectively.", "exp_te": "మౌఖిక పరీక్షలలో ప్రశ్నలను, సమాధానాలను మాట రూపంలోనే ఇస్తారు. ఇవి వేగవంతం; ఉపాధ్యాయుడు మరింత లోతుగా ప్రశ్నించవచ్చు; ఉచ్చారణ, ధారాళత, పఠనాన్ని పరీక్షించే ఒకే మార్గం ఇదే. కానీ పెద్ద తరగతికి ఎక్కువ సమయం పడుతుంది, లక్ష్యాత్మకంగా మార్కులు ఇవ్వడం కష్టం."}, {"id": 237, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "This is not a use of multiple choice questions", "q_te": "బహుళైచ్ఛిక ప్రశ్నల ఉపయోగం కానిది", "opts": [{"en": "Questions are objective", "te": "ప్రశ్నలు వస్తునిష్ఠంగా ఉంటాయి"}, {"en": "Importance given to identification", "te": "గుర్తింపుకే ప్రాధాన్యం"}, {"en": "Take less time for scoring", "te": "మార్కులు వేయడానికి తక్కువ సమయం"}, {"en": "Students’ writing skills can be tested", "te": "విద్యార్థుల రాత నైపుణ్యాలను పరీక్షించవచ్చు"}], "ans": 4, "exp_en": "In a multiple choice question the pupil only ticks or marks the right option — he writes nothing of his own. So expression, organisation and handwriting cannot be judged at all; that is a LIMITATION of MCQs, not a use. For testing writing skill, essay type questions are needed.", "exp_te": "బహుళైచ్ఛిక ప్రశ్నలో విద్యార్థి సరైన ఐచ్ఛికాన్ని గుర్తు పెట్టడం మాత్రమే చేస్తాడు — తనంతట తానుగా ఏమీ రాయడు. కాబట్టి అభివ్యక్తి, వ్యవస్థాపన, దస్తూరిని అంచనా వేయలేము; ఇది బహుళైచ్ఛిక ప్రశ్నల పరిమితి, ప్రయోజనం కాదు. రాత నైపుణ్యాన్ని పరీక్షించడానికి వ్యాస రూప ప్రశ్నలు అవసరం."}, {"id": 238, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The teacher chooses a test that fulfils the purpose for which it is meant. Then the characteristic of this test is", "q_te": "ఉద్దేశించిన ప్రయోజనాన్ని నెరవేర్చే పరీక్షను ఉపాధ్యాయుడు ఎంచుకున్నాడు. ఆ పరీక్ష లక్షణం", "opts": [{"en": "Validity", "te": "సప్రమాణత"}, {"en": "Reliability", "te": "విశ్వసనీయత"}, {"en": "Objectivity", "te": "వస్తునిష్ఠత"}, {"en": "Utility", "te": "వినియోగయోగ్యత"}], "ans": 1, "exp_en": "Validity means the test measures exactly WHAT IT IS MEANT TO MEASURE, and nothing else. A test meant to measure problem-solving ability that actually tests only memory would be invalid, however consistent its marks may be.", "exp_te": "సప్రమాణత (Validity) అంటే పరీక్ష ఏది కొలవాలని ఉద్దేశించారో అదే కొలవడం, మరేదీ కొలవకపోవడం. సమస్యా పరిష్కార సామర్థ్యాన్ని కొలవాలని ఉద్దేశించిన పరీక్ష వాస్తవంగా జ్ఞప్తిని మాత్రమే పరీక్షిస్తే, మార్కులు ఎంత స్థిరంగా వచ్చినా అది సప్రమాణం కాదు."}, {"id": 239, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The answer script is evaluated at different times or by different people and the same marks are obtained. Then the test has this characteristic", "q_te": "జవాబు పత్రాన్ని వేర్వేరు సమయాల్లో లేదా వేర్వేరు వ్యక్తులు మూల్యాంకనం చేసినా ఒకే మార్కులు వస్తే ఆ పరీక్ష లక్షణం", "opts": [{"en": "Validity", "te": "సప్రమాణత"}, {"en": "Reliability", "te": "విశ్వసనీయత"}, {"en": "Objectivity", "te": "వస్తునిష్ఠత"}, {"en": "Utility", "te": "వినియోగయోగ్యత"}], "ans": 2, "exp_en": "Reliability means consistency: the test gives the same result again and again, whoever values it and whenever it is valued. Note the relation — a valid test is always reliable, but a reliable test need not be valid.", "exp_te": "విశ్వసనీయత (Reliability) అంటే స్థిరత్వం: ఎవరు దిద్దినా, ఎప్పుడు దిద్దినా పరీక్ష అదే ఫలితాన్ని ఇస్తుంది. సంబంధాన్ని గుర్తుంచుకోండి — సప్రమాణ పరీక్ష ఎప్పుడూ విశ్వసనీయమే; కానీ విశ్వసనీయ పరీక్ష సప్రమాణం కానవసరం లేదు."}, {"id": 240, "sec": "మూల్యాంకనం | Evaluation", "passage": "", "q_en": "The science organisation working in our state for popularising science", "q_te": "మన రాష్ట్రంలో శాస్త్ర ప్రచారం కోసం పనిచేస్తున్న సైన్స్ సంస్థ", "opts": [{"en": "Ekalavya", "te": "ఏకలవ్య"}, {"en": "Jodo Gyan", "te": "జోడో జ్ఞాన్"}, {"en": "Vikramshila", "te": "విక్రమశిల"}, {"en": "Jana Vignana Vedika", "te": "జనవిజ్ఞాన వేదిక"}], "ans": 4, "exp_en": "Jana Vignana Vedika (JVV) is the people's science movement of Andhra Pradesh and Telangana. It spreads scientific temper through science fairs, jathas, magazines and by exposing superstitions. Eklavya (Madhya Pradesh), Jodo Gyan (Delhi) and Vikram Shila (West Bengal) work in other states.", "exp_te": "జన విజ్ఞాన వేదిక (JVV) ఆంధ్రప్రదేశ్, తెలంగాణల ప్రజా విజ్ఞాన ఉద్యమం. సైన్స్ ప్రదర్శనలు, జాతాలు, పత్రికల ద్వారా, మూఢనమ్మకాలను బట్టబయలు చేయడం ద్వారా శాస్త్రీయ దృక్పథాన్ని వ్యాప్తి చేస్తుంది. ఏకలవ్య (మధ్యప్రదేశ్), జోడో జ్ఞాన్ (ఢిల్లీ), విక్రమశిల (పశ్చిమ బెంగాల్) ఇతర రాష్ట్రాలలో పనిచేస్తాయి."}];
